            buildNpcOverrides();

    private ProfileMetricCatalog()
    {
    }

    public static List<ProfileMetric> metricsForLocation(
            String locationName)
    {
        if (locationName == null)
        {
            return Collections.emptyList();
        }

        return BY_LOCATION.getOrDefault(
                locationName.toLowerCase(Locale.ROOT),
                Collections.emptyList());
    }

    public static ContextOverride overrideForNpc(
            String npcName)
    {
        if (npcName == null)
        {
            return null;
        }

        return BY_NPC.get(
                npcName.toLowerCase(Locale.ROOT));
    }

