package com.runetags.hiscores;

import com.google.gson.Gson;

import java.io.IOException;
import java.time.Duration;
import java.time.Instant;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;

import lombok.Value;
import lombok.extern.slf4j.Slf4j;

import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Fetches EHP/EHB profile values from Wise Old Man for Quick-Card hiscores.
 *
 * Requests are lazy. Successful results are cached for ten minutes and negative
 * results briefly to avoid repeated lookups for unavailable or untracked players.
 */
@Slf4j
public class EfficiencyMetricService
{
    private static final String PLAYER_API_URL = "https://api.wiseoldman.net/v2/players";
    private static final Duration SUCCESS_TTL = Duration.ofMinutes(10);
    private static final Duration NEGATIVE_TTL = Duration.ofMinutes(1);

    private final OkHttpClient httpClient;
    private final Gson gson;
    private final Map<String, CacheEntry> cache = new ConcurrentHashMap<>();
    private final Map<String, CompletableFuture<EfficiencyProfileData>> inFlight = new ConcurrentHashMap<>();
    private final Set<Call> activeCalls = ConcurrentHashMap.newKeySet();
    private volatile boolean closed;

    public EfficiencyMetricService(OkHttpClient httpClient, Gson gson)
    {
        this.httpClient = httpClient;
        this.gson = gson;
    }

    public CompletableFuture<EfficiencyProfileData> lookup(String playerName)
    {
        final String key = key(playerName);

        if (closed || key.isEmpty())
        {
            return CompletableFuture.completedFuture(null);
        }

        final CacheEntry cached = cache.get(key);

        if (cached != null)
        {
            if (Instant.now().isBefore(cached.getExpiresAt()))
            {
                return CompletableFuture.completedFuture(cached.getData());
            }

            cache.remove(key, cached);
        }

        return inFlight.computeIfAbsent(key, ignored -> request(playerName.trim(), key));
    }

    public void clear()
    {
        cache.clear();
    }

    public void shutdown()
    {
        closed = true;
        cache.clear();

        for (Call call : activeCalls)
        {
            call.cancel();
        }

        activeCalls.clear();

        for (CompletableFuture<EfficiencyProfileData> future : inFlight.values())
        {
            future.cancel(false);
        }

        inFlight.clear();
    }

    private CompletableFuture<EfficiencyProfileData> request(String playerName, String key)
    {
        final CompletableFuture<EfficiencyProfileData> future = new CompletableFuture<>();
        final HttpUrl baseUrl = HttpUrl.parse(PLAYER_API_URL);

        if (baseUrl == null)
        {
            future.complete(null);
            return future;
        }

        final HttpUrl url = baseUrl.newBuilder().addPathSegment(playerName).build();
        final Request request = new Request.Builder()
                .url(url)
                .header("Accept", "application/json")
                .header("User-Agent", "RuneTags RuneLite plugin")
                .build();

        final Call call = httpClient.newCall(request);
        activeCalls.add(call);

        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call failedCall, IOException exception)
            {
                activeCalls.remove(failedCall);
                complete(key, future, null, NEGATIVE_TTL);

                //log.debug("[RuneTags][WOM] Efficiency Lookup Failed for Player='{}' | ERROR: {}", playerName, exception.getMessage());
            }

            @Override
            public void onResponse(Call completedCall, Response response)
            {
                activeCalls.remove(completedCall);
                EfficiencyProfileData data = null;

                try (Response closedResponse = response)
                {
                    if (!closedResponse.isSuccessful())
                    {
                        //log.debug("[RuneTags][WOM] Efficiency Lookup for Player='{}' returned HTTP {}", playerName, closedResponse.code());
                        return;
                    }

                    final ResponseBody body = closedResponse.body();

                    if (body == null)
                    {
                        return;
                    }

                    final WiseOldManPlayer responseData = gson.fromJson(body.charStream(), WiseOldManPlayer.class);

                    if (responseData != null)
                    {
                        data = new EfficiencyProfileData(valid(responseData.getEhp()), valid(responseData.getEhb()));

                        if (data.getEhp() == null && data.getEhb() == null)
                        {
                            data = null;
                        }
                    }
                }
                catch (RuntimeException exception)
                {
                    log.debug("[RuneTags][WOM] Unable to Parse Efficiency Response for Player='{}' | ERROR: {}", playerName, exception.getMessage());
                }
                finally
                {
                    complete(key, future, data, data != null ? SUCCESS_TTL : NEGATIVE_TTL);
                }
            }
        });

        return future;
    }

    private void complete(
            String key,
            CompletableFuture<EfficiencyProfileData> future,
            EfficiencyProfileData data,
            Duration ttl)
    {
        if (!closed)
        {
            cache.put(key, new CacheEntry(data, Instant.now().plus(ttl)));
        }

        inFlight.remove(key, future);
        future.complete(data);
    }

    private static Double valid(Double value)
    {
        return value != null && Double.isFinite(value) && value >= 0d ? value : null;
    }

    private static String key(String playerName)
    {
        if (playerName == null)
        {
            return "";
        }

        return playerName.trim()
                .replace('_', ' ')
                .replace('-', ' ')
                .replaceAll("\\s+", " ")
                .toLowerCase(Locale.ROOT);
    }

    @Value
    private static class CacheEntry
    {
        EfficiencyProfileData data;
        Instant expiresAt;
    }

    @Value
    private static class WiseOldManPlayer
    {
        Double ehp;
        Double ehb;
    }
}

package com.runetags.hiscores;

import com.runetags.player.AccountType;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;

import lombok.extern.slf4j.Slf4j;

import net.runelite.api.Experience;
import net.runelite.client.hiscore.HiscoreClient;
import net.runelite.client.hiscore.HiscoreEndpoint;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;
import net.runelite.client.hiscore.Skill;

@Slf4j
public class HiscoreEnrichmentService
{
    private final HiscoreClient hiscoreClient;
    private final HiscoreEnrichmentCache cache;

    private final Map<
            String,
            CompletableFuture<HiscoreEnrichmentCache.CachedProfileEnrichment>>
            inFlight = new ConcurrentHashMap<>();

    private CompletableFuture<AccountType> detectAccountType(String playerName)
    {
        /*
         * The individual HiScore endpoints can positively identify the three solo
         * Ironman variants. Absence from those tables cannot safely distinguish a
         * normal account from Group Ironman, so leave that case UNKNOWN.
         */
        return safeLookup(
                playerName,
                HiscoreEndpoint.IRONMAN)
                .thenCompose(
                        ironmanResult ->
                        {
                            if (ironmanResult == null)
                            {
                                return CompletableFuture.completedFuture(
                                        AccountType.UNKNOWN);
                            }

                            final CompletableFuture<HiscoreResult> hardcoreFuture =
                                    safeLookup(
                                            playerName,
                                            HiscoreEndpoint.HARDCORE_IRONMAN);

                            final CompletableFuture<HiscoreResult> ultimateFuture =
                                    safeLookup(
                                            playerName,
                                            HiscoreEndpoint.ULTIMATE_IRONMAN);

                            return hardcoreFuture.thenCombine(
                                    ultimateFuture,
                                    (hardcoreResult, ultimateResult) ->
                                    {
                                        if (hardcoreResult != null)
                                        {
                                            return AccountType.HARDCORE;
                                        }

                                        if (ultimateResult != null)
                                        {
                                            return AccountType.ULTIMATE;
                                        }

                                        return AccountType.IRONMAN;
                                    });
                        });
    }

    private CompletableFuture<HiscoreResult> safeLookup(
            String playerName,
            HiscoreEndpoint endpoint)
    {
        try
        {
            final CompletableFuture<HiscoreResult> future =
                    hiscoreClient.lookupAsync(
                            playerName,
                            endpoint);

            if (future == null)
            {
                return CompletableFuture.completedFuture(
                        null);
            }

            return future.handle(
                    (result, throwable) ->
                            throwable == null
                                    ? result
                                    : null);
        }
        catch (RuntimeException ex)
        {
            return CompletableFuture.completedFuture(
                    null);
        }
    }

    @lombok.Value
    private static class BaseLookupResult
    {
        HiscoreResult result;
        Throwable throwable;
    }

    private static Integer calculateCombatLevel(
            HiscoreResult result)
    {
        final Skill attack =
                result.getSkill(HiscoreSkill.ATTACK);

        final Skill strength =
                result.getSkill(HiscoreSkill.STRENGTH);

        final Skill defence =
                result.getSkill(HiscoreSkill.DEFENCE);

        final Skill hitpoints =
                result.getSkill(HiscoreSkill.HITPOINTS);

        final Skill magic =
                result.getSkill(HiscoreSkill.MAGIC);

        final Skill ranged =
                result.getSkill(HiscoreSkill.RANGED);

        final Skill prayer =
                result.getSkill(HiscoreSkill.PRAYER);

        if (attack == null
                || strength == null
                || defence == null
                || hitpoints == null
                || magic == null
                || ranged == null
                || prayer == null)
        {
            return null;
        }

        if (attack.getLevel() < 1
                || strength.getLevel() < 1
                || defence.getLevel() < 1
                || hitpoints.getLevel() < 1
                || magic.getLevel() < 1
                || ranged.getLevel() < 1
                || prayer.getLevel() < 1)
        {
            return null;
        }

        return Experience.getCombatLevel(
                attack.getLevel(),
                strength.getLevel(),
                defence.getLevel(),
                hitpoints.getLevel(),
                magic.getLevel(),
                ranged.getLevel(),
                prayer.getLevel());
    }

    public HiscoreEnrichmentService(
            HiscoreClient hiscoreClient,
            HiscoreEnrichmentCache cache)
    {
        this.hiscoreClient = hiscoreClient;
        this.cache = cache;
    }

    public EnrichmentRequest enrich(
            String playerName)
    {
        final String requestKey =
                HiscoreEnrichmentCache.key(
                        playerName);

        if (requestKey.isEmpty())
        {
            return EnrichmentRequest.failed();
        }

        final HiscoreEnrichmentCache.CachedProfileEnrichment cached =
                cache.get(playerName)
                        .orElse(null);

        if (cached != null)
        {
            return EnrichmentRequest.cached(
                    cached);
        }

        /*
         * Synchronize request creation so concurrent callers cannot start duplicate
         * HiScore lookups for the same normalized player. The lock covers only
         * creation and bookkeeping; network work remains asynchronous.
         */
        synchronized (inFlight)
        {
            /*
             * Re-check the cache after obtaining the lock. A request that was
             * already completing while this caller waited may have populated it.
             */
            final HiscoreEnrichmentCache.CachedProfileEnrichment cachedAfterLock =
                    cache.get(playerName)
                            .orElse(null);

            if (cachedAfterLock != null)
            {
                return EnrichmentRequest.cached(
                        cachedAfterLock);
            }

            final CompletableFuture<
                    HiscoreEnrichmentCache.CachedProfileEnrichment>
                    existing =
                    inFlight.get(
                            requestKey);

            if (existing != null)
            {
                return EnrichmentRequest.loading(
                        existing);
            }

            final CompletableFuture<HiscoreResult> normalFuture;

            try
            {
                normalFuture =
                        hiscoreClient.lookupAsync(
                                playerName,
                                HiscoreEndpoint.NORMAL);
            }
            catch (RuntimeException ex)
            {
                log.debug("[RuneTags][HiScore] Unable to Start Lookup for Player='{}'", playerName, ex);

                return EnrichmentRequest.failed();
            }

            if (normalFuture == null)
            {
                return EnrichmentRequest.failed();
            }

            final CompletableFuture<AccountType> accountTypeFuture =
                    detectAccountType(
                            playerName);

            final CompletableFuture<
                    HiscoreEnrichmentCache.CachedProfileEnrichment>
                    mapped =
                    normalFuture.handle(
                                    (result, throwable) ->
                                    {
                                        if (throwable != null)
                                        {
                                            log.debug("[RuneTags][HiScore] Lookup Failed for Player='{}' | ERROR: {}", playerName, throwable.getMessage());

                                            return new BaseLookupResult(
                                                    null,
                                                    throwable);
                                        }

                                        return new BaseLookupResult(
                                                result,
                                                null);
                                    })
                            .thenCombine(
                                    accountTypeFuture,
                                    (baseLookup, accountType) ->
                                    {
                                        if (baseLookup.getThrowable() != null)
                                        {
                                            return new HiscoreEnrichmentCache.CachedProfileEnrichment(
                                                    HiscoreEnrichmentState.ERROR,
                                                    null);
                                        }

                                        final HiscoreResult result =
                                                baseLookup.getResult();

                                        if (result == null)
                                        {
                                            cache.putNotFound(
                                                    playerName);

                                            return new HiscoreEnrichmentCache.CachedProfileEnrichment(
                                                    HiscoreEnrichmentState.NOT_FOUND,
                                                    null);
                                        }

                                        final Skill overall =
                                                result.getSkill(
                                                        HiscoreSkill.OVERALL);

                                        final Integer totalLevel =
                                                overall != null
                                                        && overall.getLevel() >= 0
                                                        ? overall.getLevel()
                                                        : null;

                                        final Integer combatLevel =
                                                calculateCombatLevel(
                                                        result);

                                        final Map<String, Integer> contextValues =
                                                new LinkedHashMap<>();

                                        for (HiscoreSkill hiscoreSkill
                                                : HiscoreSkill.values())
                                        {
                                            if (hiscoreSkill.getType()
                                                    != HiscoreSkillType.BOSS
                                                    && hiscoreSkill.getType()
                                                    != HiscoreSkillType.ACTIVITY
                                                    && hiscoreSkill.getType()
                                                    != HiscoreSkillType.SKILL)
                                            {
                                                continue;
                                            }

                                            final Skill skill =
                                                    result.getSkill(
                                                            hiscoreSkill);

                                            if (skill == null
                                                    || skill.getLevel() < 0)
                                            {
                                                continue;
                                            }

                                            contextValues.put(
                                                    hiscoreSkill.name(),
                                                    skill.getLevel());
                                        }

                                        final HiscoreProfileData data =
                                                new HiscoreProfileData(
                                                        combatLevel,
                                                        totalLevel,
                                                        accountType,
                                                        contextValues);

                                        cache.putSuccess(
                                                playerName,
                                                data);

                                        return new HiscoreEnrichmentCache.CachedProfileEnrichment(
                                                HiscoreEnrichmentState.LOADED,
                                                data);
                                    });

            inFlight.put(
                    requestKey,
                    mapped);

            mapped.whenComplete(
                    (result, throwable) ->
                            inFlight.remove(
                                    requestKey,
                                    mapped));

            return EnrichmentRequest.loading(
                    mapped);
        }
    }

    @lombok.Value
    public static class EnrichmentRequest
    {
        HiscoreEnrichmentState initialState;
        HiscoreProfileData initialData;
        CompletableFuture<HiscoreEnrichmentCache.CachedProfileEnrichment> future;

        static EnrichmentRequest cached(
                HiscoreEnrichmentCache.CachedProfileEnrichment cached)
        {
            return new EnrichmentRequest(
                    cached.getState(),
                    cached.getData(),
                    null);
        }

        static EnrichmentRequest loading(
                CompletableFuture<HiscoreEnrichmentCache.CachedProfileEnrichment> future)
        {
            return new EnrichmentRequest(
                    HiscoreEnrichmentState.LOADING,
                    null,
                    future);
        }

        static EnrichmentRequest failed()
        {
            return new EnrichmentRequest(
                    HiscoreEnrichmentState.ERROR,
                    null,
                    null);
        }
    }
}

package com.runetags.hiscores;

public enum HiscoreEnrichmentState
{
    LOCAL,
    LOADING,
    LOADED,
    NOT_FOUND,
    ERROR
}

package com.runetags.hiscores;

import lombok.Value;

@Value
public class EfficiencyProfileData
{
    Double ehp;
    Double ehb;
}

package com.runetags.hiscores;

import com.runetags.Configurations;
import com.runetags.config.LookupProvider;

import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;

import lombok.extern.slf4j.Slf4j;

import net.runelite.client.util.LinkBrowser;

@Slf4j
public class PlayerLookupService
{
    private final Configurations config;

    public PlayerLookupService(Configurations config)
    {
        this.config = config;
    }

    public void lookup(String playerName)
    {
        if (playerName == null || playerName.trim().isEmpty())
        {
            return;
        }

        final LookupProvider provider =
                config.lookupProvider();

        switch (provider)
        {
            case WISE_OLD_MAN:
                openWiseOldMan(playerName);
                break;

            case RUNE_PROFILE:
                openRuneProfile(playerName);
                break;

            case HISCORES:
            default:
                openHiscores(playerName);
                break;
        }

        //log.debug("[RuneTags][Lookup] Player='{}' | Provider={}", playerName, provider);
    }

    private static void openWiseOldMan(String playerName)
    {
        LinkBrowser.browse(
                "https://wiseoldman.net/players/"
                        + encodePath(playerName));
    }

    private static void openRuneProfile(String playerName)
    {
        LinkBrowser.browse(
                "https://runeprofile.com/"
                        + encodePath(playerName));
    }

    private static void openHiscores(String playerName)
    {
        LinkBrowser.browse(
                "https://secure.runescape.com/m=hiscore_oldschool/hiscorepersonal?user1="
                        + encodeQuery(playerName));
    }

    private static String encodePath(String value)
    {
        /*
         * URLEncoder emits '+' for spaces;
         * path segments require percent-encoded spaces.
         */
        return URLEncoder.encode(
                        value.trim(),
                        StandardCharsets.UTF_8)
                .replace("+", "%20");
    }

    private static String encodeQuery(String value)
    {
        return URLEncoder.encode(
                value.trim(),
                StandardCharsets.UTF_8);
    }
}

package com.runetags.chat;

import com.runetags.Configurations;
import com.runetags.config.MentionFont;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.FontTypeFace;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.widgets.Widget;

/**
 * Coordinates native chat construction for RuneTags mention fonts.
 *
 * Responsibilities:
 *
 * PRE-CONSTRUCTION:
 *
 * - identify RuneTags messages which require a custom font;
 * - measure native/custom wrapping;
 * - adjust RuneScape's native row allocation before construction.
 *
 * END OF CLIENT TICK:
 *
 * - coalesce every row reconstruction into one final font synchronization;
 * - apply FontId only after RuneScape has completed clientscript execution.
 *
 * ReferenceLayoutService remains authoritative for semantic
 * message -> physical-widget ownership and actual FontId mutation.
 *
 * ---------------------------------------------------------------------
 * CONSTRUCTION PATHS
 * ---------------------------------------------------------------------
 *
 * Script 203:
 *
 * - Public chat
 * - Friends Chat
 * - normal-chatbox private messages
 * - Split Private messages
 *
 * Script 4483:
 *
 * - Clan Chat
 * - Guest Clan Chat
 *
 * Both expose the same trailing eleven-value row-construction payload.
 * 4483 simply has three additional leading values.
 *
 * Relevant values are therefore addressed relative to intStackSize:
 *
 *     size - 10 -> LINE widget ID
 *     size - 9  -> parent widget ID
 *     size - 8  -> right boundary
 *     size - 7  -> left boundary
 *     size - 6  -> native vertical/line-height input
 *
 * ---------------------------------------------------------------------
 * HEIGHT MODEL
 * ---------------------------------------------------------------------
 *
 * RuneScape first wraps using its native Plain-12 font.
 *
 * RuneTags may subsequently replace that font with Bold or Verdana.
 *
 * We calculate:
 *
 *     nativeLines
 *         number of lines Font 495 requires
 *
 *     customLines
 *         number of lines the configured RuneTags font requires
 *
 *     nativeLineHeight
 *         the value RuneScape itself supplied at PRE construction
 *
 *     desiredHeight
 *         customLines * nativeLineHeight
 *
 * Because the construction script itself multiplies its supplied vertical
 * value by its native wrapped-line count:
 *
 *     injectedValue =
 *         ceil(desiredHeight / nativeLines)
 *
 * This preserves RuneScape's native cadence automatically:
 *
 *     normal chatbox currently supplies 14
 *     Split Private currently supplies 13
 *
 * No surface-specific height is hardcoded.
 */
public class FontLayoutService
{
    private static final int CHAT_BODY_SCRIPT = 203;
    private static final int CLAN_BODY_SCRIPT = 4483;

    private static final int BODY_GAP = 3;

    private final Client client;
    private final Configurations config;
    private final TaggedMessageRepository repository;
    private final ReferenceLayoutService referenceLayoutService;

    /*
     * Multiple 203 / 4483 constructors may execute during one client tick.
     *
     * They all collapse into one final semantic -> physical font synchronization
     * at PostClientTick.
     */
    private boolean fontsDirty;

    /*
     * RuneTags only measures a very small fixed set of fonts.
     *
     * Resolve each FontTypeFace once rather than temporarily changing
     * CHATBOX_INPUT for every reconstructed row.
     */
    private final Map<Integer, FontTypeFace> fontCache =
            new HashMap<>();

    public FontLayoutService(
            Client client,
            Configurations config,
            TaggedMessageRepository repository,
            ReferenceLayoutService referenceLayoutService)
    {
        this.client = client;
        this.config = config;
        this.repository = repository;
        this.referenceLayoutService = referenceLayoutService;
    }

    /**
     * Request one final font synchronization at the end of the current client tick.
     *
     * Repeated requests are intentionally coalesced into one boolean state.
     */
    public void markFontsDirty()
    {
        fontsDirty = true;
    }

    /**
     * Synchronize fonts only when native chat construction or semantic chat state
     * changed during this client tick.
     *
     * PostClientTick occurs after clientscript execution, so physical chat widgets
     * have reached their final ownership positions before RuneTags mutates them.
     *
     * @return true when this call performed an actual font synchronization;
     *         false when the font state was already clean
     */
    public boolean onPostClientTick()
    {
        if (!fontsDirty)
        {
            return false;
        }

        /*
         * Clear first so any future construction creates a new request rather than
         * being swallowed by the current synchronization.
         */
        fontsDirty = false;

        referenceLayoutService.syncMentionFonts();

        return true;
    }

    /**
     * Intercept only the native row-construction scripts supported by RuneTags.
     */
    public void onScriptPreFired(
            ScriptPreFired event)
    {
        if (event == null
                || !isSupportedConstructionScript(
                event.getScriptId()))
        {
            return;
        }

        /*
         * Any native chat-row reconstruction can recycle a physical Widget which
         * previously carried RuneTags presentation.
         *
         * Mark both font ownership and Favorite sender-color ownership dirty even
         * when this particular row is ordinary. One PostClientTick synchronization
         * will resolve all rows after the entire reconstruction sequence has
         * completed.
         */
        markFontsDirty();

        referenceLayoutService.markFavoriteSenderRowsDirty();

        final Object[] objectStack =
                client.getObjectStack();

        final int objectStackSize =
                client.getObjectStackSize();

        /*
         * Use one semantic repository snapshot for the complete construction attempt
         * so body and message resolution operate on the same retained state.
         */
        final List<TaggedMessage> messages =
                repository.snapshot();

        if (messages.isEmpty())
        {
            return;
        }

        final String rawBody =
                findBody(
                        objectStack,
                        objectStackSize,
                        messages);

        if (rawBody == null)
        {
            return;
        }

        final String semanticBody =
                ChatText.toSemanticPlain(
                        rawBody);

        if (semanticBody == null
                || semanticBody.isEmpty())
        {
            return;
        }

        /*
         * Do not alter unrelated RuneScape messages.
         *
         * Only a TaggedMessage which RuneTags itself recognized as containing
         * a reference/local mention qualifies for mention-font treatment.
         */
        final TaggedMessage taggedMessage =
                findTaggedMessage(
                        semanticBody,
                        objectStack,
                        objectStackSize,
                        messages);

        if (taggedMessage == null
                || !hasMentionFontTreatment(
                taggedMessage))
        {
            return;
        }

        final MentionFont mentionFont =
                config.fontMentions();

        /*
         * NORMAL requires no compensation.
         *
         * RuneScape is already constructing the row with its native font and
         * native height.
         */
        if (mentionFont == null
                || mentionFont == MentionFont.NORMAL)
        {
            return;
        }

        final int[] intStack =
                client.getIntStack();

        final int intStackSize =
                client.getIntStackSize();

        /*
         * Both known construction scripts expose the same trailing
         * eleven-value payload.
         */
        if (intStack == null
                || intStackSize < 11
                || intStackSize > intStack.length)
        {
            return;
        }

        final int lineWidgetIndex =
                intStackSize - 10;

        final int rightBoundaryIndex =
                intStackSize - 8;

        final int verticalValueIndex =
                intStackSize - 6;

        final int lineWidgetId =
                intStack[lineWidgetIndex];

        final int rightBoundary =
                intStack[rightBoundaryIndex];

        /*
         * Preserve RuneScape's native vertical value rather than choosing a
         * surface-specific line height.
         */
        final int nativeLineHeight =
                intStack[verticalValueIndex];

        if (nativeLineHeight <= 0)
        {
            return;
        }

        final Widget lineWidget =
                client.getWidget(
                        lineWidgetId);

        if (lineWidget == null)
        {
            return;
        }

        final FontTypeFace nativeFont =
                resolveFont(
                        FontID.PLAIN_12);

        final int selectedFontId =
                fontIdFor(
                        mentionFont);

        final FontTypeFace selectedFont =
                resolveFont(
                        selectedFontId);

        if (nativeFont == null
                || selectedFont == null)
        {
            return;
        }

        /*
         * Determine how much horizontal space RuneScape has actually left for
         * the message body.
         */
        final PrefixMeasurement prefix =
                measurePrefix(
                        event.getScriptId(),
                        nativeFont,
                        objectStack,
                        objectStackSize,
                        semanticBody,
                        intStack,
                        intStackSize);

        if (prefix == null)
        {
            return;
        }

        final int bodyX =
                lineWidget.getOriginalX()
                        + prefix.width
                        + BODY_GAP;

        final int bodyWidth =
                rightBoundary
                        - bodyX;

        if (bodyWidth <= 0)
        {
            return;
        }

        /*
         * Reuse ReferenceLayoutService's existing wrapping engine.
         *
         * Do not maintain a second approximation here.
         */
        final int nativeLines =
                referenceLayoutService.measureWrappedLineCount(
                        rawBody,
                        nativeFont,
                        bodyWidth);

        final int customLines =
                referenceLayoutService.measureWrappedLineCount(
                        rawBody,
                        selectedFont,
                        bodyWidth);

        if (nativeLines <= 0
                || customLines <= 0)
        {
            return;
        }

        final int desiredHeight =
                customLines
                        * nativeLineHeight;

        final int injectedValue =
                ceilDiv(
                        desiredHeight,
                        nativeLines);

        if (injectedValue <= 0)
        {
            return;
        }

        /*
         * Mutate only the native construction argument.
         *
         * Do NOT:
         *
         * - resize the created Widget afterward;
         * - move rows manually;
         * - change Y coordinates;
         * - call revalidate here.
         *
         * RuneScape receives the correct native allocation before it constructs
         * and positions the row.
         */
        if (intStack[verticalValueIndex]
                != injectedValue)
        {
            intStack[verticalValueIndex] =
                    injectedValue;
        }
    }

    private boolean isSupportedConstructionScript(
            int scriptId)
    {
        return scriptId
                == CHAT_BODY_SCRIPT
                || scriptId
                == CLAN_BODY_SCRIPT;
    }

    /**
     * Font treatment belongs only to a message which contains a RuneTags
     * PlayerReference or matched the local player.
     *
     * This mirrors ReferenceLayoutService.applyMentionFont().
     */
    private boolean hasMentionFontTreatment(
            TaggedMessage message)
    {
        if (message == null)
        {
            return false;
        }

        final boolean hasPlayerReference =
                message.getReferences() != null
                        && !message.getReferences().isEmpty();

        final boolean hasLocalMention =
                message.getLocalMentionMatch() != null
                        && message.getLocalMentionMatch()
                        .isMatchesLocalPlayer();

        return hasPlayerReference
                || hasLocalMention;
    }

    /**
     * Resolve the TaggedMessage represented by this construction call.
     *
     * Newest messages are preferred because chat reconstruction is
     * newest-first and identical body text can legitimately occur multiple
     * times.
     *
     * Sender/prefix matching is used when possible to disambiguate identical
     * message bodies across players/channels.
     */
    private TaggedMessage findTaggedMessage(
            String semanticBody,
            Object[] objectStack,
            int objectStackSize,
            List<TaggedMessage> messages)
    {
        if (messages == null
                || messages.isEmpty())
        {
            return null;
        }

        TaggedMessage bodyFallback =
                null;

        for (int i = messages.size() - 1;
             i >= 0;
             i--)
        {
            final TaggedMessage message =
                    messages.get(
                            i);

            if (message == null
                    || message.getOriginalMessage() == null
                    || !message.getOriginalMessage()
                    .equals(
                            semanticBody))
            {
                continue;
            }

            if (!hasMentionFontTreatment(
                    message))
            {
                continue;
            }

            /*
             * Preserve the newest semantic body match as a fallback.
             */
            if (bodyFallback == null)
            {
                bodyFallback =
                        message;
            }

            final String sender =
                    message.getCanonicalSender();

            if (sender == null
                    || sender.isEmpty())
            {
                return message;
            }

            if (prefixContainsSender(
                    objectStack,
                    objectStackSize,
                    semanticBody,
                    sender))
            {
                return message;
            }
        }

        return bodyFallback;
    }

    private boolean prefixContainsSender(
            Object[] stack,
            int size,
            String semanticBody,
            String sender)
    {
        if (stack == null
                || size <= 0
                || sender == null
                || sender.isEmpty())
        {
            return false;
        }

        final String comparableSender =
                comparable(
                        sender);

        final int safeSize =
                Math.min(
                        size,
                        stack.length);

        for (int i = 0;
             i < safeSize;
             i++)
        {
            final Object value =
                    stack[i];

            if (!(value instanceof String))
            {
                continue;
            }

            final String raw =
                    (String) value;

            final String semantic =
                    ChatText.toSemanticPlain(
                            raw);

            if (semantic == null
                    || semantic.equals(
                    semanticBody))
            {
                continue;
            }

            final String comparablePrefix =
                    comparable(
                            semantic);

            if (comparablePrefix.contains(
                    comparableSender))
            {
                return true;
            }
        }

        return false;
    }

    /**
     * Locate the rendered body argument on the current script object stack.
     *
     * We identify it semantically by matching against RuneTags' retained
     * TaggedMessageRepository rather than by assuming a fixed object-stack
     * position.
     */
    private String findBody(
            Object[] stack,
            int size,
            List<TaggedMessage> messages)
    {
        if (stack == null
                || size <= 0
                || messages == null
                || messages.isEmpty())
        {
            return null;
        }

        final int safeSize =
                Math.min(
                        size,
                        stack.length);

        for (int i = safeSize - 1;
             i >= 0;
             i--)
        {
            final Object value =
                    stack[i];

            if (!(value instanceof String))
            {
                continue;
            }

            final String raw =
                    (String) value;

            final String semantic =
                    ChatText.toSemanticPlain(
                            raw);

            if (semantic == null
                    || semantic.isEmpty())
            {
                continue;
            }

            for (int messageIndex = messages.size() - 1;
                 messageIndex >= 0;
                 messageIndex--)
            {
                final TaggedMessage message =
                        messages.get(
                                messageIndex);

                if (message == null
                        || message.getOriginalMessage() == null)
                {
                    continue;
                }

                if (message.getOriginalMessage()
                        .equals(
                                semantic))
                {
                    return raw;
                }
            }
        }

        return null;
    }

    /**
     * Determine the rendered prefix width immediately preceding the body.
     *
     * Script 203 supplies one complete prefix String:
     *
     *     Santa:
     *     [Nerds] Santa:
     *     To Player:
     *
     * Script 4483 supplies Clan/Guest-Clan components separately:
     *
     *     [Clan]
     *     Santa:
     *     body
     *
     * plus the small account/channel decoration represented by its leading
     * dimensions.
     */
    private PrefixMeasurement measurePrefix(
            int scriptId,
            FontTypeFace nativeFont,
            Object[] objectStack,
            int objectStackSize,
            String semanticBody,
            int[] intStack,
            int intStackSize)
    {
        final List<String> components =
                findPrefixComponents(
                        objectStack,
                        objectStackSize,
                        semanticBody);

        if (components.isEmpty())
        {
            return null;
        }

        if (scriptId == CHAT_BODY_SCRIPT)
        {
            /*
             * All observed 203 calls provide the complete rendered prefix as
             * one String immediately before the body.
             *
             * Preserve markup so <img=...>, colors, timestamps, etc. can
             * contribute their real FontTypeFace width.
             */
            final String rawPrefix =
                    normalizeRawForMeasurement(
                            components.get(
                                    components.size() - 1));

            return new PrefixMeasurement(
                    nativeFont.getTextWidth(
                            rawPrefix));
        }

        if (scriptId == CLAN_BODY_SCRIPT)
        {
            /*
             * 4483 gives us multiple textual prefix components.
             */
            final StringBuilder prefixText =
                    new StringBuilder();

            for (int i = 0;
                 i < components.size();
                 i++)
            {
                if (i > 0)
                {
                    prefixText.append(
                            ' ');
                }

                prefixText.append(
                        normalizeRawForMeasurement(
                                components.get(
                                        i)));
            }

            final int textWidth =
                    nativeFont.getTextWidth(
                            prefixText.toString());

            int decorationWidth =
                    0;

            /*
             * Script 4483 exposes a 13 x 13 decoration whose rendered horizontal
             * contribution is 12px.
             *
             * Keep that channel-specific adjustment isolated here.
             */
            final int commonPayloadStart =
                    intStackSize - 11;

            if (commonPayloadStart >= 3)
            {
                final int widthCandidate =
                        intStack[1];

                final int heightCandidate =
                        intStack[2];

                if (widthCandidate > 0
                        && widthCandidate <= 32
                        && heightCandidate > 0
                        && heightCandidate <= 32)
                {
                    decorationWidth =
                            Math.max(
                                    0,
                                    widthCandidate - 1);
                }
            }

            return new PrefixMeasurement(
                    textWidth
                            + decorationWidth);
        }

        return null;
    }

    /**
     * Collect every String preceding the semantic body.
     */
    private List<String> findPrefixComponents(
            Object[] stack,
            int size,
            String semanticBody)
    {
        final List<String> output =
                new ArrayList<>();

        if (stack == null
                || size <= 0
                || semanticBody == null)
        {
            return output;
        }

        final int safeSize =
                Math.min(
                        size,
                        stack.length);

        for (int i = 0;
             i < safeSize;
             i++)
        {
            final Object value =
                    stack[i];

            if (!(value instanceof String))
            {
                continue;
            }

            final String raw =
                    (String) value;

            final String semantic =
                    ChatText.toSemanticPlain(
                            raw);

            if (semantic == null)
            {
                continue;
            }

            if (semantic.equals(
                    semanticBody))
            {
                break;
            }

            output.add(
                    raw);
        }

        return output;
    }

    /**
     * Resolve an actual Jagex FontTypeFace for an arbitrary FontID.
     *
     * The chat-input widget is used only as a temporary font probe.
     * Its original FontId is immediately restored and no revalidation occurs.
     */
    private FontTypeFace resolveFont(
            int fontId)
    {
        final FontTypeFace cached =
                fontCache.get(
                        fontId);

        if (cached != null)
        {
            return cached;
        }

        final Widget probe =
                client.getWidget(InterfaceID.Chatbox.INPUT);

        if (probe == null)
        {
            return null;
        }

        final int originalFontId =
                probe.getFontId();

        try
        {
            probe.setFontId(
                    fontId);

            final FontTypeFace resolved =
                    probe.getFont();

            if (resolved != null)
            {
                fontCache.put(
                        fontId,
                        resolved);
            }

            return resolved;
        }
        finally
        {
            probe.setFontId(
                    originalFontId);
        }
    }

    private int fontIdFor(
            MentionFont font)
    {
        if (font == null)
        {
            return FontID.PLAIN_12;
        }

        switch (font)
        {
            case BOLD:
                return FontID.BOLD_12;

            case VERDANA:
                return FontID.VERDANA_13_BOLD;

            case NORMAL:
            default:
                return FontID.PLAIN_12;
        }
    }

    private int ceilDiv(
            int numerator,
            int denominator)
    {
        if (denominator <= 0)
        {
            return numerator;
        }

        return (numerator
                + denominator
                - 1)
                / denominator;
    }

    private String normalizeRawForMeasurement(
            String value)
    {
        if (value == null)
        {
            return "";
        }

        return value
                .replace('\u00A0', ' ')
                .replace('\u202F', ' ');
    }

    private String comparable(
            String value)
    {
        if (value == null)
        {
            return "";
        }

        return value
                .replace('\u00A0', ' ')
                .replace('\u202F', ' ')
                .toLowerCase();
    }

    private static final class PrefixMeasurement
    {
        private final int width;

        private PrefixMeasurement(
                int width)
        {
            this.width =
                    width;
        }
    }
}

package com.runetags.chat;

import java.awt.Point;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Optional;

public class ChatHitboxRegistry
{
    private volatile List<ReferenceHitbox> hitboxes = Collections.emptyList();

    public void replace(List<ReferenceHitbox> newHitboxes)
    {
        hitboxes = Collections.unmodifiableList(new ArrayList<>(newHitboxes));
    }

    public Optional<ReferenceHitbox> find(Point point)
    {
        for (ReferenceHitbox hitbox : hitboxes)
        {
            if (hitbox.contains(point))
            {
                return Optional.of(hitbox);
            }
        }

        return Optional.empty();
    }

    public List<ReferenceHitbox> snapshot()
    {
        return hitboxes;
    }

    public void clear()
    {
        hitboxes = Collections.emptyList();
    }
}

package com.runetags.chat;

import net.runelite.client.util.Text;

public final class ChatText
{
    private ChatText() {}

    public static String toSemanticPlain(String raw)
    {
        if (raw == null || raw.isEmpty())
        {
            return "";
        }

        String protectedText = raw.replace("<at>", "\u0001");
        return Text.removeTags(protectedText).replace('\u0001', '@');
    }
}

package com.runetags.chat;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.EnumMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Optional;

import net.runelite.api.ChatMessageType;

/**
 * Runtime semantic storage for RuneTags chat messages.
 *
 * Retention is enforced independently per ChatMessageType because RuneScape
 * retains separate histories for different message types. Traffic in one type
 * must not evict a still-retained record from another.
 *
 * The master deque remains globally chronological so snapshot() exposes one
 * ordered semantic stream.
 */
public class TaggedMessageRepository
{
    private final int capacityPerType;

    private final Deque<TaggedMessage> messages =
            new ArrayDeque<>();

    private final Map<ChatMessageType, Integer> countsByType =
            new EnumMap<>(
                    ChatMessageType.class);

    public TaggedMessageRepository(
            int capacityPerType)
    {
        if (capacityPerType < 1)
        {
            throw new IllegalArgumentException(
                    "capacityPerType must be >= 1");
        }

        this.capacityPerType =
                capacityPerType;
    }

    public synchronized void add(
            TaggedMessage message)
    {
        if (message == null)
        {
            return;
        }

        final ChatMessageType retentionType =
                retentionType(
                        message);

        messages.addLast(
                message);

        countsByType.put(
                retentionType,
                countsByType.getOrDefault(
                        retentionType,
                        0) + 1);

        /*
         * Evict only the oldest semantic record belonging to this same chat
         * type.
         *
         * Traffic in another channel must never consume this type's retention
         * allowance.
         */
        while (countsByType.getOrDefault(
                retentionType,
                0) > capacityPerType)
        {
            if (!removeOldestOfType(
                    retentionType))
            {
                /*
                 * Defensive consistency fallback.
                 *
                 * This should never occur because the count was incremented
                 * together with insertion.
                 */
                countsByType.remove(
                        retentionType);

                break;
            }
        }
    }

    public synchronized Optional<TaggedMessage> get(
            long id)
    {
        return messages.stream()
                .filter(message ->
                        message.getId() == id)
                .findFirst();
    }

    public synchronized List<TaggedMessage> snapshot()
    {
        return Collections.unmodifiableList(
                new ArrayList<>(
                        messages));
    }

    public synchronized int size()
    {
        return messages.size();
    }

    public synchronized void clear()
    {
        messages.clear();
        countsByType.clear();
    }

    private boolean removeOldestOfType(
            ChatMessageType type)
    {
        final Iterator<TaggedMessage> iterator =
                messages.iterator();

        while (iterator.hasNext())
        {
            final TaggedMessage candidate =
                    iterator.next();

            if (retentionType(candidate)
                    != type)
            {
                continue;
            }

            iterator.remove();

            final int remaining =
                    countsByType.getOrDefault(
                            type,
                            0) - 1;

            if (remaining > 0)
            {
                countsByType.put(
                        type,
                        remaining);
            }
            else
            {
                countsByType.remove(
                        type);
            }

            return true;
        }

        return false;
    }

    private static ChatMessageType retentionType(
            TaggedMessage message)
    {
        if (message == null
                || message.getType() == null)
        {
            return ChatMessageType.UNKNOWN;
        }

        return message.getType();
    }
}

