package com.runetags.input;

import java.awt.FontMetrics;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Shared local-Note normalization and wrapping rules.
 *
 * Quick-Card rendering and Note-save validation use the same hard-line and
 * soft-wrap behavior: explicit newlines remain logical bullet boundaries while
 * ordinary text wraps by pixel width.
 */
public final class NoteTextLayout
{
    public static final String BULLET = "\u2022";
    public static final String BULLET_PREFIX = BULLET + " ";

    public static final int MAX_LOGICAL_LINES = 3;
    public static final int MAX_RENDERED_ROWS = 4;

    private NoteTextLayout()
    {
    }

    public static String normalizeForEditor(
            String note)
    {
        if (note == null
                || note.trim().isEmpty())
        {
            return BULLET_PREFIX;
        }

        final String normalized =
                normalizeLineEndings(note);

        final String[] logicalLines =
                normalized.split("\\n", -1);

        final List<String> editorLines =
                new ArrayList<>();

        for (String logicalLine : logicalLines)
        {
            final String clean =
                    normalizeBulletLine(logicalLine);

            if (clean == null)
            {
                continue;
            }

            editorLines.add(clean);
        }

        if (editorLines.isEmpty())
        {
            return BULLET_PREFIX;
        }

        return String.join(
                "\n",
                editorLines);
    }

    public static String normalizeForStorage(
            String editorValue)
    {
        if (editorValue == null)
        {
            return null;
        }

        final String normalized =
                normalizeLineEndings(editorValue);

        final String[] logicalLines =
                normalized.split("\\n", -1);

        final List<String> storedLines =
                new ArrayList<>();

        for (String logicalLine : logicalLines)
        {
            final String clean =
                    normalizeBulletLine(logicalLine);

            if (clean == null
                    || BULLET.equals(clean))
            {
                continue;
            }

            storedLines.add(clean);
        }

        if (storedLines.isEmpty())
        {
            return null;
        }

        return String.join(
                "\n",
                storedLines);
    }

    public static int logicalLineCount(
            String value)
    {
        if (value == null
                || value.isEmpty())
        {
            return 0;
        }

        final String normalized =
                normalizeLineEndings(value);

        int count = 1;

        for (int index = 0;
             index < normalized.length();
             ++index)
        {
            if (normalized.charAt(index) == '\n')
            {
                ++count;
            }
        }

        return count;
    }

    public static int widestLogicalLineWidth(
            FontMetrics metrics,
            String text)
    {
        if (metrics == null
                || text == null
                || text.trim().isEmpty())
        {
            return 0;
        }

        final String normalized =
                normalizeLineEndings(text);

        int widest = 0;

        for (String logicalLine
                : normalized.split("\\n", -1))
        {
            widest =
                    Math.max(
                            widest,
                            metrics.stringWidth(
                                    logicalLine.trim()));
        }

        return widest;
    }

    public static Result layout(
            FontMetrics metrics,
            String text,
            int maxWidth,
            int maxRows)
    {
        if (metrics == null
                || text == null
                || maxWidth <= 0
                || maxRows <= 0)
        {
            return Result.empty();
        }

        final String normalized =
                normalizeLineEndings(text);

        if (normalized.trim().isEmpty())
        {
            return Result.empty();
        }

        final List<String> rows =
                new ArrayList<>();

        boolean overflow = false;

        final String[] logicalLines =
                normalized.split("\\n", -1);

        outer:
        for (String logicalLine : logicalLines)
        {
            String remaining =
                    logicalLine.trim();

            if (remaining.isEmpty())
            {
                continue;
            }

            while (!remaining.isEmpty())
            {
                if (rows.size() >= maxRows)
                {
                    overflow = true;
                    break outer;
                }

                if (metrics.stringWidth(remaining)
                        <= maxWidth)
                {
                    rows.add(remaining);
                    remaining = "";
                    continue;
                }

                final int fittingEnd =
                        largestFittingPrefix(
                                metrics,
                                remaining,
                                maxWidth);

                if (fittingEnd <= 0)
                {
                    overflow = true;
                    break outer;
                }

                int breakAt =
                        remaining.lastIndexOf(
                                ' ',
                                Math.max(
                                        0,
                                        fittingEnd - 1));

                if (breakAt <= 0)
                {
                    breakAt =
                            fittingEnd;
                }

                final String row =
                        remaining.substring(
                                        0,
                                        breakAt)
                                .trim();

                if (!row.isEmpty())
                {
                    rows.add(row);
                }

                remaining =
                        remaining.substring(
                                        breakAt)
                                .trim();
            }
        }

        return new Result(
                Collections.unmodifiableList(rows),
                overflow);
    }

    private static int largestFittingPrefix(
            FontMetrics metrics,
            String value,
            int maxWidth)
    {
        int low = 1;
        int high =
                value.length();
        int end = 0;

        while (low <= high)
        {
            final int middle =
                    (low + high) >>> 1;

            if (metrics.stringWidth(
                    value.substring(
                            0,
                            middle)) <= maxWidth)
            {
                end = middle;
                low = middle + 1;
            }
            else
            {
                high = middle - 1;
            }
        }

        return end;
    }

    private static String normalizeBulletLine(
            String value)
    {
        if (value == null)
        {
            return null;
        }

        String clean =
                value.trim();

        if (clean.isEmpty())
        {
            return null;
        }

        if (clean.charAt(0) == BULLET.charAt(0))
        {
            clean =
                    clean.substring(1)
                            .trim();
        }

        if (clean.isEmpty())
        {
            return BULLET;
        }

        return BULLET_PREFIX
                + clean;
    }

    private static String normalizeLineEndings(
            String value)
    {
        return value.replace("\r\n", "\n")
                .replace('\r', '\n');
    }

    public static final class Result
    {
        private static final Result EMPTY =
                new Result(
                        Collections.emptyList(),
                        false);

        private final List<String> rows;
        private final boolean overflow;

        private Result(
                List<String> rows,
                boolean overflow)
        {
            this.rows = rows;
            this.overflow = overflow;
        }

        public static Result empty()
        {
            return EMPTY;
        }

        public List<String> getRows()
        {
            return rows;
        }

        public boolean isOverflow()
        {
            return overflow;
        }
    }
}

package com.runetags.input;

import com.runetags.Configurations;
import com.runetags.chat.ChatHitboxRegistry;
import com.runetags.chat.ReferenceHitbox;
import com.runetags.config.ChatInteractionMode;
import com.runetags.reference.PlayerReference;
import com.runetags.reference.ReferenceType;
import com.runetags.quickprofile.QuickProfileController;
import com.runetags.suggestion.SuggestionService;

import java.awt.Point;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.util.Arrays;
import java.util.Optional;

import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

import lombok.extern.slf4j.Slf4j;
@Slf4j
public class InputListener extends MouseAdapter
        implements KeyListener
{
    private static final String MENU_OPEN_PROFILE = "Open Profile";
    private static final String MENU_TARGET = "Target";
    private static final String MENU_LOOKUP = "Lookup";

    /*
     * RuneTags never creates Report. RuneScape's native Report entry identifies
     * the real chat-sender username context menu.
     */
    private static final String NATIVE_MENU_REPORT = "Report";

    private final Client client;
    private final Configurations config;
    private final ChatHitboxRegistry registry;
    private final QuickProfileController quickProfileController;
    private final SuggestionService suggestionService;

    private boolean suppressCurrentLeftClick;
    private boolean suppressCurrentEscape;
    private boolean suppressCurrentSuggestionTyped;

    public InputListener(
            Client client,
            Configurations config,
            ChatHitboxRegistry registry,
            QuickProfileController quickProfileController,
            SuggestionService suggestionService)
    {
        this.client = client;
        this.config = config;
        this.registry = registry;
        this.quickProfileController = quickProfileController;
        this.suggestionService = suggestionService;
    }

    @Override
    public MouseEvent mousePressed(MouseEvent event)
    {
        /*
         * Close any open QuickCard before the context
         * menu becomes the active interaction.
         */
        if (event.getButton() == MouseEvent.BUTTON3)
        {
            if (quickProfileController.isOpen())
            {
                quickProfileController.close();
            }

            return super.mousePressed(event);
        }

        if (event.getButton() != MouseEvent.BUTTON1)
        {
            return super.mousePressed(event);
        }

        /*
         * An open RuneScape menu owns the click. Do not route it to an underlying
         * RuneTags hitbox, and do not consume it because RuneScape must execute the
         * selected menu action.
         */
        if (client.isMenuOpen())
        {
            suppressCurrentLeftClick = false;
            return super.mousePressed(event);
        }

        final Point point =
                event.getPoint();

        if (quickProfileController.isOpen())
        {
            final String tagToRemove =
                    quickProfileController.tagRemovalAt(
                            point);

            if (tagToRemove != null)
            {
                quickProfileController.removeTag(
                        tagToRemove);

                suppressCurrentLeftClick = true;

                event.consume();
                return event;
            }

            if (quickProfileController.isCloseButton(
                    point))
            {
                quickProfileController.close();

                suppressCurrentLeftClick = true;

                event.consume();
                return event;
            }

            if (quickProfileController.isTagButton(
                    point))
            {
                quickProfileController.editTags();

                suppressCurrentLeftClick = true;

                event.consume();
                return event;
            }

            if (quickProfileController.isNoteButton(
                    point))
            {
                quickProfileController.editNote();

                suppressCurrentLeftClick = true;

                event.consume();
                return event;
            }

            if (quickProfileController.isFavoriteButton(
                    point))
            {
                quickProfileController.toggleFavorite();

                suppressCurrentLeftClick = true;

                event.consume();
                return event;
            }

            if (quickProfileController.isTargetButton(
                    point))
            {
                quickProfileController.target();

                suppressCurrentLeftClick = true;

                event.consume();
                return event;
            }

            if (quickProfileController.isLookupButton(
                    point))
            {
                quickProfileController.lookup();

                suppressCurrentLeftClick = true;

                event.consume();
                return event;
            }

            if (quickProfileController.isClanLink(
                    point))
            {
                quickProfileController.lookupClan();

                suppressCurrentLeftClick = true;

                event.consume();
                return event;
            }

            if (quickProfileController.isReportCaseLink(
                    point))
            {
                quickProfileController.openReportCase();

                suppressCurrentLeftClick = true;

                event.consume();
                return event;
            }

            if (quickProfileController.isInsideCard(
                    point))
            {
                suppressCurrentLeftClick = true;

                event.consume();
                return event;
            }
        }

        final ChatInteractionMode interactionMode =
                config.chatInteractionMode();

        /*
         * LEFT_CLICK and BOTH permit direct QuickCard activation;
         * RIGHT_CLICK deliberately leaves a normal left-click untouched.
         */
        if (interactionMode != null
                && interactionMode.allowsLeftClick())
        {
            final Optional<ReferenceHitbox> hit =
                    registry.find(
                            point);

            if (hit.isPresent())
            {
                quickProfileController.open(
                        hit.get().getReference(),
                        point);

                suppressCurrentLeftClick = true;

                event.consume();
                return event;
            }
        }

        /*
         * Clicking outside an open QuickCard closes it.
         */
        if (quickProfileController.isOpen())
        {
            quickProfileController.close();
        }

        return super.mousePressed(
                event);
    }

    /**
     * Augment RuneScape context menus with RuneTags actions.
     *
     * Native sender menus retain their normal actions. MENTION and TAG references
     * use the RuneTags Open Profile / Target / Lookup menu when right-click
     * interaction is enabled.
     */
    public void onMenuOpened(
            MenuOpened event)
    {
        /*
         * Menu ownership takes priority over an open QuickCard, including menus opened
         * through paths other than an ordinary BUTTON3 press.
         */
        if (quickProfileController.isOpen())
        {
            quickProfileController.close();
        }

        final ChatInteractionMode interactionMode =
                config.chatInteractionMode();

        /*
         * RIGHT_CLICK and BOTH permit RuneTags context-menu actions;
         * LEFT_CLICK leaves RuneScape's native right-click menu untouched.
         */
        if (interactionMode == null
                || !interactionMode.allowsRightClick())
        {
            return;
        }

        final net.runelite.api.Point mouseCanvasPoint =
                client.getMouseCanvasPosition();

        if (mouseCanvasPoint == null)
        {
            return;
        }

        final Point mousePoint =
                new Point(
                        mouseCanvasPoint.getX(),
                        mouseCanvasPoint.getY());

        /*
         * RuneTags references take priority over native sender menus.
         *
         * A mention inside another player's chat message belongs to the
         * referenced player, not the sender of the message.
         */
        final Optional<ReferenceHitbox> hit =
                registry.find(
                        mousePoint);

        if (hit.isPresent()
                && handleReferenceMenu(
                hit.get(),
                mousePoint))
        {
            return;
        }

        /*
         * If no RuneTags reference owns the interaction, preserve RuneScape's
         * native sender menu and add RuneTags actions where appropriate.
         */
        if (augmentNativeSenderMenu(
                event,
                mousePoint))
        {
            return;
        }

    }

    private boolean handleReferenceMenu(
            ReferenceHitbox referenceHitbox,
            Point mousePoint)
    {
        final PlayerReference reference =
                referenceHitbox.getReference();

        if (reference == null)
        {
            return false;
        }

        /*
         * Sender references belong to RuneScape's native menu.
         * They should never be handled here.
         */
        if (reference.getType()
                == ReferenceType.SENDER)
        {
            return false;
        }

        /*
         * Only mentions and tags receive RuneTags menus.
         */
        if (reference.getType()
                != ReferenceType.MENTION
                && reference.getType()
                != ReferenceType.TAG)
        {
            return false;
        }
        suppressNativeMenu(nativeSenderName());

        final Point anchorPoint =
                new Point(
                        mousePoint);

        final String target =
                menuTarget(
                        reference);


        client.createMenuEntry(-1)
                .setOption(
                        MENU_OPEN_PROFILE)
                .setTarget(
                        target)
                .setType(
                        MenuAction.RUNELITE)
                .onClick(entry ->
                        quickProfileController.open(
                                reference,
                                anchorPoint));


        if (config.targetPlayerOption()
                && quickProfileController.canTarget(
                reference))
        {
            client.createMenuEntry(-2)
                    .setOption(
                            MENU_TARGET)
                    .setTarget(
                            target)
                    .setType(
                            MenuAction.RUNELITE)
                    .onClick(entry ->
                            quickProfileController.target(
                                    reference));
        }


        client.createMenuEntry(-3)
                .setOption(
                        MENU_LOOKUP)
                .setTarget(
                        target)
                .setType(
                        MenuAction.RUNELITE)
                .onClick(entry ->
                        quickProfileController.lookup(
                                reference));


        return true;
    }

    /**
     * Remove the native sender actions created for the chat message author.
     *
     * A RuneTags mention/tag belongs to the referenced player, not the player
     * who sent the message containing the reference.
     */
    private String nativeSenderName()
    {
        final MenuEntry[] entries =
                client.getMenuEntries();

        for (MenuEntry entry : entries)
        {
            if (isNativeChatReportMenuEntry(entry))
            {
                return cleanPlayerName(
                        entry.getTarget());
            }
        }

        return "";
    }

    private boolean isNativePlayerMenu(
            MenuEntry entry,
            String senderName)
    {
        if (entry == null)
        {
            return false;
        }

        final String target =
                cleanPlayerName(
                        entry.getTarget());

        if (!target.equalsIgnoreCase(
                senderName))
        {
            return false;
        }

        final String option =
                entry.getOption();

        return "WALK HERE".equalsIgnoreCase(option)
                || "ADD FRIEND".equalsIgnoreCase(option)
                || "ADD IGNORE".equalsIgnoreCase(option)
                || "MESSAGE".equalsIgnoreCase(option)
                || "LOOKUP".equalsIgnoreCase(option)
                || "WOM LOOKUP".equalsIgnoreCase(option)
                || "TCG TRADE REQUEST".equalsIgnoreCase(option)
                || "REPORT".equalsIgnoreCase(option)
                || "COPY TO CLIPBOARD".equalsIgnoreCase(option);
    }

    private boolean isNativeMovementMenu(
            MenuEntry entry)
    {
        if (entry == null)
        {
            return false;
        }

        return "WALK HERE".equalsIgnoreCase(
                entry.getOption());
    }

    private void suppressNativeMenu(
            String senderName)
    {
        final MenuEntry[] entries =
                client.getMenuEntries();

        if (entries == null
                || entries.length == 0)
        {
            return;
        }

        final boolean hasSender =
                senderName != null
                        && !senderName.isEmpty();

        client.setMenuEntries(
                Arrays.stream(entries)
                        .filter(entry ->
                                !hasSender
                                        || !isNativePlayerMenu(
                                        entry,
                                        senderName))
                        .filter(entry ->
                                !isNativeMovementMenu(
                                        entry))
                        .toArray(MenuEntry[]::new));
    }

    /**
     * Hotkey or Escape pressing
     */
    @Override
    public void keyPressed(
            KeyEvent event)
    {
        if (event == null)
        {
            return;
        }

        if (!quickProfileController.isEditingNote()
                && !quickProfileController.isEditingTag()
                && suggestionService != null
                && suggestionService.handleKeyPressed(event))
        {
            if (event.getKeyCode() == KeyEvent.VK_ESCAPE)
            {
                suppressCurrentEscape = true;
            }

            if (event.getKeyChar() != KeyEvent.CHAR_UNDEFINED)
            {
                suppressCurrentSuggestionTyped = true;
            }

            return;
        }

        if (event.getKeyCode() != KeyEvent.VK_ESCAPE)
        {
            return;
        }

        /*
         * While the Note editor is open, RuneLite's ChatboxTextInput owns ESC.
         * Let it close normally so QuickProfileController can restore the profile.
         */
        if (quickProfileController.isEditingNote()
                || quickProfileController.isEditingTag())
        {
            return;
        }

        /*
         * When a Quick Profile is open, consume ESC after closing the card so
         * RuneScape does not process the same key press.
         */
        if (quickProfileController.isOpen())
        {
            quickProfileController.close();

            suppressCurrentEscape = true;

            event.consume();
        }
    }

    @Override
    public void keyReleased(
            KeyEvent event)
    {
        if (event == null)
        {
            return;
        }

        if (suppressCurrentSuggestionTyped)
        {
            event.consume();
        }

        if (event.getKeyCode() == KeyEvent.VK_ESCAPE
                && suppressCurrentEscape)
        {
            event.consume();
            suppressCurrentEscape = false;
        }
    }

    @Override
    public void keyTyped(
            KeyEvent event)
    {
        if (event == null)
        {
            return;
        }

        if (suppressCurrentSuggestionTyped)
        {
            event.consume();
            suppressCurrentSuggestionTyped = false;
        }
    }

    @Override
    public MouseEvent mouseReleased(
            MouseEvent event)
    {
        if (event.getButton()
                == MouseEvent.BUTTON1
                && suppressCurrentLeftClick)
        {
            event.consume();
        }

        return super.mouseReleased(
                event);
    }

    @Override
    public MouseEvent mouseClicked(
            MouseEvent event)
    {
        if (event.getButton()
                == MouseEvent.BUTTON1
                && suppressCurrentLeftClick)
        {
            event.consume();

            suppressCurrentLeftClick =
                    false;

            return event;
        }

        return super.mouseClicked(
                event);
    }

    /**
     * Augment RuneScape sender menus with RuneTags actions when the cursor
     * is over a native chat sender entry.
     *
     * RuneTags-owned mentions and tags are handled separately and replace
     * conflicting sender actions with their own player context menu.
     */
    private boolean augmentNativeSenderMenu(
            MenuOpened event,
            Point anchorPoint)
    {
        if (event == null
                || event.getMenuEntries() == null)
        {
            return false;
        }

        final MenuEntry[] menuEntries =
                event.getMenuEntries();

        for (int i = 0;
             i < menuEntries.length;
             i++)
        {
            final MenuEntry entry =
                    menuEntries[i];

            if (!isNativeChatReportMenuEntry(
                    entry))
            {
                continue;
            }

            final String playerName =
                    cleanPlayerName(
                            entry.getTarget());

            if (playerName.isEmpty())
            {
                return false;
            }

            /*
             * Preserve RuneScape's target markup for display; use the cleaned name only
             * for RuneTags identity resolution.
             */
            final String nativeTarget =
                    entry.getTarget() != null
                            ? entry.getTarget()
                            : playerName;

            /*
             * Retain the original right-click point so Open Profile anchors to the
             * username interaction that opened the menu.
             */
            final Point profileAnchor =
                    anchorPoint != null
                            ? new Point(
                            anchorPoint)
                            : null;

            /*
             * Reuse a RuneTags SENDER reference when available to preserve semantic state
             * such as ChatMessageType. If sender hitboxes are disabled, fall back to a
             * lightweight reference built from RuneScape's native username.
             */
            final PlayerReference senderReference =
                    nativeSenderReference(
                            playerName,
                            anchorPoint);

            /*
             * RuneScape's backing menu order is the reverse of its visual order.
             * Inserting immediately after Report therefore places Open Profile directly
             * above Report without moving the other native actions.
             */
            client.createMenuEntry(
                            i + 1)
                    .setOption(
                            MENU_OPEN_PROFILE)
                    .setTarget(
                            nativeTarget)
                    .setType(
                            MenuAction.RUNELITE)
                    .onClick(menuEntry ->
                            quickProfileController.open(
                                    senderReference,
                                    profileAnchor));

            /*
             * Target belongs at the top of the sender menu
             * and is re-resolved when selected.
             */
            if (config.targetPlayerOption()
                    && quickProfileController.canTarget(
                    senderReference))
            {
                client.createMenuEntry(-1)
                        .setOption(
                                ColorUtil.prependColorTag(
                                        MENU_TARGET,
                                        config.targetColor()))
                        .setTarget(
                                nativeTarget)
                        .setType(
                                MenuAction.RUNELITE)
                        .onClick(menuEntry ->
                                quickProfileController.target(
                                        senderReference));
            }
            return true;
        }
        return false;
    }

    /**
     * Resolve the PlayerReference used by native sender-menu actions.
     *
     * Reuse a SENDER hitbox reference when available so semantic data such as the
     * originating chat type is retained; otherwise build a minimal reference from
     * RuneScape's native username.
     */
    private PlayerReference nativeSenderReference(
            String playerName,
            Point mousePoint)
    {
        if (mousePoint != null)
        {
            final Optional<ReferenceHitbox> hit =
                    registry.find(
                            mousePoint);

            if (hit.isPresent())
            {
                final PlayerReference reference =
                        hit.get().getReference();

                if (reference != null
                        && reference.getType()
                        == ReferenceType.SENDER)
                {
                    return reference;
                }
            }
        }

        return PlayerReference.builder()
                .rawText(
                        playerName)
                .normalizedToken(
                        playerName)
                .lookupName(
                        playerName)
                .startOffset(0)
                .endOffset(
                        playerName.length())
                .type(
                        ReferenceType.SENDER)
                .locallyResolved(
                        false)
                .identity(
                        null)
                .chatType(
                        null)
                .build();
    }

    /**
     * Identify RuneScape's native Report action only when
     * it belongs to a supported player-chat surface.
     *
     * RuneTags never creates Report.
     */
    private boolean isNativeChatReportMenuEntry(
            MenuEntry entry)
    {
        return entry != null
                && entry.getOption() != null
                && NATIVE_MENU_REPORT.equals(
                Text.removeTags(
                        entry.getOption()))
                && isSupportedChatMessageEntry(
                entry.getParam1());
    }

    /**
     * Confirm that a native menu entry belongs to either the normal chatbox
     * or split-private-chat surface.
     */
    private boolean isSupportedChatMessageEntry(
            int packedWidgetId)
    {
        final int groupId =
                WidgetUtil.componentToInterface(
                        packedWidgetId);

        if (groupId == InterfaceID.CHATBOX)
        {
            return isChatboxMessageEntry(
                    packedWidgetId);
        }

        if (groupId == InterfaceID.PM_CHAT)
        {
            return isSplitPrivateMessageEntry(
                    packedWidgetId);
        }

        return false;
    }

    /**
     * Confirm that a native menu entry belongs to a normal chatbox message row.
     */
    private boolean isChatboxMessageEntry(
            int packedWidgetId)
    {
        final int groupId =
                WidgetUtil.componentToInterface(
                        packedWidgetId);

        final int childId =
                WidgetUtil.componentToId(
                        packedWidgetId);

        if (groupId != InterfaceID.CHATBOX)
        {
            return false;
        }

        final Widget widget =
                client.getWidget(
                        groupId,
                        childId);

        if (widget == null)
        {
            return false;
        }

        final Widget parent =
                widget.getParent();

        return parent != null
                && parent.getId()
                == InterfaceID.Chatbox.SCROLLAREA;
    }

    /**
     * Confirm that a native menu entry belongs to one of RuneScape's
     * split-private-chat message components.
     */
    private boolean isSplitPrivateMessageEntry(
            int packedWidgetId)
    {
        final int groupId =
                WidgetUtil.componentToInterface(
                        packedWidgetId);

        if (groupId != InterfaceID.PM_CHAT)
        {
            return false;
        }

        final int childId =
                WidgetUtil.componentToId(
                        packedWidgetId);

        final Widget widget =
                client.getWidget(
                        groupId,
                        childId);

        if (widget == null)
        {
            return false;
        }

        final Widget container =
                client.getWidget(
                        InterfaceID.PmChat.CONTAINER);

        if (container == null)
        {
            return false;
        }

        final Widget parent =
                widget.getParent();

        return widget == container
                || parent == container
                || isChildOf(
                widget,
                container);
    }

    private static boolean isChildOf(
            Widget widget,
            Widget ancestor)
    {
        if (widget == null
                || ancestor == null)
        {
            return false;
        }

        Widget current =
                widget.getParent();

        while (current != null)
        {
            if (current == ancestor
                    || current.getId()
                    == ancestor.getId())
            {
                return true;
            }

            current =
                    current.getParent();
        }

        return false;
    }

    /**
     * Convert RuneScape's menu target into a plain player name suitable for
     * RuneTags identity resolution.
     */
    private static String cleanPlayerName(
            String value)
    {
        if (value == null)
        {
            return "";
        }

        return Text.removeTags(
                        value)
                .replace(
                        '\u00A0',
                        ' ')
                .trim();
    }

    private static String menuTarget(
            PlayerReference reference)
    {
        if (reference == null)
        {
            return "";
        }

        if (reference.getLookupName() != null
                && !reference.getLookupName()
                .trim()
                .isEmpty())
        {
            return reference
                    .getLookupName()
                    .trim();
        }

        if (reference.getRawText() != null
                && !reference.getRawText()
                .trim()
                .isEmpty())
        {
            return reference
                    .getRawText()
                    .trim();
        }

        return "";
    }
}

package com.runetags.input;

import java.awt.*;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.Consumer;

import com.runetags.records.PlayerTagCatalog;
import net.runelite.api.FontID;
import net.runelite.api.FontTypeFace;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.chatbox.ChatboxInput;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseListener;
import net.runelite.client.util.Text;

/** Native chatbox selector for adding one RuneTags local player Tag. */
public final class TagChatboxInput extends ChatboxInput
        implements KeyListener, MouseListener
{
    private static final int LEFT = 16;
    private static final int RIGHT = 16;
    private static final int START_Y = 38;

    private static final int PILL_HEIGHT = 18;
    private static final int PILL_PAD_X = 5;
    private static final int PILL_GAP_X = 5;
    private static final int PILL_GAP_Y = 4;
    private static final int PILL_TEXT_Y_OFFSET = 2;
    private static final int PILL_EDGE_BUFFER = 5;

    private static final Color PILL_BACKGROUND = new Color(55, 55, 55, 140);
    private static final Color PILL_BACKGROUND_HOVER = new Color(30, 30, 30, 140);

    private final ChatboxPanelManager chatboxPanelManager;
    private final ClientThread clientThread;
    private final List<String> selected = new ArrayList<>();
    private final List<TagHitbox> hitboxes = new ArrayList<>();

    private TagHitbox hoveredHitbox;
    private String prompt;
    private Consumer<List<String>> onDone;
    private Runnable onClose;
    private boolean built;

    public TagChatboxInput(
            ChatboxPanelManager chatboxPanelManager,
            ClientThread clientThread)
    {
        this.chatboxPanelManager = chatboxPanelManager;
        this.clientThread = clientThread;
    }

    public TagChatboxInput prompt(String prompt)
    {
        this.prompt = prompt;
        requestUpdate();
        return this;
    }

    public TagChatboxInput value(List<String> tags)
    {
        selected.clear();

        if (tags != null)
        {
            for (String value : tags)
            {
                final String tag = PlayerTagCatalog.canonical(value);

                if (tag != null
                        && !selected.contains(tag)
                        && selected.size() < PlayerTagCatalog.MAX_TAGS_PER_PLAYER)
                {
                    selected.add(tag);
                }
            }
        }

        requestUpdate();
        return this;
    }

    public TagChatboxInput onDone(Consumer<List<String>> onDone)
    {
        this.onDone = onDone;
        return this;
    }

    public TagChatboxInput onClose(Runnable onClose)
    {
        this.onClose = onClose;
        return this;
    }

    public TagChatboxInput build()
    {
        if (prompt == null)
        {
            throw new IllegalStateException("prompt must be non-null");
        }

        chatboxPanelManager.openInput(this);
        return this;
    }

    @Override
    protected void open()
    {
        built = true;
        update();
    }

    @Override
    protected void close()
    {
        built = false;
        hoveredHitbox = null;
        hitboxes.clear();

        if (onClose != null)
        {
            onClose.run();
        }
    }

    private void requestUpdate()
    {
        if (built)
        {
            clientThread.invoke(this::update);
        }
    }

    private static void setPillColor(Widget background, Color color)
    {
        if (background == null || color == null)
        {
            return;
        }

        background.setTextColor(color.getRGB() & 0xFFFFFF);
        background.setOpacity(255 - color.getAlpha());
    }

    private void update()
    {
        final Widget container = chatboxPanelManager.getContainerWidget();

        if (container == null)
        {
            return;
        }

        container.deleteAllChildren();
        hitboxes.clear();

        final Widget promptWidget = container.createChild(-1, WidgetType.TEXT);
        promptWidget.setText(prompt);
        promptWidget.setTextColor(0x800000);
        promptWidget.setFontId(FontID.QUILL_8);
        promptWidget.setXPositionMode(WidgetPositionMode.ABSOLUTE_CENTER);
        promptWidget.setOriginalX(0);
        promptWidget.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
        promptWidget.setOriginalY(6);
        promptWidget.setOriginalHeight(24);
        promptWidget.setXTextAlignment(WidgetTextAlignment.CENTER);
        promptWidget.setYTextAlignment(WidgetTextAlignment.CENTER);
        promptWidget.setWidthMode(WidgetSizeMode.MINUS);
        promptWidget.revalidate();

        final Widget probe = container.createChild(-1, WidgetType.RECTANGLE);
        probe.setFontId(FontID.PLAIN_12);

        final FontTypeFace font = probe.getFont();
        probe.setHidden(true);

        if (font == null)
        {
            return;
        }

        if (selected.size() >= PlayerTagCatalog.MAX_TAGS_PER_PLAYER)
        {
            final Widget message = container.createChild(-1, WidgetType.TEXT);
            message.setFontId(FontID.BOLD_12);
            message.setText(
                    "A maximum of (" + PlayerTagCatalog.MAX_TAGS_PER_PLAYER + ") Tags have already been selected.");
            message.setTextColor(0x282828);
            message.setXPositionMode(WidgetPositionMode.ABSOLUTE_CENTER);
            message.setXTextAlignment(WidgetTextAlignment.CENTER);
            message.setOriginalX(0);
            message.setOriginalY(START_Y + PILL_TEXT_Y_OFFSET);
            message.setOriginalWidth(Math.max(1, container.getWidth() - LEFT - RIGHT));
            message.setOriginalHeight(PILL_HEIGHT);
            message.revalidate();
            return;
        }

        final List<String> available = new ArrayList<>();

        for (String tag : PlayerTagCatalog.ALL)
        {
            if (!selected.contains(tag))
            {
                available.add(tag);
            }
        }

        drawAvailable(container, font, available, START_Y);
    }

    private void drawAvailable(
            Widget container,
            FontTypeFace font,
            List<String> tags,
            int y)
    {
        int x = LEFT;

        final int maxX = Math.max(
                LEFT,
                container.getWidth()
                        - RIGHT
                        - PILL_EDGE_BUFFER);

        for (String tag : tags)
        {
            final int width = font.getTextWidth(tag) + (PILL_PAD_X * 2);

            if (x > LEFT
                    && x
                    + width
                    + PILL_GAP_X
                    > maxX)
            {
                x = LEFT;
                y += PILL_HEIGHT + PILL_GAP_Y;
            }

            final Widget background = container.createChild(-1, WidgetType.RECTANGLE);
            background.setFilled(true);
            setPillColor(background, PILL_BACKGROUND);
            background.setOriginalX(x);
            background.setOriginalY(y);
            background.setOriginalWidth(width);
            background.setOriginalHeight(PILL_HEIGHT);
            background.revalidate();

            final Widget text = container.createChild(-1, WidgetType.TEXT);
            text.setFontId(FontID.PLAIN_12);
            text.setText(Text.escapeJagex(tag));
            text.setTextColor(0xFFFFFF);
            text.setOriginalX(x + PILL_PAD_X);
            text.setOriginalY(y + PILL_TEXT_Y_OFFSET);
            text.setOriginalWidth(width - (PILL_PAD_X * 2));
            text.setOriginalHeight(PILL_HEIGHT);
            text.revalidate();

            hitboxes.add(
                    new TagHitbox(
                            new Rectangle(x, y, width, PILL_HEIGHT),
                            tag,
                            background));

            x += width + PILL_GAP_X;
        }
    }

    @Override
    public void keyPressed(KeyEvent event)
    {
        if (!chatboxPanelManager.shouldTakeInput())
        {
            return;
        }

        if (event.getKeyCode() == KeyEvent.VK_ESCAPE
                || event.getKeyCode() == KeyEvent.VK_ENTER)
        {
            event.consume();
            chatboxPanelManager.close();
        }
    }

    @Override
    public void keyTyped(KeyEvent event)
    {
    }

    @Override
    public void keyReleased(KeyEvent event)
    {
    }

    @Override
    public MouseEvent mousePressed(MouseEvent event)
    {
        if (event.getButton() != MouseEvent.BUTTON1)
        {
            return event;
        }

        final Widget container = chatboxPanelManager.getContainerWidget();

        if (container == null)
        {
            return event;
        }

        final net.runelite.api.Point canvas = container.getCanvasLocation();

        final Point local = new Point(
                event.getX() - canvas.getX(),
                event.getY() - canvas.getY());

        for (TagHitbox hitbox : new ArrayList<>(hitboxes))
        {
            if (!hitbox.bounds.contains(local))
            {
                continue;
            }

            if (selected.size() >= PlayerTagCatalog.MAX_TAGS_PER_PLAYER)
            {
                return event;
            }

            selected.add(hitbox.tag);

            if (onDone != null)
            {
                onDone.accept(
                        Collections.unmodifiableList(
                                new ArrayList<>(selected)));
            }

            event.consume();
            chatboxPanelManager.close();
            return event;
        }

        return event;
    }

    @Override
    public MouseEvent mouseClicked(MouseEvent event)
    {
        return event;
    }

    @Override
    public MouseEvent mouseReleased(MouseEvent event)
    {
        return event;
    }

    @Override
    public MouseEvent mouseEntered(MouseEvent event)
    {
        return event;
    }

    @Override
    public MouseEvent mouseExited(MouseEvent event)
    {
        if (hoveredHitbox != null)
        {
            setPillColor(hoveredHitbox.background, PILL_BACKGROUND);
            hoveredHitbox = null;
        }

        return event;
    }

    @Override
    public MouseEvent mouseDragged(MouseEvent event)
    {
        return event;
    }

    @Override
    public MouseEvent mouseMoved(MouseEvent event)
    {
        final Widget container = chatboxPanelManager.getContainerWidget();

        if (container == null)
        {
            return event;
        }

        final net.runelite.api.Point canvas = container.getCanvasLocation();
        final Point local = new Point(
                event.getX() - canvas.getX(),
                event.getY() - canvas.getY());

        TagHitbox nextHoveredHitbox = null;

        for (TagHitbox hitbox : hitboxes)
        {
            if (hitbox.bounds.contains(local))
            {
                nextHoveredHitbox = hitbox;
                break;
            }
        }

        if (hoveredHitbox == nextHoveredHitbox)
        {
            return event;
        }

        if (hoveredHitbox != null)
        {
            setPillColor(hoveredHitbox.background, PILL_BACKGROUND);
        }

        hoveredHitbox = nextHoveredHitbox;

        if (hoveredHitbox != null)
        {
            setPillColor(hoveredHitbox.background, PILL_BACKGROUND_HOVER);
        }

        return event;
    }

    private static final class TagHitbox
    {
        private final Rectangle bounds;
        private final String tag;
        private final Widget background;

        private TagHitbox(Rectangle bounds, String tag, Widget background)
        {
            this.bounds = bounds;
            this.tag = tag;
            this.background = background;
        }
    }
}

package com.runetags.input;

import java.awt.Point;
import java.awt.Rectangle;
import java.awt.Toolkit;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.UnsupportedFlavorException;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.Predicate;

import lombok.extern.slf4j.Slf4j;

import net.runelite.api.FontID;
import net.runelite.api.FontTypeFace;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.chatbox.ChatboxInput;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseListener;
import net.runelite.client.util.Text;

/**
 * RuneTags-specific native chatbox editor for local player Notes.
 *
 * Unlike the stock ChatboxTextInput, Notes preserve hard line breaks:
 * Shift+Enter inserts a new bullet line, Enter submits, and explicit logical
 * lines are limited independently from soft-wrapped rows.
 */
@Slf4j
public final class NoteChatboxInput
        extends ChatboxInput
        implements KeyListener, MouseListener
{
    private static final int CURSOR_FLASH_RATE_MILLIS = 1000;
    private static final int TEXT_Y = 50;

    private static final int EDITOR_LEFT_PADDING = 16;
    private static final int EDITOR_RIGHT_PADDING = 16;
    private static final int BULLET_GUTTER_WIDTH = 10;
    private static final int BULLET_SIZE = 3;
    private static final int BULLET_Y_OFFSET = 3;

    private final ChatboxPanelManager chatboxPanelManager;
    private final ClientThread clientThread;

    private String prompt;
    private int visibleLines = 4;
    private int maxLength = 256;
    private int maxLogicalLines = NoteTextLayout.MAX_LOGICAL_LINES;

    private final StringBuilder value =
            new StringBuilder();

    private int cursor;
    private Predicate<String> onDone;
    private Runnable onClose;
    private boolean built;

    private volatile List<VisibleRow> visibleRows =
            Collections.emptyList();

    public NoteChatboxInput(
            ChatboxPanelManager chatboxPanelManager,
            ClientThread clientThread)
    {
        this.chatboxPanelManager =
                chatboxPanelManager;
        this.clientThread =
                clientThread;
    }

    public NoteChatboxInput prompt(
            String prompt)
    {
        this.prompt = prompt;

        requestUpdate();
        return this;
    }

    public NoteChatboxInput lines(
            int lines)
    {
        this.visibleLines =
                Math.max(
                        1,
                        lines);

        requestUpdate();
        return this;
    }

    public NoteChatboxInput maxLength(
            int maxLength)
    {
        this.maxLength =
                Math.max(
                        1,
                        maxLength);

        return this;
    }

    public NoteChatboxInput maxLogicalLines(
            int maxLogicalLines)
    {
        this.maxLogicalLines =
                Math.max(
                        1,
                        maxLogicalLines);

        return this;
    }

    public NoteChatboxInput value(
            String initialValue)
    {
        value.setLength(0);

        final String editorValue =
                NoteTextLayout.normalizeForEditor(
                        initialValue);

        appendWithinLimit(
                editorValue);

        if (value.length() == 0)
        {
            value.append(
                    NoteTextLayout.BULLET_PREFIX);
        }

        cursor =
                value.length();

        requestUpdate();
        return this;
    }

    public NoteChatboxInput onDone(
            Predicate<String> onDone)
    {
        this.onDone = onDone;
        return this;
    }

    public NoteChatboxInput onClose(
            Runnable onClose)
    {
        this.onClose = onClose;
        return this;
    }

    public String getValue()
    {
        return value.toString();
    }

    public NoteChatboxInput build()
    {
        if (prompt == null)
        {
            throw new IllegalStateException(
                    "prompt must be non-null");
        }

        chatboxPanelManager.openInput(
                this);

        return this;
    }

    @Override
    protected void open()
    {
        built = true;
        update();
    }

    @Override
    protected void close()
    {
        built = false;
        visibleRows =
                Collections.emptyList();

        if (onClose != null)
        {
            onClose.run();
        }
    }

    private void requestUpdate()
    {
        if (built)
        {
            clientThread.invoke(
                    this::update);
        }
    }

    private void update()
    {
        final Widget container =
                chatboxPanelManager.getContainerWidget();

        if (container == null)
        {
            return;
        }

        container.deleteAllChildren();

        final Widget promptWidget =
                container.createChild(
                        -1,
                        WidgetType.TEXT);

        promptWidget.setText(prompt);
        promptWidget.setTextColor(0x800000);
        promptWidget.setFontId(FontID.BARBARIAN);
        promptWidget.setXPositionMode(
                WidgetPositionMode.ABSOLUTE_CENTER);
        promptWidget.setOriginalX(0);
        promptWidget.setYPositionMode(
                WidgetPositionMode.ABSOLUTE_TOP);
        promptWidget.setOriginalY(8);
        promptWidget.setOriginalHeight(24);
        promptWidget.setXTextAlignment(
                WidgetTextAlignment.CENTER);
        promptWidget.setYTextAlignment(
                WidgetTextAlignment.CENTER);
        promptWidget.setWidthMode(
                WidgetSizeMode.MINUS);
        promptWidget.revalidate();

        drawEditor(
                container);
    }

    private void drawEditor(
            Widget container)
    {
        final Widget cursorWidget =
                container.createChild(
                        -1,
                        WidgetType.RECTANGLE);

        final long start =
                System.currentTimeMillis();

        cursorWidget.setOnTimerListener(
                (JavaScriptCallback) event ->
                {
                    final boolean on =
                            (System.currentTimeMillis()
                                    - start)
                                    % CURSOR_FLASH_RATE_MILLIS
                                    > CURSOR_FLASH_RATE_MILLIS / 2;

                    cursorWidget.setOpacity(
                            on
                                    ? 255
                                    : 0);
                });

        cursorWidget.setTextColor(0xFFFFFF);
        cursorWidget.setHasListener(true);
        cursorWidget.setFilled(true);
        cursorWidget.setFontId(FontID.PLAIN_12);

        final FontTypeFace font =
                cursorWidget.getFont();

        if (font == null)
        {
            visibleRows =
                    Collections.emptyList();
            return;
        }

        final int lineHeight =
                Math.max(
                        1,
                        font.getBaseline());

        final int width =
                Math.max(
                        1,
                        container.getWidth());

        /*
         * Use a stable left-aligned text area with a dedicated bullet gutter. Logical
         * rows draw a bullet there; soft-wrapped continuation rows share the text X
         * without drawing another bullet.
         */
        final int textX =
                EDITOR_LEFT_PADDING
                        + BULLET_GUTTER_WIDTH;

        final int textAreaWidth =
                Math.max(
                        1,
                        width
                                - textX
                                - EDITOR_RIGHT_PADDING);

        final List<InputRow> allRows =
                buildRows(
                        font,
                        textAreaWidth);

        final int cursorRowIndex =
                findCursorRow(
                        allRows);

        final int viewportStart =
                viewportStart(
                        allRows.size(),
                        cursorRowIndex);

        final int viewportEnd =
                Math.min(
                        allRows.size(),
                        viewportStart
                                + visibleLines);

        final List<VisibleRow> rendered =
                new ArrayList<>();

        int y =
                TEXT_Y;

        for (int index = viewportStart;
             index < viewportEnd;
             ++index)
        {
            final InputRow row =
                    allRows.get(index);

            final String displayText =
                    row.text;

            final int textWidth =
                    font.getTextWidth(
                            displayText);

            /*
             * QUILL_8 does not reliably expose the Unicode bullet glyph, so draw the
             * marker as a small native rectangle in the bullet gutter instead.
             */
            if (row.bullet)
            {
                final Widget bulletWidget =
                        container.createChild(
                                -1,
                                WidgetType.RECTANGLE);

                bulletWidget.setTextColor(
                        0x000000);
                bulletWidget.setFilled(true);

                bulletWidget.setOriginalX(
                        EDITOR_LEFT_PADDING
                                + 2);

                bulletWidget.setOriginalY(
                        y
                                + Math.max(
                                1,
                                (lineHeight
                                        - BULLET_SIZE) / 2)
                                + BULLET_Y_OFFSET);

                bulletWidget.setOriginalWidth(
                        BULLET_SIZE);

                bulletWidget.setOriginalHeight(
                        BULLET_SIZE);

                bulletWidget.revalidate();
            }

            final Widget textWidget =
                    container.createChild(
                            -1,
                            WidgetType.TEXT);

            textWidget.setFontId(
                    FontID.PLAIN_12);

            textWidget.setText(
                    Text.escapeJagex(
                            displayText));

            textWidget.setOriginalX(
                    textX);

            textWidget.setOriginalY(
                    y);

            textWidget.setOriginalWidth(
                    textAreaWidth);

            textWidget.setOriginalHeight(
                    lineHeight);

            textWidget.revalidate();

            if (index == cursorRowIndex)
            {
                final int relativeCursor =
                        Math.max(
                                0,
                                Math.min(
                                        displayText.length(),
                                        cursor
                                                - row.start));

                final int cursorX =
                        textX
                                + font.getTextWidth(
                                displayText.substring(
                                        0,
                                        relativeCursor));

                cursorWidget.setOriginalX(
                        cursorX - 1);

                cursorWidget.setOriginalY(
                        y);

                cursorWidget.setOriginalWidth(
                        2);

                cursorWidget.setOriginalHeight(
                        lineHeight);

                cursorWidget.revalidate();
            }

            /*
             * Use the full text area for mouse targeting so clicking after visible text
             * places the cursor at that row's end.
             */
            rendered.add(
                    new VisibleRow(
                            row,
                            textX,
                            y,
                            textAreaWidth,
                            lineHeight));

            y +=
                    lineHeight;
        }

        visibleRows =
                Collections.unmodifiableList(
                        rendered);
    }

    private List<InputRow> buildRows(
            FontTypeFace font,
            int maxWidth)
    {
        final List<InputRow> rows =
                new ArrayList<>();

        int logicalStart =
                0;

        while (logicalStart
                <= value.length())
        {
            final int newlineIndex =
                    indexOfNewline(
                            logicalStart);

            final int logicalEnd =
                    newlineIndex >= 0
                            ? newlineIndex
                            : value.length();

            final int prefixLength =
                    NoteTextLayout.BULLET_PREFIX.length();

            final boolean hasBullet =
                    logicalEnd
                            - logicalStart
                            >= prefixLength
                            && value.substring(
                                    logicalStart,
                                    logicalStart
                                            + prefixLength)
                            .equals(
                                    NoteTextLayout.BULLET_PREFIX);

            /*
             * Stored text retains "• ", while QUILL_8 renders only the editable text and
             * drawEditor() renders the bullet separately.
             */
            final int contentStart =
                    hasBullet
                            ? logicalStart
                            + prefixLength
                            : logicalStart;

            wrapLogicalLine(
                    rows,
                    font,
                    maxWidth,
                    contentStart,
                    logicalEnd,
                    hasBullet);

            if (newlineIndex < 0)
            {
                break;
            }

            logicalStart =
                    newlineIndex + 1;
        }

        if (rows.isEmpty())
        {
            rows.add(
                    new InputRow(
                            0,
                            0,
                            "",
                            false));
        }

        return rows;
    }

    private void wrapLogicalLine(
            List<InputRow> output,
            FontTypeFace font,
            int maxWidth,
            int start,
            int end,
            boolean bullet)
    {
        if (start >= end)
        {
            output.add(
                    new InputRow(
                            start,
                            end,
                            "",
                            bullet));

            return;
        }

        int rowStart =
                start;

        boolean firstRow =
                true;

        while (rowStart < end)
        {
            int fittingEnd =
                    rowStart;

            int lastSpace =
                    -1;

            for (int index = rowStart;
                 index < end;
                 ++index)
            {
                final char character =
                        value.charAt(index);

                final String candidate =
                        value.substring(
                                rowStart,
                                index + 1);

                if (font.getTextWidth(
                        candidate)
                        <= maxWidth)
                {
                    fittingEnd =
                            index + 1;

                    if (character == ' ')
                    {
                        lastSpace =
                                index;
                    }

                    continue;
                }

                break;
            }

            if (fittingEnd <= rowStart)
            {
                fittingEnd =
                        Math.min(
                                end,
                                rowStart + 1);
            }
            else if (fittingEnd < end
                    && lastSpace >= rowStart)
            {
                /*
                 * Keep the wrapping space in the previous row's source span so every source
                 * position remains owned by rendered geometry.
                 */
                fittingEnd =
                        lastSpace + 1;
            }

            final int rowEnd =
                    fittingEnd;

            /*
             * Do not trim or skip boundary spaces; every source
             * character must belong to exactly one InputRow.
             */
            output.add(
                    new InputRow(
                            rowStart,
                            rowEnd,
                            value.substring(
                                    rowStart,
                                    rowEnd),
                            firstRow
                                    && bullet));

            rowStart =
                    rowEnd;

            firstRow =
                    false;
        }
    }

    private int findCursorRow(
            List<InputRow> rows)
    {
        for (int index = 0;
             index < rows.size();
             ++index)
        {
            final InputRow row =
                    rows.get(index);

            if (row.start == row.end
                    && cursor == row.start)
            {
                return index;
            }

            if (cursor >= row.start
                    && cursor < row.end)
            {
                return index;
            }

            if (cursor == row.end)
            {
                final boolean nextRowStartsHere =
                        index + 1
                                < rows.size()
                                && rows.get(
                                index + 1).start
                                == cursor;

                /*
                 * At a soft-wrap boundary, assign the cursor to the next row;
                 * at the logical line end, keep it on the current row.
                 */
                if (!nextRowStartsHere)
                {
                    return index;
                }
            }
        }

        return Math.max(
                0,
                rows.size() - 1);
    }

    private int viewportStart(
            int rowCount,
            int cursorRowIndex)
    {
        if (rowCount <= visibleLines)
        {
            return 0;
        }

        return Math.max(
                0,
                Math.min(
                        cursorRowIndex
                                - visibleLines
                                + 1,
                        rowCount
                                - visibleLines));
    }

    private int indexOfNewline(
            int fromIndex)
    {
        for (int index = fromIndex;
             index < value.length();
             ++index)
        {
            if (value.charAt(index) == '\n')
            {
                return index;
            }
        }

        return -1;
    }

    @Override
    public void keyTyped(
            KeyEvent event)
    {
        if (!chatboxPanelManager.shouldTakeInput())
        {
            return;
        }

        final char character =
                event.getKeyChar();

        if (character < 32
                || character >= 127)
        {
            return;
        }

        if (value.length()
                >= maxLength)
        {
            setTemporaryPrompt(
                    "RuneTags Note: max "
                            + maxLength
                            + " characters");
            return;
        }

        value.insert(
                cursor,
                character);

        ++cursor;
        requestUpdate();
    }

    @Override
    public void keyPressed(
            KeyEvent event)
    {
        if (!chatboxPanelManager.shouldTakeInput())
        {
            return;
        }

        final int code =
                event.getKeyCode();

        if (event.isControlDown())
        {
            if (code == KeyEvent.VK_V)
            {
                event.consume();
                pasteClipboard();
            }

            return;
        }

        switch (code)
        {
            case KeyEvent.VK_ENTER:
                event.consume();

                if (event.isShiftDown())
                {
                    insertBulletLine();
                    return;
                }

                if (onDone != null
                        && !onDone.test(
                        getValue()))
                {
                    return;
                }

                chatboxPanelManager.close();
                return;

            case KeyEvent.VK_ESCAPE:
                event.consume();
                chatboxPanelManager.close();
                return;

            case KeyEvent.VK_BACK_SPACE:
                event.consume();
                backspace();
                return;

            case KeyEvent.VK_DELETE:
                event.consume();
                delete();
                return;

            case KeyEvent.VK_LEFT:
                event.consume();

                final int editableStart =
                        editableLineStart(
                                cursor);

                if (cursor > editableStart)
                {
                    --cursor;
                }
                else
                {
                    final int logicalStart =
                            logicalLineStart(
                                    cursor);

                    if (logicalStart > 0)
                    {
                        /*
                         * Cross "\n• " as one structural boundary to the previous logical line.
                         */
                        cursor =
                                logicalLineEnd(
                                        logicalStart - 1);
                    }
                }

                requestUpdate();
                return;

            case KeyEvent.VK_RIGHT:
                event.consume();

                final int currentLineEnd =
                        logicalLineEnd(
                                cursor);

                if (cursor < currentLineEnd)
                {
                    ++cursor;
                }
                else if (currentLineEnd
                        < value.length())
                {
                    /*
                     * Skip the complete newline + bullet prefix as one structural boundary.
                     */
                    cursor =
                            editableLineStart(
                                    currentLineEnd + 1);
                }

                requestUpdate();
                return;

            case KeyEvent.VK_HOME:
                event.consume();

                cursor =
                        editableLineStart(
                                cursor);

                requestUpdate();
                return;

            case KeyEvent.VK_END:
                event.consume();
                cursor =
                        logicalLineEnd(
                                cursor);
                requestUpdate();
                return;

            case KeyEvent.VK_UP:
                event.consume();
                moveVertical(-1);
                return;

            case KeyEvent.VK_DOWN:
                event.consume();
                moveVertical(1);
                return;

            default:
                return;
        }
    }

    @Override
    public void keyReleased(
            KeyEvent event)
    {
    }

    private void insertBulletLine()
    {
        if (NoteTextLayout.logicalLineCount(
                getValue()) >= maxLogicalLines)
        {
            setTemporaryPrompt(
                    "RuneTags Note: max "
                            + maxLogicalLines
                            + " bullets");
            return;
        }

        final String insertion =
                "\n"
                        + NoteTextLayout.BULLET_PREFIX;

        if (value.length()
                + insertion.length()
                > maxLength)
        {
            setTemporaryPrompt(
                    "RuneTags Note: max "
                            + maxLength
                            + " characters");
            return;
        }

        value.insert(
                cursor,
                insertion);

        cursor +=
                insertion.length();

        requestUpdate();
    }

    private void backspace()
    {
        if (cursor <= 0)
        {
            return;
        }

        final int lineStart =
                logicalLineStart(
                        cursor);

        final int editableStart =
                editableLineStart(
                        cursor);

        final int lineEnd =
                logicalLineEnd(
                        cursor);

        /*
         * On an empty secondary bullet, Backspace removes the complete "\n• "
         * structure and returns to the previous logical line. The first bullet is
         * permanent while the editor is open.
         */
        if (cursor == editableStart
                && lineStart > 0
                && lineEnd == editableStart)
        {
            value.delete(
                    lineStart - 1,
                    editableStart);

            cursor =
                    lineStart - 1;

            requestUpdate();
            return;
        }

        /*
         * Prevent Backspace from entering or deleting the structural bullet prefix.
         */
        if (cursor <= editableStart)
        {
            return;
        }

        value.deleteCharAt(
                cursor - 1);

        --cursor;

        requestUpdate();
    }

    private void delete()
    {
        if (cursor >= value.length())
        {
            return;
        }

        final int lineEnd =
                logicalLineEnd(
                        cursor);

        /*
         * Prevent Delete from crossing a logical-line boundary
         * and removing its newline or bullet prefix.
         */
        if (cursor >= lineEnd)
        {
            return;
        }

        value.deleteCharAt(
                cursor);

        requestUpdate();
    }

    private int logicalLineStart(
            int position)
    {
        int index =
                Math.max(
                        0,
                        Math.min(
                                position,
                                value.length()));

        while (index > 0
                && value.charAt(
                index - 1) != '\n')
        {
            --index;
        }

        return index;
    }

    private int editableLineStart(
            int position)
    {
        final int lineStart =
                logicalLineStart(
                        position);

        final int lineEnd =
                logicalLineEnd(
                        lineStart);

        final int prefixLength =
                NoteTextLayout.BULLET_PREFIX.length();

        if (lineEnd
                - lineStart
                >= prefixLength
                && value.substring(
                        lineStart,
                        lineStart
                                + prefixLength)
                .equals(
                        NoteTextLayout.BULLET_PREFIX))
        {
            return lineStart
                    + prefixLength;
        }

        return lineStart;
    }

    private int logicalLineEnd(
            int position)
    {
        int index =
                Math.max(
                        0,
                        Math.min(
                                position,
                                value.length()));

        while (index < value.length()
                && value.charAt(index) != '\n')
        {
            ++index;
        }

        return index;
    }

    private void moveVertical(
            int direction)
    {
        final List<VisibleRow> rows =
                visibleRows;

        if (rows.isEmpty())
        {
            return;
        }

        int currentIndex =
                -1;

        for (int index = 0;
             index < rows.size();
             ++index)
        {
            final InputRow row =
                    rows.get(index).row;

            if (cursor >= row.start
                    && cursor <= row.end)
            {
                currentIndex = index;
                break;
            }
        }

        if (currentIndex < 0)
        {
            return;
        }

        final int targetIndex =
                currentIndex
                        + direction;

        if (targetIndex < 0
                || targetIndex >= rows.size())
        {
            return;
        }

        final InputRow currentRow =
                rows.get(currentIndex).row;

        final InputRow targetRow =
                rows.get(targetIndex).row;

        final int column =
                Math.max(
                        0,
                        cursor
                                - currentRow.start);

        cursor =
                Math.min(
                        targetRow.end,
                        targetRow.start
                                + column);

        requestUpdate();
    }

    private void pasteClipboard()
    {
        try
        {
            final Object clipboardValue =
                    Toolkit.getDefaultToolkit()
                            .getSystemClipboard()
                            .getData(
                                    DataFlavor.stringFlavor);

            if (clipboardValue == null)
            {
                return;
            }

            String pasted =
                    clipboardValue.toString()
                            .replace("\r\n", " ")
                            .replace('\r', ' ')
                            .replace('\n', ' ')
                            .replace(
                                    NoteTextLayout.BULLET,
                                    "-");

            final StringBuilder clean =
                    new StringBuilder();

            for (int index = 0;
                 index < pasted.length();
                 ++index)
            {
                final char character =
                        pasted.charAt(index);

                if (character >= 32
                        && character < 127)
                {
                    clean.append(character);
                }
            }

            final int available =
                    Math.max(
                            0,
                            maxLength
                                    - value.length());

            if (clean.length()
                    > available)
            {
                clean.setLength(
                        available);
            }

            if (clean.length() == 0)
            {
                return;
            }

            value.insert(
                    cursor,
                    clean);

            cursor +=
                    clean.length();

            requestUpdate();
        }
        catch (IOException | UnsupportedFlavorException exception)
        {
            log.warn("Unable to Read Clipboard for RuneTags Note", exception);
        }
    }

    private void appendWithinLimit(
            String text)
    {
        if (text == null
                || text.isEmpty())
        {
            return;
        }

        final int available =
                Math.max(
                        0,
                        maxLength
                                - value.length());

        value.append(
                text,
                0,
                Math.min(
                        text.length(),
                        available));
    }

    private void setTemporaryPrompt(
            String message)
    {
        prompt = message;
        requestUpdate();
    }

    @Override
    public MouseEvent mouseClicked(
            MouseEvent mouseEvent)
    {
        return mouseEvent;
    }

    @Override
    public MouseEvent mousePressed(
            MouseEvent mouseEvent)
    {
        if (mouseEvent.getButton()
                != MouseEvent.BUTTON1)
        {
            return mouseEvent;
        }

        final Widget container =
                chatboxPanelManager.getContainerWidget();

        if (container == null)
        {
            return mouseEvent;
        }

        final net.runelite.api.Point canvasLocation =
                container.getCanvasLocation();

        final int localX =
                mouseEvent.getX()
                        - canvasLocation.getX();

        final int localY =
                mouseEvent.getY()
                        - canvasLocation.getY();

        for (VisibleRow visibleRow
                : visibleRows)
        {
            final Rectangle bounds =
                    new Rectangle(
                            visibleRow.x,
                            visibleRow.y,
                            Math.max(
                                    1,
                                    visibleRow.width),
                            visibleRow.height);

            if (!bounds.contains(
                    new Point(
                            localX,
                            localY)))
            {
                continue;
            }

            final Widget probe =
                    container.createChild(
                            -1,
                            WidgetType.RECTANGLE);

            probe.setFontId(
                    FontID.PLAIN_12);

            final FontTypeFace font =
                    probe.getFont();

            probe.setHidden(true);

            if (font == null)
            {
                break;
            }

            final int relativeX =
                    Math.max(
                            0,
                            localX
                                    - visibleRow.x);

            int bestOffset = 0;
            int bestDistance =
                    Integer.MAX_VALUE;

            for (int offset = 0;
                 offset <= visibleRow.row.text.length();
                 ++offset)
            {
                final int x =
                        font.getTextWidth(
                                visibleRow.row.text.substring(
                                        0,
                                        offset));

                final int distance =
                        Math.abs(
                                x
                                        - relativeX);

                if (distance < bestDistance)
                {
                    bestDistance =
                            distance;
                    bestOffset =
                            offset;
                }
            }

            cursor =
                    Math.min(
                            visibleRow.row.end,
                            visibleRow.row.start
                                    + bestOffset);

            requestUpdate();
            break;
        }

        return mouseEvent;
    }

    @Override
    public MouseEvent mouseReleased(
            MouseEvent mouseEvent)
    {
        return mouseEvent;
    }

    @Override
    public MouseEvent mouseEntered(
            MouseEvent mouseEvent)
    {
        return mouseEvent;
    }

    @Override
    public MouseEvent mouseExited(
            MouseEvent mouseEvent)
    {
        return mouseEvent;
    }

    @Override
    public MouseEvent mouseDragged(
            MouseEvent mouseEvent)
    {
        return mouseEvent;
    }

    @Override
    public MouseEvent mouseMoved(
            MouseEvent mouseEvent)
    {
        return mouseEvent;
    }

    private static final class InputRow
    {
        private final int start;
        private final int end;
        private final String text;
        private final boolean bullet;

        private InputRow(
                int start,
                int end,
                String text,
                boolean bullet)
        {
            this.start = start;
            this.end = end;
            this.text =
                    text != null
                            ? text
                            : "";
            this.bullet = bullet;
        }
    }

    private static final class VisibleRow
    {
        private final InputRow row;
        private final int x;
        private final int y;
        private final int width;
        private final int height;

        private VisibleRow(
                InputRow row,
                int x,
                int y,
                int width,
                int height)
        {
            this.row = row;
            this.x = x;
            this.y = y;
            this.width = width;
            this.height = height;
        }
    }
}

package com.runetags.notification;

import com.runetags.Configurations;
import com.runetags.chat.TaggedMessage;

import java.awt.TrayIcon;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.Notifier;
import net.runelite.client.config.Notification;
import net.runelite.client.config.NotificationSound;

public class MentionNotificationService
{
    private final Client client;
    private final Configurations config;
    private final Notifier notifier;

    public MentionNotificationService(
            Client client,
            Configurations config,
            Notifier notifier)
    {
        this.client = client;
        this.config = config;
        this.notifier = notifier;
    }

    public void notifyMention(
            TaggedMessage taggedMessage)
    {
        if (taggedMessage == null
                || taggedMessage.getLocalMentionMatch() == null
                || !taggedMessage
                .getLocalMentionMatch()
                .isMatchesLocalPlayer())
        {
            return;
        }

        /*
         * Override RuneLite's global notification settings so RuneTags controls focus
         * and flash behavior while disabling tray, RuneLite sound, and game-message
         * notifications. The RuneTags in-game mention sound is handled separately.
         */
        final Notification notification =
                new Notification(
                        true,                       // enabled
                        true,                               // initialized
                        true,                               // override
                        false,                              // tray
                        TrayIcon.MessageType.NONE,          // tray icon type
                        config.requestFocusOnMention(),     // request focus
                        NotificationSound.OFF,              // RuneLite sound
                        null,                               // custom sound name
                        100,                                // unused volume
                        0,                                  // unused timeout
                        false,                              // game message
                        config.flashOnMention(),            // flash mode
                        config.flashColor(),                // flash color
                        config.sendNotificationsWhenFocused());

        notifier.notify(
                notification,
                notificationText(taggedMessage));

        /*
         * The RuneTags game sound is independent from Send Notifications When Focused,
         * so disabling focused notifications does not suppress the sound.
         */
        playMentionSound();
    }

    private void playMentionSound()
    {
        if (!config.playMentionSound())
        {
            return;
        }

        if (client.getGameState()
                != GameState.LOGGED_IN)
        {
            return;
        }

        final int soundId =
                config.mentionSoundId();

        if (soundId <= 0)
        {
            return;
        }

        client.playSoundEffect(
                soundId);
    }

    private static String notificationText(
            TaggedMessage taggedMessage)
    {
        final String sender =
                taggedMessage.getCanonicalSender();

        final String message =
                taggedMessage.getOriginalMessage();

        if (sender == null
                || sender.isEmpty())
        {
            return message != null
                    && !message.isEmpty()
                    ? message
                    : "[RuneTags][Notification] Player Mentioned";
        }

        if (message == null
                || message.isEmpty())
        {
            return sender;
        }

        return sender
                + ": "
                + message;
    }
}

package com.runetags.target;

import com.runetags.Configurations;
import com.runetags.config.HideOthersMode;
import com.runetags.quickprofile.QuickProfileModel;

import java.util.Locale;

import lombok.extern.slf4j.Slf4j;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.WorldView;

@Slf4j
public class TargetController
{
    private final Client client;
    private final Configurations config;

    private volatile String targetName;
    private volatile Player targetPlayer;
    private volatile long targetStartedNanos;
    private volatile long hideOthersStartedNanos;

    public TargetController(Client client, Configurations config)
    {
        this.client = client;
        this.config = config;
    }

    public boolean toggleTarget(QuickProfileModel model)
    {
        if (model == null
                || !model.isNearby()
                || model.getDisplayName() == null
                || model.getDisplayName().trim().isEmpty())
        {
            return isTargeting();
        }

        return toggleTarget(
                model.getDisplayName());
    }

    /**
     * Toggle a target selected from RuneLite's native player menu.
     *
     * The live Player object is deliberately reduced back to the canonical
     * player name and re-resolved against the current scene. This keeps native
     * player-menu targeting and Quick-Card/chat targeting on the same nearby
     * validation path and avoids retaining a stale actor from an open menu.
     */
    public boolean toggleTarget(Player player)
    {
        if (player == null
                || player.getName() == null
                || player.getName().trim().isEmpty())
        {
            return isTargeting();
        }

        return toggleTarget(
                player.getName());
    }

    /**
     * Toggle a nearby player by name.
     *
     * This is the shared entry point used when the caller has semantic player
     * identity but no guaranteed-live Player object, such as a chat mention/tag
     * context-menu action.
     */
    public boolean toggleTarget(String playerName)
    {
        if (playerName == null
                || playerName.trim().isEmpty())
        {
            return isTargeting();
        }

        if (!config.targetPlayerOption())
        {
            if (isTargeting())
            {
                clear("targeting disabled");
            }

            return false;
        }

        final String requestedName =
                playerName.trim();

        if (isTargetingName(requestedName))
        {
            clear("manually untargeted");
            return false;
        }

        final Player resolved =
                findNearbyPlayer(
                        requestedName);

        if (resolved == null
                || resolved.getName() == null
                || resolved.getName().trim().isEmpty())
        {
            return isTargeting();
        }

        final long now =
                System.nanoTime();

        targetName = resolved.getName();
        targetPlayer = resolved;
        targetStartedNanos = now;
        hideOthersStartedNanos = now;

        //log.debug("[RuneTags][Target] Targeted Player='{}'", targetName);

        return true;
    }

    public void refresh()
    {
        final String currentName = targetName;

        if (currentName == null)
        {
            targetPlayer = null;
            return;
        }

        if (!config.targetPlayerOption())
        {
            clear("targeting disabled");
            return;
        }

        if (client.getGameState() != GameState.LOGGED_IN)
        {
            clear("not logged in");
            return;
        }

        final int timeoutSeconds = Math.max(0, config.targetTimeout());

        if (timeoutSeconds > 0
                && targetStartedNanos > 0
                && System.nanoTime() - targetStartedNanos
                >= timeoutSeconds * 1_000_000_000L)
        {
            clear("timeout");
            return;
        }

        final Player resolved = findNearbyPlayer(currentName);

        if (resolved == null)
        {
            clear("player left scene");
            return;
        }

        targetPlayer = resolved;
    }

    public void clear()
    {
        clear("cleared");
    }

    public void clear(String reason)
    {
        final String oldName = targetName;

        targetName = null;
        targetPlayer = null;
        targetStartedNanos = 0L;
        hideOthersStartedNanos = 0L;

        if (oldName != null)
        {
            //log.debug("[RuneTags][Target] Untargeted Player='{}' | Reason='{}'", oldName, reason);
        }
    }

    public boolean isTargeting()
    {
        return targetName != null;
    }

    public boolean isTargetingName(String playerName)
    {
        final String currentName = targetName;

        return currentName != null
                && normalize(currentName).equals(normalize(playerName));
    }

    public Player getTargetPlayer()
    {
        return targetPlayer;
    }

    private Player findNearbyPlayer(String playerName)
    {
        final WorldView worldView = client.getTopLevelWorldView();

        if (worldView == null)
        {
            return null;
        }

        final String wanted = normalize(playerName);

        for (Player player : worldView.players())
        {
            if (player == null || player.getName() == null)
            {
                continue;
            }

            if (normalize(player.getName()).equals(wanted))
            {
                return player;
            }
        }

        return null;
    }

    public boolean shouldHideOtherPlayers()
    {
        if (!isTargeting())
        {
            return false;
        }

        final HideOthersMode mode =
                config.hideAllOthers();

        if (mode == null || !mode.isEnabled())
        {
            return false;
        }

        if (!mode.isTimed()
                || hideOthersStartedNanos <= 0L)
        {
            return false;
        }

        final long elapsedNanos =
                System.nanoTime()
                        - hideOthersStartedNanos;

        final long durationNanos =
                mode.getDurationSeconds()
                        * 1_000_000_000L;

        return elapsedNanos < durationNanos;
    }

    private static String normalize(String value)
    {
        return value == null
                ? ""
                : value.trim()
                .replace('_', ' ')
                .replace('-', ' ')
                .replaceAll("\\s+", " ")
                .toLowerCase(Locale.ROOT);
    }
}

package com.runetags.target;

import net.runelite.api.Player;
import net.runelite.api.Renderable;
import net.runelite.client.callback.Hooks;

/**
 * Controls visibility of player renderables while RuneTags' "Hide All Others" mode is active.
 *
 * When active:
 * - current target = visible
 * - every other player = hidden
 *
 * This applies to both:
 * - 3D player models
 * - 2D player UI elements such as overheads / health bars
 *
 * NPCs, projectiles, graphics objects, etc. are unaffected.
 */
public class PlayerVisibilityService
{
    private final Hooks hooks;
    private final TargetController targetController;

    private final Hooks.RenderableDrawListener drawListener =
            this::shouldDraw;

    private boolean registered;

    public PlayerVisibilityService(
            Hooks hooks,
            TargetController targetController)
    {
        this.hooks = hooks;
        this.targetController = targetController;
    }

    public void start()
    {
        if (registered)
        {
            return;
        }

        hooks.registerRenderableDrawListener(
                drawListener);

        registered = true;
    }

    public void stop()
    {
        if (!registered)
        {
            return;
        }

        hooks.unregisterRenderableDrawListener(
                drawListener);

        registered = false;
    }

    private boolean shouldDraw(
            Renderable renderable,
            boolean drawingUi)
    {
        /*
         * RuneTags only modifies Player visibility.
         */
        if (!(renderable instanceof Player))
        {
            return true;
        }

        /*
         * When "Hide All Others" is inactive, RuneTags must not
         * interfere with normal RuneLite/Jagex rendering.
         */
        if (!targetController.shouldHideOtherPlayers())
        {
            return true;
        }

        final Player player =
                (Player) renderable;

        final String playerName =
                player.getName();

        /*
         * A null-name Player should be left alone rather than risk hiding
         * something whose identity RuneTags cannot safely determine.
         */
        if (playerName == null
                || playerName.isEmpty())
        {
            return true;
        }

        /*
         * Hide EVERYTHING except the active RuneTags target.
         *
         * This deliberately includes:
         *
         * - local player
         * - friends
         * - clan members
         * - friends-chat members
         * - party members
         * - strangers
         *
         * drawingUi is intentionally ignored so both the player reference and
         * their 2D UI elements follow the same visibility rule.
         */
        return targetController.isTargetingName(
                playerName);
    }
}

package com.runetags.location;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import javax.inject.Inject;

/**
 * Loads RuneTags' coarse-location map from the bundled Locations.json.
 *
 * JSON values are RuneScape region-grid coordinates [regionX, regionY].
 */
public class LocationIndex
{
    private static final String RESOURCE = "/com/runetags/context/Locations.json";

    private final Map<Integer, String> byRegion;

    @Inject
    public LocationIndex(Gson gson)
    {
        this.byRegion = load(gson);
    }

    public String findName(int regionId)
    {
        return byRegion.get(regionId);
    }

    public int size()
    {
        return byRegion.size();
    }

    private static Map<Integer, String> load(Gson gson)
    {
        final InputStream stream =
                LocationIndex.class.getResourceAsStream(RESOURCE);

        if (stream == null)
        {
            throw new IllegalStateException(
                    "Missing RuneTags location resource: " + RESOURCE);
        }

        final Type type =
                new TypeToken<LinkedHashMap<String, List<List<Integer>>>>() { }
                        .getType();

        final Map<String, List<List<Integer>>> source =
                gson.fromJson(
                        new InputStreamReader(stream, StandardCharsets.UTF_8),
                        type);

        final Map<Integer, String> result =
                new LinkedHashMap<>();

        for (Map.Entry<String, List<List<Integer>>> entry : source.entrySet())
        {
            for (List<Integer> pair : entry.getValue())
            {
                if (pair == null || pair.size() < 2)
                {
                    continue;
                }

                final int regionX = pair.get(0);
                final int regionY = pair.get(1);
                final int regionId = (regionX << 8) | regionY;

                result.put(regionId, entry.getKey());
            }
        }

        return Collections.unmodifiableMap(result);
    }
}

package com.runetags.location;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;

/**
 * Client-thread snapshot of the local player's coarse location.
 *
 * This service answers only WHERE the local player is.
 *
 * It deliberately does not:
 *
 * - inspect NPCs;
 * - choose profile metrics;
 * - resolve boss encounters;
 * - perform HiScore lookups;
 * - decide which KC/activity/skill values should be displayed.
 *
 * Those concerns belong to the contextual metric layer.
 */
public class PlayerLocationService
{
    private final Client client;
    private final LocationIndex locationIndex;

    private volatile PlayerLocation current =
            PlayerLocation.unknown();

    public PlayerLocationService(
            Client client,
            LocationIndex locationIndex)
    {
        this.client =
                client;

        this.locationIndex =
                locationIndex;
    }

    public PlayerLocation getCurrent()
    {
        return current;
    }

    public void clear()
    {
        current =
                PlayerLocation.unknown();
    }

    /**
     * Refresh the local player's coarse location.
     *
     * Must run on RuneLite's client thread.
     */
    public void refresh()
    {
        final Player localPlayer =
                client.getLocalPlayer();

        if (localPlayer == null)
        {
            clear();
            return;
        }

        final WorldPoint point =
                localPlayer.getWorldLocation();

        if (point == null)
        {
            clear();
            return;
        }

        final int regionId =
                point.getRegionID();

        final String locationName =
                locationIndex.findName(
                        regionId);

        current =
                new PlayerLocation(
                        locationName,
                        regionId);
    }
}

package com.runetags.location;

import lombok.Value;

/**
 * Immutable coarse location snapshot for a player.
 *
 * Represents only where the player is; contextual metrics and encounter
 * semantics belong to the context layer.
 */
@Value
public class PlayerLocation
{
    String locationName;
    int regionId;

    public static PlayerLocation unknown()
    {
        return new PlayerLocation(
                null,
                -1);
    }

    public boolean hasLocation()
    {
        return locationName != null
                && !locationName.trim().isEmpty();
    }

    public boolean hasRegion()
    {
        return regionId >= 0;
    }
}

