    private void startReportLookup(
            String playerName,
            long generation)
    {
        if (reportCaseService == null
                || playerName == null
                || playerName.trim().isEmpty())
        {
            return;
        }

        reportCaseService.requestReports(
                playerName,
                reports -> applyReportSummaries(
                        generation,
                        playerName,
                        reports));
    }

    private void applyReportSummaries(
            long generation,
            String playerName,
            List<ReportSummary> reports)
    {
        if (generation != openGeneration)
        {
            return;
        }

        final QuickProfileModel current =
                model;

        if (current == null
                || current.getDisplayName() == null
                || !samePlayer(
                current.getDisplayName(),
                playerName))
        {
            return;
        }

        model = current.toBuilder()
                .reportSummaries(
                        reports != null
                                ? reports
                                : Collections.emptyList())
                .build();
    }

    private void startEfficiencyLookup(
            String playerName,
            long generation)
    {
        if (efficiencyMetricService == null
                || !config.wiseOldManMetrics()
                || (!config.showEhp()
                && !config.showEhb())
                || playerName == null
                || playerName.trim().isEmpty())
        {
            return;
        }

        efficiencyMetricService.lookup(playerName)
                .thenAccept(data ->
                        applyEfficiencyMetrics(
                                generation,
                                playerName,
                                data));
    }

    private void applyEfficiencyMetrics(
            long generation,
            String playerName,
            EfficiencyProfileData data)
    {
        if (generation != openGeneration
                || !config.wiseOldManMetrics())
        {
            return;
        }

        final QuickProfileModel current = model;

        if (current == null
                || current.getDisplayName() == null
                || !samePlayer(
                current.getDisplayName(),
                playerName))
        {
            return;
        }

        model = current.toBuilder()
                .efficientHoursPlayed(
                        data != null
                                ? data.getEhp()
                                : null)
                .efficientHoursBossed(
                        data != null
                                ? data.getEhb()
                                : null)
                .build();
    }

    private void startAutomaticEnrichment(
            String playerName,
            long generation)
    {
        if (playerName == null || playerName.trim().isEmpty())
        {
            return;
        }

        final HiscoreEnrichmentService.EnrichmentRequest request =
                hiscoreEnrichmentService.enrich(playerName);

        applyEnrichment(
                generation,
                playerName,
                request.getInitialState(),
                request.getInitialData());

        final CompletableFuture<HiscoreEnrichmentCache.CachedProfileEnrichment> future =
                request.getFuture();

        if (future == null)
        {
            return;
        }

        future.thenAccept(result ->
                applyEnrichment(
                        generation,
                        playerName,
                        result.getState(),
                        result.getData()));
    }

    private void applyEnrichment(
            long generation,
            String playerName,
            HiscoreEnrichmentState state,
            HiscoreProfileData data)
    {
        if (generation != openGeneration)
        {
            return;
        }

        final QuickProfileModel current = model;

        if (current == null
                || current.getDisplayName() == null
                || !samePlayer(current.getDisplayName(), playerName))
        {
            return;
        }

        /*
         * Use the context captured when the profile opened. Asynchronous enrichment
         * must not recalculate context from the local player's current location.
         */
        enrichmentData = data;

        final PlayerContext playerContext =
                profileContext;

        final List<ProfileMetricValue> contextMetrics =
                buildContextMetrics(
                        playerContext,
                        enrichmentData);

        model = current.toBuilder()
                .accountType(
                        resolveAccountType(
                                current.getAccountType(),
                                data))
                .combatLevel(
                        data != null
                                && data.getCombatLevel() != null
                                ? data.getCombatLevel()
                                : current.getCombatLevel())
                .totalLevel(
                        data != null
                                ? data.getTotalLevel()
                                : current.getTotalLevel())
                .contextMetrics(contextMetrics)
                .enrichmentState(state)
                .build();
    }

    private static AccountType resolveAccountType(
            AccountType current,
            HiscoreProfileData data)
    {
        final AccountType enriched =
                data != null
                        ? data.getAccountType()
                        : AccountType.UNKNOWN;

        return AccountType.prefer(
                current,
                enriched);
    }

    private PlayerContext resolveProfileContext(
            PlayerIdentity identity)
    {
        if (identity == null)
        {
            return null;
        }

        /*
         * Nearby context takes priority over cached Party context because local
         * scene information is more current.
         */
        if (identity.isNearby())
        {
            return playerContextService != null
                    ? playerContextService.getCurrent()
                    : null;
        }

        /*
         * Remote Party members may use their own shared Party context. Other remote
         * players must not inherit local context.
         */
        if (identity.getSources() == null
                || !identity.getSources().contains(PlayerSource.PARTY)
                || partyContextService == null)
        {
            return null;
        }

        final PartyContextService.PartyContext partyContext =
                partyContextService.find(
                        identity.getCanonicalName());

        if (partyContext == null)
        {
            return null;
        }

        return profileMetricResolver.resolveLocation(
                new PlayerLocation(
                        partyContext.getLocationName(),
                        partyContext.getRegionId()));
    }

    private String displayLocation(
            String playerName,
            PlayerIdentity identity,
            PlayerContext context)
    {
        /*
         * A resolved location is preferred whenever one is available.
         */
        if (context != null
                && context.getLocationName() != null
                && !context.getLocationName().trim().isEmpty())
        {
            return context.getLocationName();
        }

        /*
         * Region-grid fallback is only valid for the local player. Nearby players
         * without a mapped location should not expose the local region as their own.
         */
        if (isLocalPlayerName(playerName))
        {
            final PlayerContext localContext =
                    context != null
                            ? context
                            : playerContextService != null
                            ? playerContextService.getCurrent()
                            : null;

            if (localContext != null)
            {
                if (localContext.getLocationName() != null
                        && !localContext.getLocationName().trim().isEmpty())
                {
                    return localContext.getLocationName();
                }

                if (localContext.getRegionId() >= 0)
                {
                    return formatRegionGrid(
                            localContext.getRegionId());
                }
            }
        }

        /*
         * Nearby players without a resolved location only expose their nearby state.
         */
        if (identity != null
                && identity.isNearby())
        {
            return "Nearby";
        }

        /*
         * Remote players without a resolved location have no location data available.
         */
        return "Location: Unknown";
    }

    private boolean isLocalPlayerName(
            String playerName)
    {
        if (client == null
                || playerName == null
                || playerName.trim().isEmpty())
        {
            return false;
        }

        final Player localPlayer =
                client.getLocalPlayer();

        return localPlayer != null
                && localPlayer.getName() != null
                && samePlayer(
                playerName,
                localPlayer.getName());
    }

    /**
     * Locations.json stores region-grid coordinates as [regionX, regionY].
     * WorldPoint#getRegionID packs that pair as (regionX << 8) | regionY.
     */
    private static String formatRegionGrid(
            int regionId)
    {
        final int regionX =
                (regionId >>> 8) & 0xFF;

        final int regionY =
                regionId & 0xFF;

        return "Region: ["
                + regionX
                + ", "
                + regionY
                + "]";
    }

    private static String displayChannelName(
            PlayerIdentity identity,
            ChatMessageType originatingChatType)
    {
        /*
         * Prefer the resolved shared channel when available.
         */
        if (identity != null
                && identity.getChannelName() != null
                && !identity.getChannelName().trim().isEmpty())
        {
            return identity.getChannelName();
        }

        return displayMessageChannel(
                originatingChatType);
    }

    private static String displayMessageChannel(
            ChatMessageType chatType)
    {
        if (chatType == null)
        {
            return null;
        }

        switch (chatType)
        {
            case PUBLICCHAT:
            case MODCHAT:
                return "Public";

            case PRIVATECHAT:
            case MODPRIVATECHAT:
            case PRIVATECHATOUT:
                return "Private";

            case FRIENDSCHAT:
                return "Friends Chat";

            case CLAN_CHAT:
            case CLAN_GIM_CHAT:
                return "Clan";

            case CLAN_GUEST_CHAT:
                return "Guest Clan";

            default:
                return null;
        }
    }

    private static String displayChannelRank(
            PlayerIdentity identity)
    {
        /*
         * Message-derived channels do not provide a channel rank.
         */
        if (identity == null
                || identity.getChannelName() == null
                || identity.getChannelName().trim().isEmpty())
        {
            return null;
        }

        return identity.getChannelRank();
    }

    private static PlayerSource displayChannelSource(
            PlayerIdentity identity)
    {
        /*
         * Message-derived channels do not map to a PlayerSource.
         */
        if (identity == null
                || identity.getChannelName() == null
                || identity.getChannelName().trim().isEmpty())
        {
            return null;
        }

        return identity.getChannelSource();
    }

    private static List<ProfileMetricValue> buildContextMetrics(
            PlayerContext playerContext,
            HiscoreProfileData data)
    {
        if (playerContext == null
                || data == null
                || !playerContext.hasMetrics())
        {
            return Collections.emptyList();
        }

        final List<ProfileMetricValue> values =
                new ArrayList<>();

        for (ProfileMetric metric : playerContext.getMetrics())
        {
            final Integer value =
                    data.getContextValue(
                            metric.getHiscoreSkillName());

            if (value == null)
            {
                continue;
            }

            values.add(
                    new ProfileMetricValue(
                            metric.getLabel(),
                            value));
        }

        return Collections.unmodifiableList(values);
    }

    private static boolean samePlayer(
            String left,
            String right)
    {
        return normalize(left).equals(normalize(right));
    }

    private static String normalize(String value)
    {
        return value == null
                ? ""
                : value.trim()
                .replace('\u00A0', ' ')
                .replace('\u202F', ' ')
                .replaceAll("[ _-]+", "")
                .toLowerCase(java.util.Locale.ROOT);
    }

    @lombok.Value
    public static class ProfileContextSnapshot
    {
        Integer world;
        String locationName;
        String channelName;
        PlayerSource channelSource;

        public static ProfileContextSnapshot empty()
        {
            return new ProfileContextSnapshot(
                    null,
                    null,
                    null,
                    null);
        }
    }

    private void clearLayoutBounds()
    {
        cardBounds = null;
        closeButtonBounds = null;
        tagButtonBounds = null;
        noteButtonBounds = null;
        favoriteButtonBounds = null;
        targetButtonBounds = null;
        lookupButtonBounds = null;
        clanLinkBounds = null;
        reportCaseLinkBounds = null;
        tagRemoveBounds.clear();
    }

    private static Rectangle copy(Rectangle rectangle)
    {
        return rectangle == null
                ? null
                : new Rectangle(rectangle);
    }
}

package com.runetags.quickprofile;

import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;

import lombok.extern.slf4j.Slf4j;

import net.runelite.client.util.LinkBrowser;

@Slf4j
public class ClanLookupService
{
    private static final String WOM_GROUP_SEARCH_URL = "https://wiseoldman.net/groups?search=";

    public void search(String clanName)
    {
        if (clanName == null
                || clanName.trim().isEmpty())
        {
            return;
        }

        final String encodedName =
                URLEncoder.encode(
                        clanName.trim(),
                        StandardCharsets.UTF_8);

        final String url =
                WOM_GROUP_SEARCH_URL + encodedName;

        LinkBrowser.browse(url);
    }
}

package com.runetags.history;

import com.google.gson.Gson;
import com.runetags.Configurations;
import com.runetags.Constants;
import com.runetags.chat.TaggedMessage;
import com.runetags.mention.MatchReason;

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.List;

import javax.inject.Inject;

import lombok.extern.slf4j.Slf4j;

import net.runelite.api.ChatMessageType;
import net.runelite.client.RuneLite;
import net.runelite.client.config.ConfigManager;

@Slf4j
public class MentionHistoryService
{
    private static final int STORE_VERSION = 1;

    private static final String LEGACY_CONFIG_KEY =
            "mentionHistoryV1";

    private static final Path DEFAULT_HISTORY_DIRECTORY =
            RuneLite.RUNELITE_DIR
                    .toPath()
                    .resolve("RuneTags")
                    .resolve("history");

    private static final Path DEFAULT_HISTORY_FILE =
            DEFAULT_HISTORY_DIRECTORY.resolve(
                    "history.json");

    private final Configurations config;
    private final Gson gson;
    private final ConfigManager configManager;
    private final Path historyDirectory;
    private final Path historyFile;
    private final Path historyTempFile;

    private final Deque<MentionHistoryEntry> entries =
            new ArrayDeque<>();

    @Inject
    public MentionHistoryService(
            Configurations config,
            Gson gson,
            ConfigManager configManager)
    {
        this(
                config,
                gson,
                configManager,
                DEFAULT_HISTORY_FILE);
    }

    MentionHistoryService(
            Configurations config,
            Gson gson)
    {
        this(
                config,
                gson,
                null,
                DEFAULT_HISTORY_FILE);
    }

    MentionHistoryService(
            Configurations config,
            Gson gson,
            ConfigManager configManager,
            Path historyFile)
    {
        this.config = config;
        this.gson = gson;
        this.configManager = configManager;
        this.historyFile = historyFile;
        this.historyDirectory = historyFile.getParent();
        this.historyTempFile = historyFile.resolveSibling(
                historyFile.getFileName().toString() + ".tmp");

        load();
    }

    public synchronized void add(
            TaggedMessage taggedMessage,
            Integer world,
            String locationName,
            String channelName)
    {
        if (!config.mentionHistory()
                || taggedMessage == null
                || taggedMessage.getLocalMentionMatch() == null
                || !taggedMessage.getLocalMentionMatch().isMatchesLocalPlayer())
        {
            return;
        }

        final MentionHistoryEntry entry =
                new MentionHistoryEntry(
                        taggedMessage.getId(),
                        taggedMessage.getCanonicalSender(),
                        taggedMessage.getOriginalMessage(),
                        taggedMessage.getType(),
                        taggedMessage.getLocalMentionMatch().getReason(),
                        world,
                        locationName,
                        channelName,
                        taggedMessage.getTimestamp());

        entries.addFirst(entry);
        trim();
        save();
    }

    public synchronized List<MentionHistoryEntry> snapshot()
    {
        return Collections.unmodifiableList(
                new ArrayList<>(entries));
    }

    public synchronized int size()
    {
        return entries.size();
    }

    public synchronized void clear()
    {
        entries.clear();
        save();
    }

    public synchronized void enforceLimit()
    {
        final int before = entries.size();

        trim();

        if (entries.size() != before)
        {
            save();
        }
    }

    /**
     * Reload persistent mention history from disk.
     *
     * MentionHistoryService is owned by RuneLite/Guice and may remain alive
     * across RuneTags disable/enable cycles. Reloading here ensures each
     * plugin startup reflects the current contents of history.json.
     */
    public synchronized void reload()
    {
        load();
    }

    private void load()
    {
        entries.clear();

        if (Files.isRegularFile(historyFile))
        {
            if (loadFile())
            {
                removeLegacyConfig();
            }

            return;
        }

        migrateLegacyConfig();
    }

    private boolean loadFile()
    {
        try (BufferedReader reader =
                     Files.newBufferedReader(
                             historyFile,
                             StandardCharsets.UTF_8))
        {
            final PersistedStore store =
                    gson.fromJson(
                            reader,
                            PersistedStore.class);

            if (!isValidStore(store))
            {
                log.warn(
                        "[RuneTags][Mention-History] Ignoring Invalid Store '{}'",
                        historyFile);
                return false;
            }

            loadStore(store);
            return true;
        }
        catch (Exception exception)
        {
            log.warn(
                    "[RuneTags][Mention-History] Unable to Load from '{}'",
                    historyFile,
                    exception);
            return false;
        }
    }

    private void migrateLegacyConfig()
    {
        if (configManager == null)
        {
            return;
        }

        final String json =
                configManager.getConfiguration(
                        Constants.CONFIG_GROUP,
                        LEGACY_CONFIG_KEY);

        if (json == null
                || json.trim().isEmpty())
        {
            return;
        }

        try
        {
            final PersistedStore store =
                    gson.fromJson(
                            json,
                            PersistedStore.class);

            if (!isValidStore(store))
            {
                log.warn(
                        "[RuneTags][Mention-History] Legacy Config Store is Invalid; Leaving it Untouched");
                return;
            }

            entries.clear();
            loadStore(store);
            save();

            entries.clear();
            if (!loadFile())
            {
                log.warn(
                        "[RuneTags][Mention-History] Migration Verification Failed; Legacy Config Preserved");
                entries.clear();
                loadStore(store);
                return;
            }

            removeLegacyConfig();
            log.info(
                    "[RuneTags][Mention-History] Migrated Legacy ConfigManager History to '{}'",
                    historyFile);
        }
        catch (RuntimeException exception)
        {
            log.warn(
                    "[RuneTags][Mention-History] Unable to Migrate Legacy ConfigManager History | ERROR: {}",
                    exception.getMessage());
        }
    }

    private void loadStore(
            PersistedStore store)
    {
        if (store == null
                || store.entries == null)
        {
            return;
        }

        for (PersistedEntry persisted : store.entries)
        {
            final MentionHistoryEntry entry =
                    fromPersisted(persisted);

            if (entry != null)
            {
                entries.addLast(entry);
            }
        }

        trim();
    }

    private static boolean isValidStore(
            PersistedStore store)
    {
        return store != null
                && store.version == STORE_VERSION
                && store.entries != null;
    }

    private void save()
    {
        final PersistedStore store =
                new PersistedStore();

        store.version = STORE_VERSION;
        store.entries = new ArrayList<>();

        for (MentionHistoryEntry entry : entries)
        {
            store.entries.add(toPersisted(entry));
        }

        try
        {
            Files.createDirectories(historyDirectory);

            try (BufferedWriter writer =
                         Files.newBufferedWriter(
                                 historyTempFile,
                                 StandardCharsets.UTF_8))
            {
                gson.newBuilder()
                        .setPrettyPrinting()
                        .create()
                        .toJson(
                                store,
                                PersistedStore.class,
                                writer);
            }

            moveIntoPlace(
                    historyTempFile,
                    historyFile);
        }
        catch (IOException exception)
        {
            log.warn(
                    "[RuneTags][Mention-History] Unable to Save to '{}'",
                    historyFile,
                    exception);
        }
    }

    private void removeLegacyConfig()
    {
        if (configManager == null)
        {
            return;
        }

        final String json =
                configManager.getConfiguration(
                        Constants.CONFIG_GROUP,
                        LEGACY_CONFIG_KEY);

        if (json == null
                || json.trim().isEmpty())
        {
            return;
        }

        try
        {
            configManager.unsetConfiguration(
                    Constants.CONFIG_GROUP,
                    LEGACY_CONFIG_KEY);
        }
        catch (RuntimeException exception)
        {
            log.warn(
                    "[RuneTags][Mention-History] Unable to Remove Migrated Legacy Config",
                    exception);
        }
    }

    private static void moveIntoPlace(
            Path source,
            Path target)
            throws IOException
    {
        try
        {
            Files.move(
                    source,
                    target,
                    StandardCopyOption.REPLACE_EXISTING,
                    StandardCopyOption.ATOMIC_MOVE);
        }
        catch (IOException atomicMoveFailure)
        {
            Files.move(
                    source,
                    target,
                    StandardCopyOption.REPLACE_EXISTING);
        }
    }

    private void trim()
    {
        final int maximum =
                Math.max(
                        1,
                        config.maximumHistory());

        while (entries.size() > maximum)
        {
            entries.removeLast();
        }
    }

    private static PersistedEntry toPersisted(
            MentionHistoryEntry entry)
    {
        final PersistedEntry persisted =
                new PersistedEntry();

        persisted.messageId =
                entry.getMessageId();

        persisted.sender =
                entry.getSender();
        persisted.message =
                entry.getMessage();

        persisted.chatType =
                entry.getChatType() != null
                        ? entry.getChatType().name()
                        : null;
        persisted.matchReason =
                entry.getMatchReason() != null
                        ? entry.getMatchReason().name()
                        : null;

        persisted.world =
                entry.getWorld();
        persisted.locationName =
                entry.getLocationName();
        persisted.channelName =
                entry.getChannelName();

        persisted.timestampMillis =
                entry.getTimestamp() != null
                        ? entry.getTimestamp().toEpochMilli()
                        : System.currentTimeMillis();

        return persisted;
    }

    private static MentionHistoryEntry fromPersisted(
            PersistedEntry persisted)
    {
        if (persisted == null)
        {
            return null;
        }

        final ChatMessageType chatType;

        try
        {
            chatType =
                    persisted.chatType != null
                            ? ChatMessageType.valueOf(
                            persisted.chatType)
                            : null;
        }
        catch (IllegalArgumentException ex)
        {
            return null;
        }

        final MatchReason matchReason;

        try
        {
            matchReason =
                    persisted.matchReason != null
                            ? MatchReason.valueOf(
                            persisted.matchReason)
                            : null;
        }
        catch (IllegalArgumentException ex)
        {
            return null;
        }

        return new MentionHistoryEntry(
                persisted.messageId,
                persisted.sender,
                persisted.message,
                chatType,
                matchReason,
                persisted.world,
                persisted.locationName,
                persisted.channelName,
                Instant.ofEpochMilli(
                        persisted.timestampMillis));
    }

    /*
     * Store primitives and enum names instead of RuneLite objects or Instant so
     * the persisted format remains simple and tolerant of internal model changes.
     */
    private static class PersistedEntry
    {
        long messageId;

        String sender;
        String message;

        String chatType;
        String matchReason;

        Integer world;
        String locationName;
        String channelName;

        long timestampMillis;
    }
    private static final class PersistedStore
    {
        private int version =
                STORE_VERSION;

        private List<PersistedEntry> entries =
                new ArrayList<>();
    }

}

package com.runetags.history;

