                new BorderLayout());

        add(
                buildHeader(),
                BorderLayout.NORTH);

        entriesPanel.setLayout(
                new BoxLayout(
                        entriesPanel,
                        BoxLayout.Y_AXIS));

        entriesPanel.setBackground(
                ColorScheme.DARK_GRAY_COLOR);

        final JScrollPane scrollPane =
                new JScrollPane(
                        entriesPanel);

        scrollPane.setBorder(null);

        scrollPane.getVerticalScrollBar()
                .setUnitIncrement(16);

        add(
                scrollPane,
                BorderLayout.CENTER);

        /*
         * Keep the footer outside the scrolling history list.
         */
        add(
                buildFooter(),
                BorderLayout.SOUTH);

        /*
         * Relative ages have minute-level precision after "now", so a 30-second
         * refresh keeps them current without rebuilding the history panel.
         */
        ageRefreshTimer =
                new Timer(
                        30_000,
                        event -> refreshAgeLabels());

        ageRefreshTimer.start();

        reload();
    }

