    private static class RoundedPanel extends JPanel
    {
        private final int arc;
        private final Color borderColor;

        private RoundedPanel(
                int arc,
                Color borderColor)
        {
            this.arc =
                    arc;

            this.borderColor =
                    borderColor;

            setOpaque(false);
        }

        @Override
        protected void paintComponent(
                java.awt.Graphics graphics)
        {
            super.paintComponent(graphics);

            final java.awt.Graphics2D graphics2D =
                    (java.awt.Graphics2D) graphics.create();

            try
            {
                graphics2D.setRenderingHint(
                        java.awt.RenderingHints.KEY_ANTIALIASING,
                        java.awt.RenderingHints.VALUE_ANTIALIAS_ON);

                graphics2D.setColor(
                        getBackground());

                final int inset =
                        1;

                final int width =
                        Math.max(
                                0,
                                getWidth()
                                        - (inset * 2)
                                        - 1);

                final int height =
                        Math.max(
                                0,
                                getHeight()
                                        - (inset * 2)
                                        - 1);

                graphics2D.fillRoundRect(
                        inset,
                        inset,
                        width,
                        height,
                        arc,
                        arc);

                if (borderColor != null)
                {
                    graphics2D.setColor(
                            borderColor);

                    graphics2D.drawRoundRect(
                            inset,
                            inset,
                            width,
                            height,
                            arc,
                            arc);
                }
            }
            finally
            {
                graphics2D.dispose();
            }
        }
    }

    public void reload()
    {
        if (!SwingUtilities.isEventDispatchThread())
        {
            SwingUtilities.invokeLater(
                    this::reload);
            return;
        }

        final List<MentionHistoryEntry> entries =
                historyService.snapshot();

        countLabel.setText(
                "Total Mentions: "
                        + entries.size());

        entriesPanel.removeAll();
        ageLabels.clear();
        favoriteLabels.clear();

        if (entries.isEmpty())
        {
            final JLabel empty =
                    new JLabel(
                            "No mentions yet.");

            empty.setForeground(
                    ColorScheme.LIGHT_GRAY_COLOR);

            empty.setBorder(
                    BorderFactory.createEmptyBorder(
                            12,
                            8,
                            12,
                            8));

            entriesPanel.add(empty);
        }
        else
        {
            for (MentionHistoryEntry entry : entries)
            {
                entriesPanel.add(
                        buildEntry(entry));

                entriesPanel.add(
                        Box.createVerticalStrut(5));
            }
        }

        entriesPanel.revalidate();
        entriesPanel.repaint();
    }

    private JPanel buildEntry(
            MentionHistoryEntry entry)
    {
        final JPanel panel =
                new RoundedPanel(
                        4,
                        ColorScheme.MEDIUM_GRAY_COLOR)
                {
                    @Override
                    public Dimension getMaximumSize()
                    {
                        final Dimension preferred =
                                getPreferredSize();

                        return new Dimension(
                                Integer.MAX_VALUE,
                                preferred.height);
                    }
                };

        panel.setLayout(
                new BoxLayout(
                        panel,
                        BoxLayout.Y_AXIS));

        panel.setAlignmentX(
                LEFT_ALIGNMENT);

        panel.setBackground(
                ColorScheme.DARKER_GRAY_COLOR);

        panel.setBorder(
                BorderFactory.createEmptyBorder(
                        7,
                        8,
                        7,
                        8));

        panel.setCursor(
                Cursor.getPredefinedCursor(
                        Cursor.HAND_CURSOR));

        final String sender =
                safe(
                        entry.getSender(),
                        "Unknown");

        final JPanel senderRow =
                new JPanel(
                        new BorderLayout());

        senderRow.setOpaque(false);

        senderRow.setAlignmentX(
                LEFT_ALIGNMENT);

        senderRow.setMaximumSize(
                new Dimension(
                        Integer.MAX_VALUE,
                        senderRow.getPreferredSize().height));

        final JLabel senderLabel =
                new JLabel(
                        sender);

        senderLabel.setFont(
                senderLabel.getFont()
                        .deriveFont(
                                Font.BOLD));

        final FavoriteLabelBinding favoriteBinding =
                new FavoriteLabelBinding(
                        senderLabel,
                        sender,
                        senderLabel.getForeground());

        favoriteLabels.add(
                favoriteBinding);

        applyFavoriteAppearance(
                favoriteBinding);

        final JLabel ageLabel =
                new JLabel(
                        ageText(
                                entry.getTimestamp()));

        ageLabels.add(
                new AgeLabelBinding(
                        ageLabel,
                        entry.getTimestamp()));

        ageLabel.setFont(
                ageLabel.getFont()
                        .deriveFont(
                                Font.BOLD));

        senderRow.add(
                senderLabel,
                BorderLayout.WEST);

        senderRow.add(
                ageLabel,
                BorderLayout.EAST);

        panel.add(senderRow);

        panel.add(
                Box.createVerticalStrut(3));

        final String context =
                contextText(entry);

        JLabel contextLabel = null;
        if (!context.isEmpty())
        {
            contextLabel =
                    smallLabel(context);

            panel.add(
                    contextLabel);
        }

        final String channel =
                channelText(entry);

        JLabel channelLabel = null;
        if (!channel.isEmpty())
        {
            channelLabel =
                    smallLabel(channel);

            panel.add(
                    channelLabel);
        }

        panel.add(
                Box.createVerticalStrut(5));

        /*
         * Use RuneLite's medium gray here so the blue mention text remains the visual
         * focus of the history entry.
         */
        final JPanel messageField =
                new RoundedPanel(8, ColorScheme.MEDIUM_GRAY_COLOR);

        messageField.setLayout(
                new BorderLayout());

        messageField.setAlignmentX(
                LEFT_ALIGNMENT);

        messageField.setBackground(
                ColorScheme.DARK_GRAY_COLOR);

        messageField.setBorder(
                BorderFactory.createEmptyBorder(
                        4,
                        6,
                        4,
                        6));

        messageField.setCursor(
                Cursor.getPredefinedCursor(
                        Cursor.HAND_CURSOR));

        final JTextArea message =
                new JTextArea(
                        safe(
                                entry.getMessage(),
                                ""))
                {
                    @Override
                    public Dimension getPreferredSize()
                    {
                        final Dimension preferred =
                                super.getPreferredSize();

                        /*
                         * Once the component has a real width, recalculate wrapped height against that
                         * width instead of retaining the initial single-line preferred size.
                         */
                        if (getWidth() > 0)
                        {
                            setSize(
                                    new Dimension(
                                            getWidth(),
                                            Short.MAX_VALUE));

                            return super.getPreferredSize();
                        }

                        return preferred;
                    }
                };

        message.setEditable(false);
        message.setLineWrap(true);
        message.setWrapStyleWord(true);
        message.setOpaque(false);

        /*
         * Apply the mention color only to the message;
         * sender and contextual metadata retain their RuneLite colors.
         */
        message.setForeground(
                new Color(
                        144,
                        144,
                        255));

        message.setFont(
                panel.getFont());

        message.setBorder(null);

        message.setCursor(
                Cursor.getPredefinedCursor(
                        Cursor.HAND_CURSOR));

        messageField.add(
                message,
                BorderLayout.CENTER);

        panel.add(messageField);

        final MouseAdapter opener =
                new MouseAdapter()
                {
                    @Override
                    public void mouseEntered(
                            MouseEvent event)
                    {
                        panel.setBackground(new Color(20,20,20));

                        panel.repaint();
                    }

                    @Override
                    public void mouseExited(
                            MouseEvent event)
                    {
                        /*
                         * Restore the normal card color only after the mouse leaves the entire history entry.
                         */
                        final Point mousePoint =
                                SwingUtilities.convertPoint(
                                        event.getComponent(),
                                        event.getPoint(),
                                        panel);

                        if (!panel.contains(mousePoint))
                        {
                            panel.setBackground(
                                    ColorScheme.DARKER_GRAY_COLOR);

                            panel.repaint();
                        }
                    }

                    @Override
                    public void mouseClicked(
                            MouseEvent event)
                    {
                        if (event.getButton()
                                != MouseEvent.BUTTON1)
                        {
                            return;
                        }

                        final Point clickPoint =
                                event.getLocationOnScreen();

                        SwingUtilities.convertPointFromScreen(
                                clickPoint,
                                client.getCanvas());

                        quickProfileController.openPlayer(
                                entry.getSender(),
                                entry.getChatType(),
                                clickPoint);
                    }
                };

        /*
         * All visible child components share the entry's hover and click behavior,
         * while only the outer card owns the background state.
         */
        panel.addMouseListener(opener);
        senderRow.addMouseListener(opener);
        senderLabel.addMouseListener(opener);
        ageLabel.addMouseListener(opener);
        if (contextLabel != null)
        {
            contextLabel.addMouseListener(opener);
        }
        if (channelLabel != null)
        {
            channelLabel.addMouseListener(opener);
        }
        messageField.addMouseListener(opener);
        message.addMouseListener(opener);

        return panel;
    }

