    private static String channelText(
            MentionHistoryEntry entry)
    {
        final String type =
                readableChatType(
                        entry.getChatType());

        final String channelName =
                entry.getChannelName();

        if (channelName == null
                || channelName.trim().isEmpty())
        {
            return type;
        }

        return type
                + " \u2022 "
                + channelName;
    }

    private static String contextText(
            MentionHistoryEntry entry)
    {
        final StringBuilder text =
                new StringBuilder();

        if (entry.getWorld() != null)
        {
            text.append(
                            "World ")
                    .append(
                            entry.getWorld());
        }

        if (entry.getLocationName() != null
                && !entry.getLocationName()
                .trim()
                .isEmpty())
        {
            if (text.length() > 0)
            {
                text.append(
                        " \u2022 ");
            }

            text.append(
                    entry.getLocationName());
        }

        return text.toString();
    }

    private static String readableChatType(
            ChatMessageType type)
    {
        if (type == null)
        {
            return "";
        }

        switch (type)
        {
            case PUBLICCHAT:
            case MODCHAT:
                return "Public";

            case FRIENDSCHAT:
                return "Friends Chat";

            case CLAN_CHAT:
            case CLAN_GIM_CHAT:
                return "Clan";

            case CLAN_GUEST_CHAT:
                return "Guest Clan";

            case PRIVATECHAT:
            case MODPRIVATECHAT:
            case PRIVATECHATOUT:
                return "Private";

            default:
                return type.name();
        }
    }

    private static String ageText(
            Instant timestamp)
    {
        if (timestamp == null)
        {
            return "";
        }

        final Instant now =
                Instant.now();

        final long seconds =
                Math.max(
                        0,
                        Duration.between(
                                        timestamp,
                                        now)
                                .getSeconds());

        if (seconds < 60)
        {
            return "now";
        }

        final long minutes =
                seconds / 60;

        if (minutes < 60)
        {
            return minutes + "m";
        }

        final long hours =
                minutes / 60;

        if (hours < 24)
        {
            return hours + "h";
        }

        final long days =
                hours / 24;

        if (days < 7)
        {
            return days + "d";
        }

        final java.time.ZoneId zone =
                java.time.ZoneId.systemDefault();

        final java.time.LocalDate date =
                timestamp.atZone(zone)
                        .toLocalDate();

        final java.time.LocalDate today =
                now.atZone(zone)
                        .toLocalDate();

        final java.time.format.DateTimeFormatter formatter =
                date.getYear() == today.getYear()
                        ? java.time.format.DateTimeFormatter.ofPattern("MMM dd")
                        : java.time.format.DateTimeFormatter.ofPattern("MMM dd, yy");

        return formatter.format(date);
    }

    /**
     * Refresh only Favorite sender-name presentation without rebuilding history
     * entries or disturbing the current scroll position.
     */
    public void refreshFavoriteAppearance()
    {
        if (!SwingUtilities.isEventDispatchThread())
        {
            SwingUtilities.invokeLater(
                    this::refreshFavoriteAppearance);
            return;
        }

        for (FavoriteLabelBinding binding : favoriteLabels)
        {
            applyFavoriteAppearance(
                    binding);
        }

        entriesPanel.repaint();
    }

    private void applyFavoriteAppearance(
            FavoriteLabelBinding binding)
    {
        if (binding == null
                || binding.label == null)
        {
            return;
        }

        final boolean favorite =
                config != null
                        && config.showFavorites()
                        && localPlayerRecordService != null
                        && localPlayerRecordService.isFavorite(
                        binding.playerName);

        final Color favoriteColor =
                config != null
                        && config.favoriteColor() != null
                        ? config.favoriteColor()
                        : new Color(255, 205, 70);

        binding.label.setForeground(
                favorite
                        ? favoriteColor
                        : binding.normalColor);
    }

    private void refreshAgeLabels()
    {
        if (!SwingUtilities.isEventDispatchThread())
        {
            SwingUtilities.invokeLater(
                    this::refreshAgeLabels);
            return;
        }

        for (AgeLabelBinding binding : ageLabels)
        {
            binding.label.setText(
                    ageText(
                            binding.timestamp));
        }
    }

