package com.runetags.mention;

import com.runetags.player.PlayerIdentity;
import com.runetags.reference.PlayerReference;
import com.runetags.reference.ReferenceType;
import com.runetags.player.PlayerDirectory;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class TagParser
{
    private static final Pattern TAG_PATTERN = Pattern.compile("@([A-Za-z0-9_-]+)");

    private final NameNormalizer nameNormalizer;
    private final PlayerDirectory playerDirectory;

    public TagParser(NameNormalizer nameNormalizer, PlayerDirectory playerDirectory)
    {
        this.nameNormalizer = nameNormalizer;
        this.playerDirectory = playerDirectory;
    }

    public List<PlayerReference> parse(String message)
    {
        final List<PlayerReference> references = new ArrayList<>();

        if (message == null || message.isEmpty())
        {
            return references;
        }

        final Matcher matcher = TAG_PATTERN.matcher(message);

        while (matcher.find())
        {
            final String token =
                    matcher.group(1);

            final String canonicalLookupName =
                    nameNormalizer.canonicalize(token);

            final Optional<PlayerIdentity> identity =
                    playerDirectory.find(canonicalLookupName);

            final String resolvedLookupName =
                    identity
                            .map(PlayerIdentity::getCanonicalName)
                            .orElse(canonicalLookupName);

            references.add(
                    PlayerReference.builder()
                            .rawText(matcher.group(0))
                            .normalizedToken(
                                    nameNormalizer.taggedToken(token))
                            .lookupName(resolvedLookupName)
                            .startOffset(matcher.start())
                            .endOffset(matcher.end())
                            .type(ReferenceType.TAG)
                            .locallyResolved(identity.isPresent())
                            .identity(identity.orElse(null))
                            .build());
        }

        return references;
    }
}

package com.runetags.mention;

import com.runetags.player.PlayerIdentity;
import com.runetags.reference.PlayerReference;
import com.runetags.reference.ReferenceType;
import com.runetags.player.PlayerDirectory;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

public class KnownPlayerMentionParser
{
    private final PlayerDirectory playerDirectory;
    private final NameNormalizer normalizer;

    public KnownPlayerMentionParser(
            PlayerDirectory playerDirectory,
            NameNormalizer normalizer)
    {
        this.playerDirectory = playerDirectory;
        this.normalizer = normalizer;
    }

    public List<PlayerReference> parse(
            String message,
            List<PlayerReference> reservedReferences)
    {
        final List<PlayerReference> matches =
                new ArrayList<>();

        if (message == null || message.isEmpty())
        {
            return matches;
        }

        final String lowered =
                message.toLowerCase(Locale.ROOT);

        /*
         * Preserve longest-name-first identity ordering so more specific player names
         * retain overlap priority.
         */
        final List<PlayerIdentity> identities =
                playerDirectory.allSortedLongestNameFirst();

        /*
         * Build normalized message spans once per message and index them by comparison
         * key. Original offsets are retained so normalized fallback matches can still
         * produce exact PlayerReference spans.
         */
        final Map<String, List<NormalizedMessageSpan>> normalizedSpanIndex =
                buildNormalizedSpanIndex(message);

        for (PlayerIdentity identity : identities)
        {
            final String canonical =
                    identity.getCanonicalName();

            if (canonical == null || canonical.isEmpty())
            {
                continue;
            }

            findVariant(
                    message,
                    lowered,
                    canonical,
                    identity,
                    matches,
                    reservedReferences);

            findVariant(
                    message,
                    lowered,
                    canonical.replace(' ', '_'),
                    identity,
                    matches,
                    reservedReferences);

            findVariant(
                    message,
                    lowered,
                    canonical.replace(' ', '-'),
                    identity,
                    matches,
                    reservedReferences);

            /*
             * Fall back to normalized matching when a RuneScape name's source
             * representation differs in separator usage.
             *
             * For example, "Santaclause" and "Santa clause" share the same comparison key.
             */
            findNormalizedVariant(
                    message,
                    identity,
                    normalizedSpanIndex,
                    matches,
                    reservedReferences);
        }

        matches.sort(
                Comparator.comparingInt(
                        PlayerReference::getStartOffset));

        return removeOverlaps(matches);
    }

    private void findVariant(
            String original,
            String lowered,
            String candidate,
            PlayerIdentity identity,
            List<PlayerReference> output,
            List<PlayerReference> reserved)
    {
        if (candidate == null || candidate.isEmpty())
        {
            return;
        }

        final String needle =
                candidate.toLowerCase(Locale.ROOT);

        int from = 0;

        while (from <= lowered.length() - needle.length())
        {
            final int start =
                    lowered.indexOf(needle, from);

            if (start < 0)
            {
                return;
            }

            final int end =
                    start + needle.length();

            if (hasBoundaries(lowered, start, end)
                    && !isInsideExplicitTag(lowered, start)
                    && !overlapsAny(start, end, reserved)
                    && !overlapsAny(start, end, output))
            {
                addReference(
                        original,
                        start,
                        end,
                        identity,
                        output);
            }

            from = start + 1;
        }
    }

    private void findNormalizedVariant(
            String original,
            PlayerIdentity identity,
            Map<String, List<NormalizedMessageSpan>> normalizedSpanIndex,
            List<PlayerReference> output,
            List<PlayerReference> reserved)
    {
        String targetKey =
                identity.getNormalizedName();

        if (targetKey == null
                || targetKey.isEmpty())
        {
            targetKey =
                    normalizer.comparisonKey(
                            identity.getCanonicalName());
        }

        if (targetKey.isEmpty())
        {
            return;
        }

        final List<NormalizedMessageSpan> candidates =
                normalizedSpanIndex.get(targetKey);

        if (candidates == null || candidates.isEmpty())
        {
            return;
        }

        /*
         * Preserve candidate discovery order so longest-name-first identity ordering
         * continues to determine overlap priority.
         */
        for (NormalizedMessageSpan candidate : candidates)
        {
            final int start = candidate.start;
            final int end = candidate.end;

            if (!hasBoundaries(original, start, end)
                    || overlapsAny(start, end, reserved)
                    || overlapsAny(start, end, output))
            {
                continue;
            }

            addReference(
                    original,
                    start,
                    end,
                    identity,
                    output);
        }
    }

    private Map<String, List<NormalizedMessageSpan>> buildNormalizedSpanIndex(
            String original)
    {
        final Map<String, List<NormalizedMessageSpan>> index =
                new HashMap<>();

        for (int start = 0; start < original.length(); start++)
        {
            if (!isNameChar(original.charAt(start)))
            {
                continue;
            }

            if (start > 0
                    && isNameChar(original.charAt(start - 1)))
            {
                continue;
            }

            if (isInsideExplicitTag(original, start))
            {
                continue;
            }

            for (int end = start + 1;
                 end <= original.length();
                 end++)
            {
                final char last =
                        original.charAt(end - 1);

                if (!isNameChar(last) && last != ' ')
                {
                    break;
                }

                if (end < original.length()
                        && isNameChar(original.charAt(end)))
                {
                    continue;
                }

                final String candidate =
                        original.substring(start, end);

                final String candidateKey =
                        normalizer.comparisonKey(candidate);

                if (candidateKey.isEmpty())
                {
                    continue;
                }

                index.computeIfAbsent(
                                candidateKey,
                                ignored -> new ArrayList<>())
                        .add(new NormalizedMessageSpan(start, end));
            }
        }

        return index;
    }

    private void addReference(
            String original,
            int start,
            int end,
            PlayerIdentity identity,
            List<PlayerReference> output)
    {
        output.add(
                PlayerReference.builder()
                        .rawText(original.substring(start, end))
                        .normalizedToken(
                                normalizer.taggedToken(
                                        identity.getCanonicalName()))
                        .lookupName(
                                identity.getCanonicalName())
                        .startOffset(start)
                        .endOffset(end)
                        .type(ReferenceType.MENTION)
                        .locallyResolved(true)
                        .identity(identity)
                        .build());
    }

    private static boolean hasBoundaries(
            String text,
            int start,
            int end)
    {
        return (start == 0
                || !isNameChar(text.charAt(start - 1)))
                && (end == text.length()
                || !isNameChar(text.charAt(end)));
    }

    private static boolean isInsideExplicitTag(
            String text,
            int start)
    {
        return start > 0
                && text.charAt(start - 1) == '@';
    }

    private static boolean isNameChar(char c)
    {
        return Character.isLetterOrDigit(c)
                || c == '_'
                || c == '-';
    }

    private static boolean overlapsAny(
            int start,
            int end,
            List<PlayerReference> references)
    {
        if (references == null)
        {
            return false;
        }

        for (PlayerReference reference : references)
        {
            if (start < reference.getEndOffset()
                    && end > reference.getStartOffset())
            {
                return true;
            }
        }

        return false;
    }

    private static List<PlayerReference> removeOverlaps(
            List<PlayerReference> references)
    {
        final List<PlayerReference> result =
                new ArrayList<>();

        for (PlayerReference reference : references)
        {
            if (!overlapsAny(
                    reference.getStartOffset(),
                    reference.getEndOffset(),
                    result))
            {
                result.add(reference);
            }
        }

        return result;
    }

    private static final class NormalizedMessageSpan
    {
        private final int start;
        private final int end;

        private NormalizedMessageSpan(
                int start,
                int end)
        {
            this.start = start;
            this.end = end;
        }
    }
}

package com.runetags.mention;

import java.util.Locale;
import java.util.regex.Pattern;
import net.runelite.client.util.Text;

public class NameNormalizer
{
    private static final Pattern SEPARATORS = Pattern.compile("[ _-]+");
    private static final Pattern NON_NAME_CHARS = Pattern.compile("[^A-Za-z0-9 _-]");

    public NormalizedPlayerName normalize(String raw)
    {
        final String canonical = canonicalize(raw);
        final String lowercase = canonical.toLowerCase(Locale.ROOT);
        final String comparison = SEPARATORS.matcher(lowercase).replaceAll("");
        final String tagged = SEPARATORS.matcher(lowercase).replaceAll("_");

        return new NormalizedPlayerName(canonical, comparison, tagged);
    }

    public String comparisonKey(String raw)
    {
        return normalize(raw).getComparisonKey();
    }

    public String taggedToken(String raw)
    {
        return normalize(raw).getTaggedToken();
    }

    public String canonicalize(String raw)
    {
        if (raw == null)
        {
            return "";
        }

        String clean = Text.removeTags(raw).trim();

        /*
         * RuneScape/RuneLite social lists may represent player-name spaces as
         * non-breaking spaces. Normalize them before filtering characters so the
         * separator is preserved.
         */
        clean = clean
                .replace('\u00A0', ' ')
                .replace('\u202F', ' ');

        clean = NON_NAME_CHARS.matcher(clean).replaceAll("");
        clean = clean.replace('_', ' ').replace('-', ' ');
        clean = clean.replaceAll("\\s+", " ").trim();

        return clean;
    }
}

package com.runetags.mention;

import com.runetags.Configurations;
import com.runetags.reference.PlayerReference;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import java.util.stream.Collectors;

public class LocalMentionMatcher
{
    private final Configurations config;
    private final NameNormalizer normalizer;

    public LocalMentionMatcher(
            Configurations config,
            NameNormalizer normalizer)
    {
        this.config = config;
        this.normalizer = normalizer;
    }

    /**
     * Match a structured player reference against the local player or one of
     * the user's Unique Highlights.
     *
     * Unique Highlights are notification triggers only. They never remap the
     * PlayerReference identity.
     */
    public LocalMentionMatch match(
            PlayerReference reference,
            String localPlayerName)
    {
        if (reference == null
                || localPlayerName == null
                || localPlayerName.isEmpty())
        {
            return LocalMentionMatch.none();
        }

        final String referenceText =
                reference.getRawText().replaceFirst("^@", "");

        final String referenceKey =
                normalizer.comparisonKey(referenceText);

        final String localKey =
                normalizer.comparisonKey(localPlayerName);

        /*
         * Local-account identity takes precedence over Unique Highlights.
         */
        if (!referenceKey.isEmpty()
                && referenceKey.equals(localKey))
        {
            return new LocalMentionMatch(
                    true,
                    MatchReason.ACCOUNT_NAME,
                    reference.getRawText());
        }

        /*
         * A Unique Highlight affects notification/highlight behavior without
         * associating the reference with the local account.
         */
        if (uniqueHighlightKeys().contains(referenceKey))
        {
            return new LocalMentionMatch(
                    true,
                    MatchReason.UNIQUE_HIGHLIGHT,
                    reference.getRawText());
        }

        return LocalMentionMatch.none();
    }

    /**
     * Scan ordinary message text for a local-account variant or configured
     * Unique Highlight.
     *
     * Returns the match reason so notification, history, and logging consumers can
     * distinguish local-account matches from Unique Highlights.
     */
    public LocalMentionMatch matchMessage(
            String message,
            String localPlayerName)
    {
        if (message == null || message.isEmpty())
        {
            return LocalMentionMatch.none();
        }

        final String lowered =
                message.toLowerCase(Locale.ROOT);

        /*
         * Local-account variants take priority over Unique Highlights.
         */
        if (localPlayerName != null
                && !localPlayerName.isEmpty())
        {
            final String canonical =
                    normalizer.canonicalize(localPlayerName)
                            .toLowerCase(Locale.ROOT);

            final String tagged =
                    normalizer.taggedToken(localPlayerName)
                            .toLowerCase(Locale.ROOT);

            final String hyphenated =
                    canonical.replace(' ', '-');

            if (containsWholePhrase(lowered, canonical))
            {
                return new LocalMentionMatch(
                        true,
                        MatchReason.NORMALIZED_ACCOUNT_NAME,
                        canonical);
            }

            if (containsWholePhrase(lowered, tagged))
            {
                return new LocalMentionMatch(
                        true,
                        MatchReason.NORMALIZED_ACCOUNT_NAME,
                        tagged);
            }

            if (containsWholePhrase(lowered, hyphenated))
            {
                return new LocalMentionMatch(
                        true,
                        MatchReason.NORMALIZED_ACCOUNT_NAME,
                        hyphenated);
            }
        }

        for (String trigger : configuredHighlights())
        {
            final String loweredTrigger =
                    trigger.toLowerCase(Locale.ROOT);

            if (containsWholePhrase(lowered, loweredTrigger))
            {
                return new LocalMentionMatch(
                        true,
                        MatchReason.UNIQUE_HIGHLIGHT,
                        trigger);
            }
        }

        return LocalMentionMatch.none();
    }

    private Set<String> uniqueHighlightKeys()
    {
        return configuredHighlights().stream()
                .map(normalizer::comparisonKey)
                .filter(key -> !key.isEmpty())
                .collect(Collectors.toSet());
    }

    private Set<String> configuredHighlights()
    {
        final String configured =
                config.uniqueMentions();

        if (configured == null
                || configured.trim().isEmpty())
        {
            return new HashSet<>();
        }

        return Arrays.stream(configured.split(","))
                .map(String::trim)
                .filter(value -> !value.isEmpty())
                .collect(Collectors.toCollection(HashSet::new));
    }

    private static boolean containsWholePhrase(
            String message,
            String phrase)
    {
        if (phrase == null || phrase.isEmpty())
        {
            return false;
        }

        int from = 0;

        while (from <= message.length() - phrase.length())
        {
            final int index =
                    message.indexOf(phrase, from);

            if (index < 0)
            {
                return false;
            }

            final boolean leftBoundary =
                    index == 0
                            || !isNameChar(message.charAt(index - 1));

            final int right =
                    index + phrase.length();

            final boolean rightBoundary =
                    right == message.length()
                            || !isNameChar(message.charAt(right));

            if (leftBoundary && rightBoundary)
            {
                return true;
            }

            from = index + 1;
        }

        return false;
    }

    private static boolean isNameChar(char c)
    {
        return Character.isLetterOrDigit(c)
                || c == '_'
                || c == '-';
    }
}

package com.runetags.overlay;

import com.runetags.Configurations;
import com.runetags.config.TargetMode;
import com.runetags.target.TargetController;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

public class TargetOverlay extends Overlay
{
    private static final int OUTLINE_WIDTH = 2;
    private static final int OUTLINE_FEATHER = 4;
    private static final int NAME_HEIGHT_OFFSET = 40;

    private final Client client;
    private final Configurations config;
    private final TargetController targetController;
    private final ModelOutlineRenderer modelOutlineRenderer;

    public TargetOverlay(
            Client client,
            Configurations config,
            TargetController targetController,
            ModelOutlineRenderer modelOutlineRenderer)
    {
        this.client = client;
        this.config = config;
        this.targetController = targetController;
        this.modelOutlineRenderer = modelOutlineRenderer;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
        setPriority(OverlayPriority.HIGH);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.targetPlayerOption()
                || client.getGameState() != GameState.LOGGED_IN)
        {
            return null;
        }

        final Player target = targetController.getTargetPlayer();

        if (target == null)
        {
            return null;
        }

        final Color targetColor = config.targetColor();

        final TargetMode targetMode =
                config.targetMode();

        if (targetMode.showsOutline())
        {
            modelOutlineRenderer.drawOutline(
                    target,
                    OUTLINE_WIDTH,
                    targetColor,
                    OUTLINE_FEATHER);
        }

        if (targetMode.showsTile())
        {
            final Polygon tilePoly =
                    target.getCanvasTilePoly();

            if (tilePoly != null)
            {
                OverlayUtil.renderPolygon(
                        graphics,
                        tilePoly,
                        targetColor);
            }
        }

        if (config.targetLine())
        {
            drawTargetLine(graphics, target, targetColor);
        }

        if (config.targetName())
        {
            drawTargetName(graphics, target, targetColor);
        }

        return null;
    }

    private void drawTargetLine(
            Graphics2D graphics,
            Player target,
            Color color)
    {
        final Player localPlayer = client.getLocalPlayer();

        if (localPlayer == null)
        {
            return;
        }

        final LocalPoint localPoint = localPlayer.getLocalLocation();
        final LocalPoint targetPoint = target.getLocalLocation();

        if (localPoint == null || targetPoint == null)
        {
            return;
        }

        final int plane = localPlayer.getWorldLocation().getPlane();

        final Point localCanvas =
                net.runelite.api.Perspective.localToCanvas(
                        client,
                        localPoint,
                        plane);

        final Point targetCanvas =
                net.runelite.api.Perspective.localToCanvas(
                        client,
                        targetPoint,
                        plane);

        if (localCanvas == null || targetCanvas == null)
        {
            return;
        }

        final Color oldColor = graphics.getColor();
        final java.awt.Stroke oldStroke = graphics.getStroke();

        try
        {
            graphics.setColor(color);
            graphics.setStroke(new BasicStroke(2.0f));

            graphics.drawLine(
                    localCanvas.getX(),
                    localCanvas.getY(),
                    targetCanvas.getX(),
                    targetCanvas.getY());
        }
        finally
        {
            graphics.setStroke(oldStroke);
            graphics.setColor(oldColor);
        }
    }

    private static void drawTargetName(
            Graphics2D graphics,
            Player target,
            Color color)
    {
        final String name = target.getName();

        if (name == null || name.isEmpty())
        {
            return;
        }

        final Point textLocation =
                target.getCanvasTextLocation(
                        graphics,
                        name,
                        target.getLogicalHeight() + NAME_HEIGHT_OFFSET);

        if (textLocation != null)
        {
            OverlayUtil.renderTextLocation(
                    graphics,
                    textLocation,
                    name,
                    color);
        }
    }
}

package com.runetags.overlay;

import com.runetags.Configurations;
import com.runetags.chat.ChatHitboxRegistry;
import com.runetags.chat.ReferenceHitbox;
import com.runetags.chat.ReferenceLayoutService;
import com.runetags.chat.ReferenceLayoutService.LayoutResult;
import com.runetags.chat.ReferenceLayoutService.LocalHighlight;
import com.runetags.mention.LocalMentionMatcher;
import com.runetags.mention.LocalMentionMatch;
import com.runetags.reference.PlayerReference;
import com.runetags.reference.ReferenceType;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.Area;
import java.util.ArrayList;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Set;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

/**
 * Renders chat-reference decorations and publishes their current interaction
 * hitboxes across CHATBOX and SPLIT_PRIVATE surfaces.
 *
 * Also renders local-reference backgrounds and unresolved-tag underlines.
 */
public class ChatReferenceOverlay extends Overlay
{
    private static final int BACKGROUND_HORIZONTAL_PADDING = 1;
    private static final int BACKGROUND_VERTICAL_PADDING = 0;

    private static final int MAX_OCCLUSION_WIDGET_DEPTH = 12;

    private final ReferenceLayoutService layoutService;
    private final ChatHitboxRegistry registry;
    private final Client client;
    private final Configurations config;
    private final LocalMentionMatcher localMentionMatcher;

    public ChatReferenceOverlay(
            ReferenceLayoutService layoutService,
            ChatHitboxRegistry registry,
            Client client,
            Configurations config,
            LocalMentionMatcher localMentionMatcher)
    {
        this.layoutService = layoutService;
        this.registry = registry;
        this.client = client;
        this.config = config;
        this.localMentionMatcher = localMentionMatcher;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(OverlayPriority.HIGHEST);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        /*
         * Native chat text is clipped to the chatbox, but ABOVE_WIDGETS overlays are
         * not. Use the visible chat area to constrain RuneTags rendering and input.
         */
        final Widget chatbox =
                client.getWidget(InterfaceID.Chatbox.SCROLLAREA);

        final Rectangle chatboxBounds =
                chatbox != null
                        && !chatbox.isHidden()
                        ? chatbox.getBounds()
                        : null;

        final boolean hasVisibleChatbox =
                chatboxBounds != null
                        && chatboxBounds.width > 0
                        && chatboxBounds.height > 0;

        /*
         * Calculate semantic/reference hitboxes from the rendered chat.
         */
        final LayoutResult layoutResult =
                layoutService.layout();

        final List<ReferenceHitbox> hitboxes =
                layoutResult.getHitboxes();

        final List<LocalHighlight> localHighlights =
                layoutResult.getLocalHighlights();

        /*
         * CHATBOX references are clipped to the visible chat history, including
         * partially scrolled rows. SPLIT_PRIVATE references come from visible PmChat
         * widgets outside CHATBOX_MESSAGE_LINES and must not use that clip.
         */
        final Widget splitPrivateRoot =
                client.getWidget(InterfaceID.PmChat.CONTAINER);

        /*
         * ABOVE_WIDGETS is not automatically obscured by interfaces covering chat, so
         * respect RuneScape's native no-click-through regions explicitly.
         */
        final Rectangle interactionBounds =
                unionInteractionBounds(
                        hitboxes,
                        localHighlights);

        final List<Rectangle> blockingBounds =
                collectBlockingWidgetBounds(
                        chatbox,
                        splitPrivateRoot,
                        interactionBounds);

        final List<ReferenceHitbox> visibleHitboxes =
                new ArrayList<>();

        for (ReferenceHitbox hitbox : hitboxes)
        {
            if (hitbox == null
                    || hitbox.getBounds() == null)
            {
                continue;
            }

            Rectangle visibleBounds =
                    new Rectangle(
                            hitbox.getBounds());

            switch (hitbox.getSurface())
            {
                case CHATBOX:
                    if (!hasVisibleChatbox
                            || !chatboxBounds.intersects(
                            visibleBounds))
                    {
                        continue;
                    }

                    visibleBounds =
                            chatboxBounds.intersection(
                                    visibleBounds);
                    break;

                case SPLIT_PRIVATE:
                    break;

                default:
                    continue;
            }

            if (visibleBounds.isEmpty())
            {
                continue;
            }

            /*
             * Preserve visible fragments when an interface
             * obscures only part of a reference.
             */
            for (Rectangle fragment
                    : subtractBlockingBounds(
                    visibleBounds,
                    blockingBounds))
            {
                if (fragment == null
                        || fragment.isEmpty())
                {
                    continue;
                }

                visibleHitboxes.add(
                        new ReferenceHitbox(
                                hitbox.getMessageId(),
                                fragment,
                                hitbox.getReference(),
                                hitbox.getSurface()));
            }
        }

        registry.replace(visibleHitboxes);

        final Player localPlayer =
                client.getLocalPlayer();

        final String localPlayerName =
                localPlayer != null
                        ? localPlayer.getName()
                        : null;

        final Color originalColor =
                graphics.getColor();

        final Shape originalClip =
                graphics.getClip();

        final Shape unobscuredClip =
                buildUnobscuredClip(
                        originalClip,
                        blockingBounds);

        try
        {
            /*
             * Draw non-clickable local/self backgrounds before clickable reference
             * decorations so reference decoration remains visually above them.
             */
            drawLocalHighlights(
                    graphics,
                    localHighlights,
                    chatboxBounds,
                    hasVisibleChatbox,
                    unobscuredClip);

            graphics.setColor(
                    originalColor);

            /*
             * Render each reference independently because CHATBOX
             * and SPLIT_PRIVATE use different clipping rules.
             */
            for (ReferenceHitbox hitbox : visibleHitboxes)
            {
                final PlayerReference reference =
                        hitbox.getReference();

                if (reference == null)
                {
                    continue;
                }

                graphics.setClip(unobscuredClip);

                if (hitbox.getSurface()
                        == ReferenceLayoutService.Surface.CHATBOX)
                {
                    /*
                     * Clip CHATBOX decorations so ABOVE_WIDGETS rendering
                     * cannot escape the visible chat history.
                     */
                    graphics.clip(chatboxBounds);
                }

                /*
                 * SENDER is an interaction target, not a semantic mention,
                 * so clickable sender names must not receive mention highlighting.
                 */
                if (reference.getType() != ReferenceType.SENDER
                        && config.highlightBackground())
                {
                    drawReferenceBackground(
                            graphics,
                            hitbox,
                            localPlayerName);
                }

                /*
                 * Unresolved tags retain their dotted underline on either chat surface.
                 */
                if (config.underlineMentions()
                        && reference.getType() == ReferenceType.TAG
                        && !reference.isLocallyResolved())
                {
                    drawDottedUnderline(
                            graphics,
                            hitbox.getBounds(),
                            config.otherMentionColor());
                }
            }
        }
        finally
        {
            /*
             * Always restore Graphics2D state because RuneLite shares this
             * graphics context with other overlay rendering.
             */
            graphics.setClip(originalClip);
            graphics.setColor(originalColor);
        }

        return null;
    }

    /**
     * Build the smallest canvas region needed for RuneTags chat rendering and
     * interaction so native widget traversal can ignore unrelated interfaces.
     */
    private static Rectangle unionInteractionBounds(
            List<ReferenceHitbox> hitboxes,
            List<LocalHighlight> localHighlights)
    {
        Rectangle result =
                null;

        if (hitboxes != null)
        {
            for (ReferenceHitbox hitbox : hitboxes)
            {
                if (hitbox == null
                        || hitbox.getBounds() == null
                        || hitbox.getBounds().isEmpty())
                {
                    continue;
                }

                result =
                        result == null
                                ? new Rectangle(
                                hitbox.getBounds())
                                : result.union(
                                hitbox.getBounds());
            }
        }

        if (localHighlights != null)
        {
            for (LocalHighlight highlight : localHighlights)
            {
                if (highlight == null
                        || highlight.getBounds() == null
                        || highlight.getBounds().isEmpty())
                {
                    continue;
                }

                result =
                        result == null
                                ? new Rectangle(
                                highlight.getBounds())
                                : result.union(
                                highlight.getBounds());
            }
        }

        if (result != null)
        {
            result.grow(
                    BACKGROUND_HORIZONTAL_PADDING,
                    BACKGROUND_VERTICAL_PADDING);
        }

        return result;
    }

    /**
     * Find visible native widgets that prevent interaction with widgets beneath
     * them, excluding the chat surfaces RuneTags deliberately decorates.
     */
    private List<Rectangle> collectBlockingWidgetBounds(
            Widget chatbox,
            Widget splitPrivateRoot,
            Rectangle interactionBounds)
    {
        if (interactionBounds == null
                || interactionBounds.isEmpty())
        {
            return Collections.emptyList();
        }

        final Widget[] roots =
                client.getWidgetRoots();

        if (roots == null
                || roots.length == 0)
        {
            return Collections.emptyList();
        }

        final List<Rectangle> blockingBounds =
                new ArrayList<>();

        final Set<Widget> visited =
                Collections.newSetFromMap(
                        new IdentityHashMap<>());

        for (Widget root : roots)
        {
            collectBlockingWidgetBounds(
                    root,
                    chatbox,
                    splitPrivateRoot,
                    interactionBounds,
                    blockingBounds,
                    visited,
                    0);
        }

        return blockingBounds;
    }

    private void collectBlockingWidgetBounds(
            Widget widget,
            Widget chatbox,
            Widget splitPrivateRoot,
            Rectangle interactionBounds,
            List<Rectangle> blockingBounds,
            Set<Widget> visited,
            int depth)
    {
        if (widget == null
                || depth > MAX_OCCLUSION_WIDGET_DEPTH
                || !visited.add(
                widget)
                || widget.isHidden())
        {
            return;
        }

        final Rectangle bounds =
                widget.getBounds();

        /*
         * Prune widget subtrees outside the RuneTags interaction region.
         */
        if (bounds != null
                && !bounds.isEmpty()
                && !interactionBounds.intersects(
                bounds))
        {
            return;
        }

        /*
         * Once a no-click-through widget blocks this region,
         * its descendants cannot expose the chat beneath it.
         */
        if (bounds != null
                && !bounds.isEmpty()
                && widget.getNoClickThrough()
                && !belongsToChatPresentation(
                widget,
                chatbox,
                splitPrivateRoot))
        {
            blockingBounds.add(
                    interactionBounds.intersection(
                            bounds));

            return;
        }

        collectBlockingWidgetChildren(
                widget.getChildren(),
                chatbox,
                splitPrivateRoot,
                interactionBounds,
                blockingBounds,
                visited,
                depth + 1);

        collectBlockingWidgetChildren(
                widget.getStaticChildren(),
                chatbox,
                splitPrivateRoot,
                interactionBounds,
                blockingBounds,
                visited,
                depth + 1);

        collectBlockingWidgetChildren(
                widget.getNestedChildren(),
                chatbox,
                splitPrivateRoot,
                interactionBounds,
                blockingBounds,
                visited,
                depth + 1);
    }

    private void collectBlockingWidgetChildren(
            Widget[] children,
            Widget chatbox,
            Widget splitPrivateRoot,
            Rectangle interactionBounds,
            List<Rectangle> blockingBounds,
            Set<Widget> visited,
            int depth)
    {
        if (children == null)
        {
            return;
        }

        for (Widget child : children)
        {
            collectBlockingWidgetBounds(
                    child,
                    chatbox,
                    splitPrivateRoot,
                    interactionBounds,
                    blockingBounds,
                    visited,
                    depth);
        }
    }

    /**
     * A no-click-through Widget belonging to either native chat presentation must
     * not hide RuneTags from the very chat surface it is decorating.
     */
    private static boolean belongsToChatPresentation(
            Widget widget,
            Widget chatbox,
            Widget splitPrivateRoot)
    {
        return sharesWidgetBranch(
                widget,
                chatbox)
                || sharesWidgetBranch(
                widget,
                splitPrivateRoot);
    }

    private static boolean sharesWidgetBranch(
            Widget first,
            Widget second)
    {
        if (first == null
                || second == null)
        {
            return false;
        }

        return isAncestorOrSelf(
                first,
                second)
                || isAncestorOrSelf(
                second,
                first);
    }

    private static boolean isAncestorOrSelf(
            Widget ancestor,
            Widget widget)
    {
        for (Widget current = widget;
             current != null;
             current = current.getParent())
        {
            if (current == ancestor)
            {
                return true;
            }
        }

        return false;
    }

    /**
     * Build the RuneTags paint region by subtracting native no-click-through
     * interface bounds from the current graphics clip.
     */
    private Shape buildUnobscuredClip(
            Shape originalClip,
            List<Rectangle> blockingBounds)
    {
        final Area visibleArea =
                originalClip != null
                        ? new Area(
                        originalClip)
                        : new Area(
                        new Rectangle(
                                0,
                                0,
                                client.getCanvasWidth(),
                                client.getCanvasHeight()));

        if (blockingBounds != null)
        {
            for (Rectangle blocker : blockingBounds)
            {
                if (blocker == null
                        || blocker.isEmpty())
                {
                    continue;
                }

                visibleArea.subtract(
                        new Area(
                                blocker));
            }
        }

        return visibleArea;
    }

    /**
     * Remove native interface regions from one clickable reference rectangle.
     *
     * Rectangle fragments are retained individually because ChatHitboxRegistry
     * stores rectangular hit targets.
     */
    private static List<Rectangle> subtractBlockingBounds(
            Rectangle source,
            List<Rectangle> blockingBounds)
    {
        if (source == null
                || source.isEmpty())
        {
            return Collections.emptyList();
        }

        List<Rectangle> fragments =
                new ArrayList<>();

        fragments.add(
                new Rectangle(
                        source));

        if (blockingBounds == null
                || blockingBounds.isEmpty())
        {
            return fragments;
        }

        for (Rectangle blocker : blockingBounds)
        {
            if (blocker == null
                    || blocker.isEmpty()
                    || fragments.isEmpty())
            {
                continue;
            }

            final List<Rectangle> next =
                    new ArrayList<>();

            for (Rectangle fragment : fragments)
            {
                subtractRectangle(
                        fragment,
                        blocker,
                        next);
            }

            fragments =
                    next;
        }

        return fragments;
    }

    private static void subtractRectangle(
            Rectangle source,
            Rectangle blocker,
            List<Rectangle> output)
    {
        if (source == null
                || blocker == null
                || output == null)
        {
            return;
        }

        final Rectangle intersection =
                source.intersection(
                        blocker);

        if (intersection.isEmpty())
        {
            output.add(
                    source);
            return;
        }

        final int sourceRight =
                source.x
                        + source.width;

        final int sourceBottom =
                source.y
                        + source.height;

        final int intersectionRight =
                intersection.x
                        + intersection.width;

        final int intersectionBottom =
                intersection.y
                        + intersection.height;

        /*
         * Area above the blocker.
         */
        if (intersection.y > source.y)
        {
            output.add(
                    new Rectangle(
                            source.x,
                            source.y,
                            source.width,
                            intersection.y
                                    - source.y));
        }

        /*
         * Area below the blocker.
         */
        if (intersectionBottom < sourceBottom)
        {
            output.add(
                    new Rectangle(
                            source.x,
                            intersectionBottom,
                            source.width,
                            sourceBottom
                                    - intersectionBottom));
        }

        /*
         * Area left of the blocker within the blocker's vertical band.
         */
        if (intersection.x > source.x)
        {
            output.add(
                    new Rectangle(
                            source.x,
                            intersection.y,
                            intersection.x
                                    - source.x,
                            intersection.height));
        }

        /*
         * Area right of the blocker within the blocker's vertical band.
         */
        if (intersectionRight < sourceRight)
        {
            output.add(
                    new Rectangle(
                            intersectionRight,
                            intersection.y,
                            sourceRight
                                    - intersectionRight,
                            intersection.height));
        }
    }

    private void drawLocalHighlights(
            Graphics2D graphics,
            List<LocalHighlight> highlights,
            Rectangle chatboxBounds,
            boolean hasVisibleChatbox,
            Shape unobscuredClip)
    {
        if (highlights == null
                || highlights.isEmpty()
                || !config.highlightBackground())
        {
            return;
        }

        final Color backgroundColor =
                config.selfBackgroundColor();

        if (backgroundColor == null
                || backgroundColor.getAlpha() == 0)
        {
            return;
        }

        graphics.setColor(
                backgroundColor);

        for (LocalHighlight highlight : highlights)
        {
            if (highlight == null
                    || highlight.getBounds() == null)
            {
                continue;
            }

            graphics.setClip(
                    unobscuredClip);

            Rectangle visibleBounds =
                    highlight.getBounds();

            switch (highlight.getSurface())
            {
                case CHATBOX:
                    if (!hasVisibleChatbox
                            || !chatboxBounds.intersects(
                            visibleBounds))
                    {
                        continue;
                    }

                    graphics.clip(
                            chatboxBounds);

                    visibleBounds =
                            chatboxBounds.intersection(
                                    visibleBounds);

                    if (visibleBounds.isEmpty())
                    {
                        continue;
                    }

                    break;

                case SPLIT_PRIVATE:
                    break;

                default:
                    continue;
            }

            graphics.fillRect(
                    visibleBounds.x
                            - BACKGROUND_HORIZONTAL_PADDING,
                    visibleBounds.y
                            - BACKGROUND_VERTICAL_PADDING,
                    visibleBounds.width
                            + (BACKGROUND_HORIZONTAL_PADDING * 2),
                    visibleBounds.height
                            + (BACKGROUND_VERTICAL_PADDING * 2));
        }

        graphics.setClip(
                unobscuredClip);
    }

    private void drawReferenceBackground(
            Graphics2D graphics,
            ReferenceHitbox hitbox,
            String localPlayerName)
    {
        final PlayerReference reference =
                hitbox.getReference();

        final Rectangle bounds =
                hitbox.getBounds();

        if (reference == null || bounds == null)
        {
            return;
        }

        final LocalMentionMatch localMatch =
                localMentionMatcher.match(
                        reference,
                        localPlayerName);

        final boolean isSelf =
                localMatch.isMatchesLocalPlayer();

        /*
         * Reference backgrounds are independent from foreground mention coloring and
         * apply only to the exact mention/tag hitbox. Mention Whole Message therefore
         * does not affect this path.
         */
        final Color backgroundColor =
                isSelf
                        ? config.selfBackgroundColor()
                        : config.otherBackgroundColor();

        /*
         * A fully transparent color disables this reference background.
         */
        if (backgroundColor == null
                || backgroundColor.getAlpha() == 0)
        {
            return;
        }

        final Color previousColor =
                graphics.getColor();

        try
        {
            graphics.setColor(backgroundColor);

            graphics.fillRect(
                    bounds.x - BACKGROUND_HORIZONTAL_PADDING,
                    bounds.y - BACKGROUND_VERTICAL_PADDING,
                    bounds.width + (BACKGROUND_HORIZONTAL_PADDING * 2),
                    bounds.height + (BACKGROUND_VERTICAL_PADDING * 2));
        }
        finally
        {
            graphics.setColor(previousColor);
        }
    }

    private static void drawDottedUnderline(
            Graphics2D graphics,
            Rectangle bounds,
            Color color)
    {
        if (bounds == null || bounds.width <= 0)
        {
            return;
        }

        final Color previousColor =
                graphics.getColor();

        try
        {
            if (color != null)
            {
                graphics.setColor(color);
            }

            final int y =
                    bounds.y + bounds.height - 2;

            /*
             * Segmented Dots
             */
            for (int x = bounds.x;
                 x < bounds.x + bounds.width;
                 x += 3)
            {
//          — 1px dotted segments —
                graphics.fillRect(
                        x,
                        y,
                        1,
                        1);
//          — 2px horizontal segments —
//                graphics.drawLine(
//                        x,
//                        y,
//                        Math.min(x + 1, bounds.x + bounds.width - 1), y);
            }
        }
        finally
        {
            graphics.setColor(previousColor);
        }
    }
}

