    private static String evidenceRatingText(
            Graphics2D graphics,
            String rawRating)
    {
        if (rawRating == null
                || rawRating.trim().isEmpty())
        {
            return "";
        }

        final String rating =
                rawRating.trim();

        final double parsed;

        try
        {
            parsed =
                    Double.parseDouble(
                            rating);
        }
        catch (NumberFormatException exception)
        {
            return rating;
        }

        if (parsed < 0d
                || parsed > 5d)
        {
            return rating;
        }

        final int wholeStars =
                (int) Math.round(
                        parsed);

        final boolean integral =
                Math.abs(
                        parsed - wholeStars) < 0.0001d;

        final Font font =
                graphics.getFont();

        if (integral
                && font != null
                && font.canDisplay('★')
                && font.canDisplay('☆'))
        {
            final StringBuilder stars =
                    new StringBuilder(5);

            for (int i = 0; i < 5; i++)
            {
                stars.append(
                        i < wholeStars
                                ? '★'
                                : '☆');
            }

            return stars.toString();
        }

        return rating + "/5";
    }

