        switch (state)
        {
            case LOADING:
                graphics.setColor(TEXT_SECONDARY);

                graphics.drawString(
                        loadingText(),
                        x,
                        y);
                break;

            case NOT_FOUND:
                graphics.setColor(TEXT_SECONDARY);
                graphics.drawString(
                        "Player not found.",
                        x,
                        y);
                break;

            case ERROR:
                graphics.setColor(OFFLINE);
                graphics.drawString(
                        "HiScores temporarily unavailable.",
                        x,
                        y);
                break;

            case LOCAL:
            default:
                graphics.drawString(
                        "Unable to resolve player name.",
                        x,
                        y);
                break;
        }
    }

