        if (model.getChannelSource() == PlayerSource.PARTY
                && !channelName.regionMatches(
                true,
                0,
                "Party:",
                0,
                "Party:".length()))
        {
            return "Party: " + channelName;
        }

        return channelName;
    }

    private static String locationText(
