    private static int preferredCardWidth(
            Graphics2D graphics,
            QuickProfileModel model,
            boolean showStatus,
            boolean showWorld,
            boolean showLocation,
            boolean showChannel,
            boolean showRank,
            boolean showTags,
            boolean showNote,
            boolean showReports,
            boolean showStats,
            boolean showEhp,
            boolean showEhb,
            boolean showContextMetrics,
            boolean showUnresolvedState)
    {
        final FontMetrics metrics =
                graphics.getFontMetrics();

        int contentWidth =
                ACCOUNT_ICON_SLOT_WIDTH
                        + ACCOUNT_ICON_GAP
                        + metrics.stringWidth(
                        safe(model.getDisplayName()));

        int sectionContentWidth = 0;

        final Font reportTitleFont =
                graphics.getFont()
                        .deriveFont(
                                Font.BOLD);

        final FontMetrics reportTitleMetrics =
                graphics.getFontMetrics(
                        reportTitleFont);

        if (showStatus || showLocation)
        {
            final String statusLine =
                    statusLineText(
                            model,
                            showStatus,
                            showWorld,
                            showLocation);

            sectionContentWidth =
                    Math.max(
                            sectionContentWidth,
                            metrics.stringWidth(statusLine));
        }

        if (showChannel)
        {
            String channelText =
                    channelNameText(model);

            if (showRank)
            {
                channelText +=
                        "  •  " + model.getChannelRank();
            }

            sectionContentWidth =
                    Math.max(
                            sectionContentWidth,
                            metrics.stringWidth(channelText));
        }

        if (showTags
                && model.getTags() != null
                && !model.getTags().isEmpty())
        {
            int tagsWidth = 0;

            for (String tag : model.getTags())
            {
                if (tag == null || tag.trim().isEmpty())
                {
                    continue;
                }

                final int pillWidth =
                        metrics.stringWidth(tag)
                                + (TAG_PILL_PAD_X * 2)
                                + TAG_REMOVE_GAP
                                + TAG_REMOVE_WIDTH;

                if (tagsWidth > 0)
                {
                    tagsWidth += TAG_PILL_GAP_X;
                }

                tagsWidth += pillWidth;
            }

            sectionContentWidth =
                    Math.max(
                            sectionContentWidth,
                            tagsWidth
                                    + TAG_BLOCK_PADDING_X_LEFT
                                    + TAG_BLOCK_PADDING_X_RIGHT);
        }

        if (showNote
                && model.getNote() != null
                && !model.getNote().trim().isEmpty())
        {
            sectionContentWidth =
                    Math.max(
                            sectionContentWidth,
                            Math.min(
                                    NOTE_PREFERRED_TEXT_WIDTH,
                                    NoteTextLayout.widestLogicalLineWidth(
                                            metrics,
                                            model.getNote())));
        }

        if (showReports
                && model.getReportSummaries() != null)
        {
            for (ReportSummary summary
                    : model.getReportSummaries())
            {
                if (summary == null)
                {
                    continue;
                }

                final String sourceTitle =
                        warningSourceTitle(
                                graphics,
                                summary);

                final String countText =
                        summary.getCaseCount() > 1
                                ? summary.getCaseCount() + " CASES"
                                : "";

                int headerWidth =
                        reportTitleMetrics.stringWidth(
                                sourceTitle);

                if (!countText.isEmpty())
                {
                    headerWidth +=
                            10
                                    + metrics.stringWidth(
                                    countText);
                }

                final String ratingText =
                        evidenceRatingText(
                                graphics,
                                summary.getEvidenceRating());

                final String reason =
                        summary.getReason() == null
                                || summary.getReason().trim().isEmpty()
                                ? "Case details unavailable"
                                : summary.getReason().trim();

                int reasonWidth =
                        metrics.stringWidth(
                                reason);

                if (!ratingText.isEmpty())
                {
                    reasonWidth +=
                            10
                                    + metrics.stringWidth(
                                    ratingText);
                }

                final String formattedDate =
                        summary.getFormattedDate();

                final int dateWidth =
                        formattedDate.isEmpty()
                                ? 0
                                : metrics.stringWidth(
                                "Reported: "
                                        + formattedDate);

                final int reportContentWidth =
                        Math.max(
                                headerWidth,
                                Math.max(
                                        reasonWidth,
                                        dateWidth));

                sectionContentWidth =
                        Math.max(
                                sectionContentWidth,
                                reportContentWidth
                                        + (REPORT_PADDING * 2));
            }
        }

        if (showStats)
        {
            sectionContentWidth =
                    Math.max(
                            sectionContentWidth,
                            metrics.stringWidth(
                                    statsText(model)));
        }

        if (showEhp || showEhb)
        {
            sectionContentWidth =
                    Math.max(
                            sectionContentWidth,
                            metrics.stringWidth(
                                    efficiencyMetricsText(model, showEhp, showEhb)));
        }

        if (showContextMetrics
                && model.getContextMetrics() != null)
        {
            for (int i = 0;
                 i < model.getContextMetrics().size();
                 i += 3)
            {
                final StringBuilder row =
                        new StringBuilder();

                for (int j = 0;
                     j < 3
                             && i + j < model.getContextMetrics().size();
                     j++)
                {
                    final ProfileMetricValue metric =
                            model.getContextMetrics().get(i + j);

                    if (j > 0)
                    {
                        row.append("  •  ");
                    }

                    row.append(metric.getLabel())
                            .append(": ")
                            .append(metric.getValue());
                }

                sectionContentWidth =
                        Math.max(
                                sectionContentWidth,
                                metrics.stringWidth(
                                        row.toString()));
            }
        }

        if (sectionContentWidth > 0)
        {
            contentWidth =
                    Math.max(
                            contentWidth,
                            sectionContentWidth
                                    + (SECTION_PADDING * 2));
        }

        if (showUnresolvedState)
        {
            contentWidth =
                    Math.max(
                            contentWidth,
                            metrics.stringWidth(
                                    unresolvedStateText(model)));
        }

        return Math.max(
                CARD_MIN_WIDTH,
                Math.min(
                        CARD_MAX_WIDTH,
                        contentWidth + (PADDING * 2) + 8));
    }

    private static String ellipsize(
            Graphics2D graphics,
            String text,
            int maxWidth)
    {
        if (text == null)
        {
            return "";
        }

        final FontMetrics metrics =
                graphics.getFontMetrics();

        if (metrics.stringWidth(text) <= maxWidth)
        {
            return text;
        }

        final String ellipsis = "…";

        int end =
                text.length();

        while (end > 0)
        {
            final String candidate =
                    text.substring(0, end)
                            + ellipsis;

            if (metrics.stringWidth(candidate) <= maxWidth)
            {
                return candidate;
            }

            end--;
        }

        return ellipsis;
    }

    private static String safe(String value)
    {
        return value == null || value.isEmpty()
                ? "Unknown Player"
                : value;
    }
}

package com.runetags.overlay;

import com.runetags.Configurations;
import com.runetags.config.MinimapIndicatorMode;
import com.runetags.target.TargetController;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

public class TargetMinimapOverlay extends Overlay
{
    private final Client client;
    private final Configurations config;
    private final TargetController targetController;

    public TargetMinimapOverlay(
            Client client,
            Configurations config,
            TargetController targetController)
    {
        this.client = client;
        this.config = config;
        this.targetController = targetController;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(OverlayPriority.HIGH);
    }

    private static void drawMinimapIndicator(
            Graphics2D graphics,
            Point point,
            Color color,
            int diameter)
    {
        if (point == null || diameter <= 0)
        {
            return;
        }

        final Color oldColor =
                graphics.getColor();

        try
        {
            final int radius =
                    diameter / 2;

            graphics.setColor(Color.BLACK);
            graphics.fillOval(
                    point.getX() - radius,
                    point.getY() - radius + 1,
                    diameter,
                    diameter);

            graphics.setColor(color);
            graphics.fillOval(
                    point.getX() - radius,
                    point.getY() - radius,
                    diameter,
                    diameter);
        }
        finally
        {
            graphics.setColor(oldColor);
        }
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        final MinimapIndicatorMode indicatorMode =
                config.minimapIndicator();

        if (!config.targetPlayerOption()
                || indicatorMode == MinimapIndicatorMode.OFF
                || client.getGameState() != GameState.LOGGED_IN)
        {
            return null;
        }

        final Player target = targetController.getTargetPlayer();

        if (target == null)
        {
            return null;
        }

        final Point minimapPoint = target.getMinimapLocation();

        if (minimapPoint != null)
        {
            drawMinimapIndicator(
                    graphics,
                    minimapPoint,
                    config.minimapDotColor(),
                    indicatorMode.getDiameter());
        }

        return null;
    }
}

package com.runetags.overlay;

import com.runetags.Configurations;
import com.runetags.config.TargetMode;
import com.runetags.records.LocalPlayerRecordService;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;
import net.runelite.client.util.Text;

/**
 * Scene presentation for locally favorited players.
 *
 * Favorite names use RuneTags gold while scene indicators reuse the configured
 * Target Mode. TargetOverlay has higher priority, so an actively targeted
 * Favorite retains Target as the stronger live interaction state.
 */
public class FavoriteOverlay extends Overlay
{
    private static final int OUTLINE_WIDTH = 2;
    private static final int OUTLINE_FEATHER = 4;
    private static final int NAME_HEIGHT_OFFSET = 40;

    private final Client client;
    private final Configurations config;
    private final LocalPlayerRecordService localPlayerRecordService;
    private final ModelOutlineRenderer modelOutlineRenderer;

    public FavoriteOverlay(
            Client client,
            Configurations config,
            LocalPlayerRecordService localPlayerRecordService,
            ModelOutlineRenderer modelOutlineRenderer)
    {
        this.client = client;
        this.config = config;
        this.localPlayerRecordService =
                localPlayerRecordService;
        this.modelOutlineRenderer =
                modelOutlineRenderer;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
        setPriority(OverlayPriority.MED);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showFavorites()
                || localPlayerRecordService == null
                || client.getGameState() != GameState.LOGGED_IN)
        {
            return null;
        }

        final WorldView worldView =
                client.getTopLevelWorldView();

        if (worldView == null)
        {
            return null;
        }

        final TargetMode mode =
                config.targetMode() != null
                        ? config.targetMode()
                        : TargetMode.OFF;

        final Color favoriteColor =
                configuredFavoriteColor();

        final Color sceneColor =
                sceneColor(
                        favoriteColor);

        for (Player player : worldView.players())
        {
            if (player == null
                    || player.getName() == null
                    || player.getName().trim().isEmpty()
                    || !localPlayerRecordService.isFavorite(
                    player.getName()))
            {
                continue;
            }

            if (mode.showsOutline())
            {
                modelOutlineRenderer.drawOutline(
                        player,
                        OUTLINE_WIDTH,
                        sceneColor,
                        OUTLINE_FEATHER);
            }

            if (mode.showsTile())
            {
                final Polygon tilePoly =
                        player.getCanvasTilePoly();

                if (tilePoly != null)
                {
                    OverlayUtil.renderPolygon(
                            graphics,
                            tilePoly,
                            sceneColor);
                }
            }

            drawFavoriteName(
                    graphics,
                    player,
                    favoriteColor);
        }

        return null;
    }

    private Color configuredFavoriteColor()
    {
        final Color configured =
                config.favoriteColor();

        return configured != null
                ? configured
                : new Color(255, 205, 70);
    }

    private static Color sceneColor(
            Color color)
    {
        final Color source =
                color != null
                        ? color
                        : new Color(255, 205, 70);

        return new Color(
                source.getRed(),
                source.getGreen(),
                source.getBlue(),
                Math.min(200, source.getAlpha()));
    }

    private static void drawFavoriteName(
            Graphics2D graphics,
            Player player,
            Color favoriteColor)
    {
        final String rawName =
                player.getName();

        if (rawName == null
                || rawName.isEmpty())
        {
            return;
        }

        final String name =
                Text.sanitize(
                        rawName);

        final Point textLocation =
                player.getCanvasTextLocation(
                        graphics,
                        name,
                        player.getLogicalHeight()
                                + NAME_HEIGHT_OFFSET);

        if (textLocation != null)
        {
            OverlayUtil.renderTextLocation(
                    graphics,
                    textLocation,
                    name,
                    favoriteColor);
        }
    }
}

